Fraude contable (inciso i):
El delito de fraude contable en la administración de las personas jurídicas se configura
con la ocultación de la verdadera situación de la empresa frente a los accionistas, audito
res o terceros interesados mediante el falseamiento de los instrumentos contables.
Este delito no se configura únicamente con el falseamiento de los estados financieros, como
el estado de gananciasy pérdidas, sino también con la modificación, en general, de las par
tidas contables, sean del balance o no. A diferencia de la modalidad de falsas informaciones
sociales, el fraude contable no se configura a partir del suministro de información falsa sino
del ocultamiento de la situación (económica-financiera) de la persona jurídica.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 959 of 1506 --

Tema 6: Temas de la Especialidad Penal
d) El reparto de utilidades inexistentes (inciso 5):
El reparto de utilidades inexistentes no es propiamente la conducta típica, sino fraguar
los balances financieros de la empresa para reflejar y distribuir utilidades inexistentes.
Esta modalidad busca impedir el reparto indebido del capital social entre los socios per
judicando a la persona jurídica con la reducción ilegal de su patrimonio.
Si bien no es necesario que las utilidades efectivamente se distribuyan, el fraude en los
balances debe haber generado un peligro de perjuicio patrimonial, que en el caso especí
fico se configura por el peligro de distribución de utilidades inexistentes a los accionistas.
En ese sentido, es necesario para su configuración que se haya aprobado por el órgano
correspondiente el balance fraguado.
e) El agiotaje societario (inciso 3):
Consiste en promover por cualquier medio fraudulento falsa cotizaciones de acciones,
títulos valores o participaciones. Esta modalidad está configurada como un delito de do
minio por cuanto se castiga a los directivos o administradores de una persona jurídica por
promover mediante actos de simulación falsos valores a las acciones, participaciones o
títulos de la empresa lo que significa un abuso de las facultades de administración para
perjudicar a terceras personas.
Tipicidad subjetiva: Teniendo en cuenta que nos encontramos ante un delito de infracción
de deber del funcionario de una institución privada, es evidente que la conducta de éste debe
ser dolosa.
7.10. Delito de usurpación
Descripción normativa:
“Art. 202 GR Será reprimido con pena privativa de libertad no menor de dos ni mayor de cinco añosmm
1. El que, para apropiarse de todo o en parte de un inmueble, destruye o altera los linderos del mismo.
2. El que, con violencia, amenaza, engaño o abuso de confianza, despoja a otro, total o parcialmente,
de la posesión o tenencia de un inmueble o del ejercicio de un derecho real.
3. El que, con violencia o amenaza, turba la posesión de un inmueble.
4. El que, ilegítimamente, ingresa a un inmueble, mediante actos ocultos, en ausencia del poseedor o con pre
cauciones para asegurarse el desconocimiento de quienes tengan derecho a oponerse.
La violencia a la que se hace referencia en los numerales 2 y 3 s e ejerce tanto sobre las personas como sobre
los bienes."
Bien jurídico protegido: El delito de usurpación en palabras del maestro Muñoz Conde: “la usur
pación no es sino una forma de ataque contra el patrimonio inmobiliario, por lo que el bien jurí
dico protegido es el tranquilo disfrute de las cosas inmuebles, entendiéndose como ausencia de
perturbación en el ejercicio de la posesión o de cualquier derecho real sobre las mismas”
Tipicidad objetiva: La primera modalidad de usurpación consiste en destruir o alterar los lin
deros del bien inmueble. Lindero es toda señal natural o artificial que sirve para establecer
los límites de un bien inmueble. Los linderos no serán pues el bien jurídico protegido de este
delito, sino más bien el medio comisivo del mismo.
