• Destruir significa: Deshacer, inutilizar algo, en este caso será pues los linderos de un bien
mueble, con la intención de acrecentar el bien propio, perjudicando así al dueño del in
mueble colindante.
• Alterar los linderos implica la acción de cambiar de posición, es decir, mover el lindero
de su posición original hacia la parte interna del inmueble colindante.
Al decir la ley que esta acción debe darse con el objeto de apropiarse de todo o parte de un
inmueble implica que no será delito, si es que quien mueve el lindero hacia el interior de su
propio inmueble, afectándose así mismo no será delito.
La segunda modalidad de usurpación consiste despojar a la víctima total o parcialmente de la
posesión o tenencia de un inmueble o del ejercicio de un derecho real, empleando para ello,
violencia, amenaza o abuso de confianza. El verbo recto del comportamiento es “despojar” en
tendido como la acción por la cual el agente despoja, quita, arrebata, desposee o usurpa el in
mueble o el ejercicio de un derecho real del sujeto pasivo. Por otro lado, la “posesión” viene a ser
el despliegue de algunas de las facultades del derecho de propiedad, en mérito al poder de he
cho que se tiene sobre el inmueble, estándole restringido solo la facultad de disposición que sí la
tiene el propietario aun cuando se le presuma como tal mientras no se le pruebe lo contrario124.
Ahora, el derecho penal no protege toda conducta lesiva contra el derecho de posesión, sino
aquellas que estima especialmente peligrosas cuando media en el despojo el uso de violen
cia, amenaza o abuso de confianza. Por “violencia” se entiende la energía física ejercida porel
autor sobre la víctima para arrebatarle o despojarle su inmueble. Por “amenaza” se entiende
como el anuncio de un mal o perjuicio inminente para la víctima, cuya fin al idad es intim idar
la, para lo cual dicha amenaza debe ser idónea o eficaz. Finalmente, por “abuso de confianza”
se entiende como el mal uso que hace el agente de laconfianzay buena fe de la víctima, para
luego logra traicionarloy despojarlo de la posesión de un inmueble125.
El tercer comportamiento consiste en turbar la posesión del inmueble. La turbación consiste
en la realización de actos materiales que, sin despojar al poseedor, suponen una limitación de
la pacífica posesión de un inmueble. No se comprende la turbación de la mera tenencia, por
lo que este caso será un hecho atípico. Los medios para realizar la turbación de la posesión son
la violencia o amenaza. La violencia se debe entender como la fuerza física que se ejerce sobre
la persona, suficiente para vencer su resistencia. La amenaza es el anuncio del propósito de
causar un mal a otro.
La cuarta modalidad bien podría denominarse usurpación subrepticia o alevosa, pues el delin
cuente se aprovecha de la ausencia del poseedor, quien muchas veces se aleja de su casa por un
día o varios meses, sin dejar guardián. No es el supuesto en que se rompen chapas o candados
en ausencia del titular. En esta nueva modalidad el agente puede valerse de llaves duplicadas,
ganzúas u otros artificios que facilitan la usurpación, ocultamente y a escondidas. También, el
agente aprovechará el desconocimiento que tenga lavíctimade las acciones usurpatorias, loque
impedirá que ejerza resistencia u oposición. Es decir, la acción típica no se comete a la vista de
