7.11. Delito de daños
Descripción normativa:
"Ari. 205 CP. El que daña, destruye o inutiliza un bien, mueble o inmueble, total o parcialmente ajeno,
será reprimido con pena privativa de libertad no mayor de tres años y con treinta a sesenta días-multa."
Bien jurídico protegido: Con respecto al bien jurídico protegido, debemos afirm ar que lo que
se pretende proteger con este delito subsumldo dentro de “daños a la propiedad” es el patri
monio de manera genéricayel derecho de propiedad-de manera específica-que todos tene
mos respecto de nuestros bienes, sean estos muebles o inmuebles.
Tipicidad objetiva: El delito de daños se encuentra tipificado en el artículo 205o de nuestro
Código Penal y sanciona al que “daña, destruye o inutiliza un bien, mueble o inmueble, total o
parcialmente ajeno”. De la lectura del tipo penal se advierte que el presente delito denunciado
puede configurarse hasta por tres formas o modalidades:
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 962 of 1506 --

a) La primera modalidad se presenta cuando el sujeto activo daña, menoscaba, estropea o
deteriora un bien mueble o inmueble que total o parcialmente pertenece a otra persona
quien por tal circunstancia se convierte en sujeto pasivo de la acción. En términos claros,
dañar consiste en dism inuirel valor patrimonial de un bien comprometiendo fundamen
talmente el aspecto corporal con el cual se encuentra construido. Con su acción, el sujeto
activo no busca destruir ni inutilizar el bien, lo único que busca es deteriorarlo para que
no siga cumpliendo su función normal y natural.
b) La segunda modalidad se da cuando el agente destruye o elimina un bien mueble o in
mueble que de manera total o parcial pertenece a otra persona. Por destruir debemos
entender que es el acto de desaparecer el valor patrimonial de un bien, afectando tanto
el aspecto material como funcional. En este supuesto, el sujeto activo no solo busca dete
riorar o inutilizar el bien, sino destruirlo o desaparecerlo.
c) Por último, la tercera modalidad se presenta cuando el agente inutiliza o inhabilita un
bien mueble o inmueble que total o parcialmente pertenece a otra persona. El término
inutilizarconsisteen provocarla pérdida de la capacidad del bien para ejecutarsufunción
natural, sin que exista alguna lesión o menoscabo en su aspecto material. En este supues
to, el sujeto activo no busca dañar ni destruir el bien, sino loque busca es inutilizarlo para
que no pueda seguircumpliendo con su función habitual.
Tipicidad subjetiva: El tipo penal requiere la presencia de dolo en la conducta del autor. A
diferencia del hurto o el robo, en el delito de daños el autor no posee ánimo de lucro, sino la
voluntad de destruir, estropear o inutilizar una cosa mueble o inmueble ajena.
