Tema 6: Temas de la Especialidad Penal
8. DELITOS CONTRA LA VIDA, EL CUERPO Y LA SALUD
8.1. HOMICIDIO
El homicidio es la privación de la vida de una persona causada por otra u otras personas, con
siste en la privación injusta de la vida de una persona por parte de otra persona.
Dentro de la teoría del delito se da una definición que es: la acción comisiva u omisiva, tip ifi
cada en la ley penal, de matar a otro, antijurídica y culpablemente Debemos precisar que la
figura del homicidio requiere de tres elementos básicos que son los siguientes:
a) Una vida humana preexistente al hecho.
b) Una acción igualmente humana que determina la extinción de esa vida.
c) Un riguroso nexo de causalidad entre la acción humanay la muerte del sujeto pasivo.
Bien jurídico protegido: El bien jurídico protegido es la vida humana, comprendida como
unidad bio-psico-social inescindible. Su protección está determinada por el art. 2o de nuestra
Constitución Política. La vida se protege de manera absoluta, independiente de la estimación
social que está merezca y de la voluntad del individuo que es su titular, por cuanto es un bien
indispensable.
1. Homicidio Simple
Este tipo penal se circunscribe estrictamente a la muerte que una persona le causa a otra sin
que en el evento criminal concurran circunstancias especiales vinculadas con la modalidad o
móvil del acto o con las vinculaciones de parentesco habidas entre víctim ay victimario que le
den gravedad o atenuación al tipo base.
Descripción normativa:
“Art, 106 CP Ei que mata a otro será reprimido con pena privativa de libertad no menor de seis ni mayor
de veinte años."
Tipicidad objetiva: En cuanto a la tipicidad objetiva, la conducta típica consiste en m atar a
otra persona, siendo la acción dirigida a extinguir o acortar el período de vida de otra persona,
vale decir, toda acción u omisión que cause la muerte o la adelante en el tiempo. La im puta
ción objetiva del resultado de la conducta homicida exige una relación de causalidad entre la
acción del sujeto activo y el resultado (muerte) en la víctima, siempre y cuando, la conducta
haya creado un riesgo no permitido para el bien jurídico-vida independiente-o hayaaumen-
tado uno ya existente, trayendo como consecuencia el resultado letal126.
Elementos constitutivos del delito de homicidio:
a. La preexistencia de la vida humana.- Para que se cometa el delito de homicidio necesa
riamente el sujeto pasivo debe estar con vida. Es suficiente la vida, no importa el grado de
