capacidad para vivir; si el recién nacido está vivo, aunque no tenga vitalidad (aptitud para
continuar la vida) tal existencia es real y no aparente.
b. Extinción de la vida humana.- El homicidio es un delito típicamente material o de re
sultado externo, entonces para que se cumpla o se materializa este delito se realiza actos
que pongan fin a la vida de una persona, “la materialidad de este delito se deduce de la
perfecta coincidencia entre el resultado jurídico (anulación del derecho a la vida y el re
sultado material (muerte)”.
SI sólo se produce peligro a la vida o causa lesiones entonces puede reputarse como ten
tativa. Ejemplo:
Acción propiamente dicha.- El homicidio se comete por acción Strictosensu, cuando
por ejemplo se asesta una puñalada, se suministra una sustancia química para obte
ner el efecto letal requerido.
Comisión por omisión.- en el caso del lazarillo que no impide que el ciego, su amo,
se precipite al abism o-viene a ser la acción con la cual se le quita intencional mente
la vida.
c. Relación de casualidad.- La acción y el resultado, es decir la muerte debe ser resultado
o producto de la acción delictiva. En conclusión el tipo penal y la finalidad de la norma
Inherente, fundamenta la naturaleza de vinculación entre conductay resultado, a fin de
lograr relevancia para el derecho penal. Que la muerte sea causada por acción, o atribuida
por comisión omisiva.
Tipicidadsubjetiva: En cuanto a la tipicidadsubjetiva, el ilícito penal de hom lcidiosim ple re
quiere la concurrencia de dolo, entendido como el conocimiento válido del autor del contexto
social de su acc¡ón127y la voluntad de querer la realización de la conducta. Se exige al autor lo
que "debía conocer”, mas no lo que meramente “sabía” o “podía conocer” al momento de obrar
en un contexto social determinado; vale decir, el sujeto activo toma la decisión de realizar un
hecho a pesar de conocer todas las circunstancias fácticas que convertirán ese hecho en un he
cho típico128. Es por el lo que « (...) no cualquier forma o manifestación del pensamiento o conocimiento
humano puede configurar ese componente subjetivo indispensable para el juicio de tipicidad129(...)».
Medios de ejecución.- Cualquier medio capaz de producir la muerte tienen relevancia
jurídica, a excepción que aquellos que determinan una agravación especial; importa la
eficacia para matar. Se ejecuta mediante la acción, omisión, comisión por omisión. Ejem
plo: se deja de atender a un paciente en un hospital.
Medios directos e indirectos: Los primeros son aquellos que actúan directamente sobre
la víctima entre ellos pueden ser armas blancas, de fuego, los gases asfixiantes, lacorrien-
