Medios materiales: (Físicos), son los que actúan atacando el organismo en su integridad,
entre ellos tenemos las armas propias, destinadas normalmente al ataque o la defensa o
las impropias, son aquellos instrumentos destinadas a otros fines pero que pueden tener
