Medios psicológicos: Es decir el sujeto utiliza o se vale de medios psicológicos como el
que utiliza los medios físicos habituales, es decir el sujeto activo ha realizado de las cir
cunstancias)/ que unidas a su acción, deben producir la muerte.
Tentativa: Teniendo en cuenta que nos encontramos ante un delito de resultado en donde se
exige la muerte de una persona, es posible la tentativa.
Concurso de delitos: El homicidio puede concurrir con otros delitos, como lesiones, aborto, o
contra el patrimonio que no configure una agravación, pues es diferente que un sujeto robe y
mate, a que mate para robar.
2. Parricidio
El parricidio es el homicidio agravado por el conocimiento que tuvo el agente del vínculo de
parentesco consanguíneo en línea recta que lo unía a la víctima o por el conocimiento del
vínculo jurídico existente con ella por acto de matrimonio civil, adopción civil o concubinato
legalmente amparado.
Descripción normativa:
"Art. 107 CP. "El que, a sabiendas, mata a su ascendiente, descendiente, natural o adoptivo, o a una
persona con quien sostiene o haya sostenido una relación conyugal o de convivencia, será reprimido
con pena privativa de libertad no menor de quince años.
La pena privativa de libertad será no menor de veinticinco años, cuando concurra cualquiera de las
circunstancias agravantes previstas en los numerales 1, 2, 3 y 4 d e l artículo 108."
En caso de que el agente tenga hijos con la víctima, además será reprimido con la pena de inhabilitación pre
vista en el inciso 5 del artículo 36."
Es un tipo especial impropio, por cuanto la posibilidad de autoría está limitada sólo a un de
terminado círculo de autores. No puede cometer el delito cualquier persona, sino únicamente
aquellas en quienes concurre la especial calidad exigida por ley como son los ascendientes,
descendientes, cónyuge o concubino. Se entiende al parricidio como un delito especial im pro
pio dado que guarda correspondencia con un delito común, el homicidio simple. Esta peculia
ridad del tipo trae consigo consecuencias fundamentales a nivel de la autoríay participación.
Es un tipo autónomo, dado que goza de una jerarquía valorativa propia respecto a los demás
delitos contra la vida. La construcción del tipo de parricidio, a diferencia del homicidio simple,
posee un doble dato valorativo, por un lado la prohibición de m atary por el otro la prohibición
de matar al pariente (ascendiente, descendiente, cónyuge o concubino).
Si bien es cierto que parece indudable la mayor gravedad del injusto en el parricidio respecto a las
demás figuras, hecho que sería una honda repercusión en lo que atañe a la autoríay participación
