UBILEX
del delito sub-examine, también es meridianamente claro que la resolución del problema aludido
tiene que arreglarse según prescripciones contenidas en la parte general (artículo 26o).
Al igual que el homicidio simple el parricidio es un tipo no referenciado, no requiere ni alude
a una especial circunstancia de tiempo, lugar, modo u ocasión. Asimismo, el tipo no se detiene
en exigir una determinada utilización de medios o instrumentos por lo que ha de entender
una amplia libertad en la precisión de los medios comisivos.
Es un tipo de resultado, dado que produce un cambio en el mundo exterior: la muerte del
pariente. Esta modificación es de naturaleza física, dado que causa la muerte a una personay
es notoriala separación espacio-temporal entre acción y resultado.
Porsu redacción es un tipo monosubjetivo, basta que la muerte sea producida por una perso
na, siemprey cuando sea ascendiente, descendiente, cónyuge o concubino.
Tipicidad objetiva: En cuanto al tipo objetivo, la conducta consiste en matar a una persona,
de igual manera que en el delito de homicidio simple, con la diferencia que nos encontramos
ante un delito especial impropio en donde la autoría está limitada sólo a un determinado cír
culo de autores en relación a parentescos sanguíneosy jurídicos130. No puede cometer el delito
cualquier persona, sino únicamente aquella en la que concurre la cualidad especial exigida
porel tipo penal.
Tipicidad subjetiva: En cuanto al tipo subjetivo, el delito de parricidio es esencialmente doloso,
dado a que se exige que el autor actúe “a sabiendas” de que su conducta constituye un riesgo
para la vida de víctima y, además, que sea consciente de la existencia del parentesco de ascen
dencia, descendencia, matrimonial o concubinato con ésta (identificación de la víctima)131.
Penalidad agravante: Cuando concurra cualquiera de las circunstancias agravantes previstas en
los numerales 1,2,3y 4 del artículo 108o la pena privativa de libertad no será menor de 25 años.
3. Homicidio calificado
Es un homicidio premeditado pero con el agregado de factores o elementos que le otorgan
una especial gravedad y que por lo mismo hacen lugar a una represión más severa. Esos ele
mentos de agravación que acreditan una acentuada perversidad en el agente. Son aquellos
homicidios en que concurren situaciones particularmente graves en cuanto a los móviles que
determinan su comisión o los medios empleados para ejecutarlo.
Descripción normativa:
“Art. 108 CP Homicidio calificado
'' Será reprimido con pena privativa de libertad no menor de quince años el que mate a otro concurriem
do cualquiera de las circunstancias siguientes;
7. Por ferocidad, codicia, lucro o por placer
2. Para facilitar u ocultar otro delito.
3. Con gran crueldad o alevosía.
4. Por fuego, explosión o cualquier otro medio capaz de pofter en peligro la vida o salud de otras personas",
