Tema 6: Temas de la Especialidad Penal
Tipicidadobjetiva: En cuanto a la tipicidad objetiva, la conducta típica consiste en quitar lavida
a otra persona, concurriendo cualquiera de las circunstancias descritas en el tipo penal, además
de los elementos objetivos del delito de homicidio simple, por lo que nos encontramos ante tipo
cualificado del tipo básico. El presente ilícito penal no exige una condición especial en el suje
to activo, por lo que nos encontramos ante un delito común132. Teniendo en cuenta que las cir
cunstancias especiales que caracterizan al asesinato u homicidio calificado se refieren a medios
peligrosos o revelan una especial maldad o peligrosidad en la personalidad del sujeto activo, se
puede definir dicho ilícito como la acción de matar que realiza el agente sobre la víctima hacien
do uso de medios peligrosos o por efectos de maldad o peligrosidad de su personalidad.
Circunstancias agravantes: El a rticu ló lo s0 que señala los casos en que el homicidio adquiere
para nuestra ley el nivel de asesinato, incurre en una nueva y penosa incorrección al dar el
nombre de circunstancias a factores sumamente significativos de agravación. No puede de
cirse que la ferocidad, el lucro, la gran crueldad o la alevosía son nada más que circunstancias.
Son, por el contrario elementos consustanciales de la figura delictiva calificadas o agravada.
Las circunstancias que le dan particularidad al asesinato son del siguiente orden:
í. Asesinato por Ferocidad.- La Ferocidad alude a la ¡dea de fiereza y crueldad; a su vez fie
reza importa inhum anidady crueldad en el ánimo, con el empleo del vocablo en mención
el legislador pretende resaltar el profundo reproche al homicidio que se comete con in
humanidady una motivación cercana al salvajismoy a la barbarie. El asesinato cometido
con el móvil de ferocidad requiere ser probado no basta desconocer la motivación del
autor para plantear la presencia de la ferocidad. A pesar de ser un elemento de natura
leza psíquica, íntima y subjetiva requiere una determinada situación objetiva y externa
susceptible de verificación con los instrumentos y medio de prueba adecuados. Aquí el
peritaje psiquiátrico nos brinda un dato invalorable de gran precisión.
ii. Asesinato por Lucro.- El lucro en el asesinato puede ser susceptible de diversas interpre
taciones dogmáticas en virtud a la poli funcionalidad semántica del término. En una pri
mera interpretación extensa, el lucro puede aludir a toda forma de ganancia o provecho
alcanzado o por lograr, consecuencia de la producción de la muerte.
iii. Asesinato por Placer.- Según el Diccionario de la Real Academia el significado de la pa
labra placer denota la experimentación de “una sensación agradable o la presencia de
un ánimo contento”. Si se acepta, como se hace aquí, la tesis del sentido literal posible,
como límite de la interpretación jurídica, no cabe duda que la referencia legislativa del
matar "por placer” da lugar a una circunstancia agravante sumamente amplia en cuanto
a contenido y variedad de interpretaciones que quizás no solo desborde, sino abrace a las
otras modalidades típicas.
ív. Para facilitar un delito (delito medio).- En el homicidio empleado como medio, el agen
te dirige su voluntad final hacia la perpetración de otros delitos. La agravante aparece
aquí especificada en el desprecio, por parte del agravante, del significado ético-social pri-
merísima que tiene lavida humana.
v. Para ocultar otro delito.- Es esta hipótesis la conexión teleológica es consecuencial. El agente
mata con la finalidad determinada de ocultar "strictu sensu”, vale decir, cuando el otro delito
