vii. Asesinato con gran crueldad.- Cuando «(...) el su je to activo pro d u ce la m u e rte de su v íc tim a
h acié n d o le s u f r ir en fo rm a in e x p lica b le e in n e c e sa ria (...) a cre ce n ta r d e lib e ra d a e in h u m a n a m e n t e el
