del sufrimiento innecesario de la víctima, para lo cual se necesita que: i) los actos de esta
gravante se desplieguen cuando la víctima esté con vida, quedando excluidos los actos de
ensañamiento contra el cadáver; y, ii) la víctima debe estar consciente en el momento que
el agente despliega su acción homicida de manera cruel,ya que solo en ese estado puede
experimentar el dolor o sufrimiento136.
3.1. Homicidio calificado por la condición oficial del agente (Art. 1 0 8 -A C.P.):
El que mata a un miembro de la Policía Nacional, de las Fuerzas Armadas, a un magistrado
del Poder Judicial o del Ministerio Público o a un miembro del Tribunal Constitucional o a
cualquier autoridad elegida por mandato popular, en el ejercicio de sus funciones o como
consecuencia de ellas, será reprimido con pena privativa de libertad no menor de veinte años.
4. Feminicidio
El feminicidio es un acto concreto realizado por un hombre suprimiendo la vida de una mujer.
Es ciertamente el reflejo de un conjunto de condiciones estructurales, que van más allá de la
conducta homicida del sujeto activo, y que expresan una relación asimétrica de poder entre el
hom brey la mujer, en desmedro de esta última.
Si bien por exigencias de un derecho penal de acto, se debe castigar únicamente las manifes
taciones concretas del autor137, en contra de la norma penal que prohíbe atentar contra la vida
