Tema 6: Temas de la Especialidad Penal
de la mujer, el legislador ha considerado necesario ubicar el ataque a la vida de la mujer, en un
contexto situacional determinado. De esta manera ha estimado que la violencia desencadenan
te de la muerte de la víctima, no es un episodio, no es una eventualidad, sino el lamentable re
sultado de un conjunto de circunstancias precedentes,y parte de construcciones culturales que
han alimentado el resultado fatal. Por imperativos del mandato de determinación, es menester
delimitar cada uno de ellos, en concordancia claro está con el ordenamiento jurídico en general.
El artículo 8 o (b), de la Convención interamericana para Prevenir, Sancionary Erradicar la Vio
lencia contra la Mujer “BELÉM DO PARÁ” obliga a los Estados Partes a adoptar medidas espe
cíficas para m odificar los patrones socio culturales de conducta de hombres y mujeres para
contrarrestar perjuicios y costumbres y todo tipo de prácticas que se basen en la premisa de la
inferioridad o superioridad de cualquiera de los géneros o en los papeles estereotipados para
el hom brey la m ujerque legitiman o exacerban la violencia contra la mujer.
En esa línea se tipifica el delito de fem inicidioy debe entenderse como la más extrema mani
festación de violencia contra la mujer porsu condición de tal.
4.1. Descripción normativa
Tipo básico:
(Primer párrafo).- Feminicidio Será reprimido con pena privativa de libertad no rn&p&mtm
veinte años el que mata a una mujer por su condición de tal, en cualquiera de los siguientes contextos:
1. Violencia familiar
2. Coacción, hostigamiento o acoso sexual.
:3, Abuso de pode/y confianza o de cualquier otra posición o relación que le confiera autoridad al agente.
4. Cualquier forma de discriminación contra la mujer; independientemente de que exista o haya existido una
relación conyugal o de convivencia con el agente.
Tipo agravado:
Art. 108-B (segundo párrafo).-La pena privativa de libertad será no menor de treinta años c u a n ftflS p J
curra cualquiera de las siguientes circunstancias agravantes:
I . Si la víctima era menor de edad o adulta mayor.
2. Si la víctima se encontraba en estado de gestación.
3. Si la víctima se encontraba bajo cuidado o responsabilidad del agente.
4. Sí la víctima fue sometida previamente a violación sexual o actos de mutilación.
5. Si al momento de cometerse el delito, la víctima tiene cualquier tipo de discapacidad.
6. Si la víctima fue sometida para fines de trata de personas o cualquier tipo de explotación humana.
7. Cuando hubiera concurrido cualquiera de las circunstancias agravantes establecidas en el artículo 108.
8. Si, en el momento de cometerse el delito, estuviera presente cualquier niña, niño o adolescente.
9. Si el agente actúa en estado de ebriedad, con presencia de alcohol en la sangre en proporción mayor de 0.25
gramos-litro, o bajo efecto de drogas tóxicas, estupefacientes, sustancias psicotrópicas o sintéticas.
La pena será de cadena perpetua cuando concurran dos o más circunstancias agravantes.
En todas las circunstancias previstas en tanto en el tipo básico como las formas agravadas, se impondrá la
pena de inhabilitación.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 969

-- 970 of 1506 --

UBILEX
Tipo objetivo138
Sujeto activo.- Solo un hombre podría actuar contra la mujer, produciéndole la muerte, por su
género o su condición de tal. Esta motivación excluye entonces que una mujer sea sujeto activo.
Sujeto pasivo.- La identificación del sujeto pasivo del feminicidio es más clara. La conducta
homicida del varón recae sobre una mujer.
En el caso del sujeto pasivo puede ser una mujer adulta, menor de edad o adulta mayor. En
el primer caso, la muerte de la víctima configura un feminicidio simple. En los últimos casos,
dicha circufistancias, califican la conducta feminicida.
Bien jurídico protegido.- Es la vida humana en el femicidio simple, en el femicidio agravado,
por el modo de comisión, las conductas previas a la muerte o la condición misma de la víctima,
concurren otros intereses jurídicos adicionales o independientes que deben considerarse. En
el caso deque la victimase haya encontrado gestando, se protege también la vida del feto que
también es suprimida. En el caso que la víctima haya sido violada o mutilada previamente, se
vulnera también la libertad (indemnidad) sexual y la integridad física, respectivamente. Si el
sometimiento contextual a la conducta feminicida se realizó con fines de trata deseres huma
nos o cualquier forma de explotación, se protege también la libertad personal. Si la conducta
feminicida se realiza a sabiendas de la presencia de los hijos de la víctima o de niños que estén
al cuidado del feminicida, se protege la integridad sicológica de dichas personas. En resumen,
en estos casos si se puede sostener que el delito de feminicidio agravado es pluriofensivo139.
Comportamiento típico.- La conducta típica del sujeto activo varón es la de matar a una mujer
portal condición. Al igual que en todos los tipos penales de homicidio, la conducta del sujeto
activo es descrita con la locución "El que mata”. En el contexto de un derecho penal de acto,
el feminicidio debe implicar una actividad homicida del agente que produzca la muerte del
sujeto pasivo mujer. Desde esta perspectiva el feminicidio es también un delito de resultado.
La muerte puede producirse por acción o por comisión por omisión. Estas dos formas de compor
tamiento típico están sujetas a las mismas exigencias que rigen el comportamiento humano. Tra
tándose de un feminicidio por acción, debe existir un mínimo control de la voluntad, para que se
entienda que la muerte se ha producido por un individuo que actuaba. Si se trata de un feminicidio
por comisión por omisión, el sujeto activo o, mejor dicho, el omitente no impidió la producción de
la muerte de la mujer, habiendo tenido el deber jurídico de impedirlo o si hubiera creado un peligro
inminente que haya sido idóneo para producirlo (posición de garante). En este caso la omisión del
hombre corresponde a la realización activa del feminicidio (juicio de equivalencia).
Medios.-Cualquier medio idóneo para matares relevante típicamente. Pueden usarse medios
directos o inmediatos (puño, pies, cuchillo, arma de fuego), o indirectos o mediatos (veneno,
pastillas). Del mismo modo se acepta que se puede matar con medios materiales o físicos, o
por medios psicológicos.
Causalidad e Imputación objetiva.- El nexo causal es un elemento indispensable en los de
litos de resultado, como el feminicidio. La imputación objetiva se construye además sobre la
