Tema 6: Temas de la Especialidad Penal
base de la causalidad. En este sentido, en el feminicidio, como en cualquier otra conducta ho
micida debe establecerse que hay una vinculación entre la conducta del sujeto activo -hom
bre-y la muerte de la mujer.
Si la conducta del hombre no genera peligro alguno a la vida de la mujer, o el peligro no produce
la muerte de ésta o el resultado es distinto a la muerte, prohibición por la norma penal subya
cente al tipo penal de feminicidio, no podría colegirse la imputación objetiva, en el caso concreto.
Tipo Subjetivo.- El feminicidio es un delito doloso. En el contexto presente, el dolo consiste en
el conocimiento actual que la conducta desplegada por el sujeto activo era idónea para pro
ducir la muerte de la mujer, produciendo un riesgo relevante en la vida de ésta y se concretó
en su muerte.
Contextos en los que se produce el feminicidio140:
Violencia familiar.- Este contexto es fundamental delimitarlo, porque es el escenario
más recurrente en los casos de feminicidio. Para ello debe distinguirse dos niveles interre
lacionados pero que pueden eventualmente operar independientemente: el de violencia
contra las mujeres y el de violencia fam iliar en general. Para efectos típicos, el primero
está comprendido dentro del segundo. Pero puede asumirse que un feminicidio se pro
duzca, en un contexto de violencia sistemática contra los integrantes del grupo familiar,
sin antecedentes relevantes o frecuentes de violencia directa precedente, contra la vícti
ma del feminicidio.
Coacción, hostigamiento y acoso sexual.
Prevalimiento.- Otro contexto, en el que se puede dar el delito de feminicidio, es el de
abuso de poder, confianza o cualquier posición o relación que le confiera autoridad al
agente. Son las típicas conductas del llamado prevalimiento; esto es, el de aprovecharse
o valerse de una posición de poder, confianza o legitimación para someter o pretender
sojuzgar arbitrariamente a la mujer, en el ámbito privado o público,
Actos de discriminación.- Finalmente, el delito de feminicidio puede realizarse en el
contexto de cualquier forma de discriminación contra la mujer, independientemente de
que exista o haya existido una relación conyugal o de convivencia con el agente. Se en
tiende por discriminación, la actitud de impedir la igualdad de oportunidades o de dar
igual trato a la mujer, en cualquier ámbito (personal, familiar, laboral, de salud, educati
vo) por motivos sexistas o misóginos.
4.2. Tipos agravados141
Edad de la mujer.- El feminicidio tiene un mayor des valor de acción cuando la víctima es menor
de edad o una persona adulta.
Estado de gestación - La conducta igualmente se agrava si la mujer se encontraba gestando. La
razón de la agravación radica en la supresión de una vida no dependiente, además de la vida
de la mujer.
