UBILEX
Subordinación.- La conducta se agrava si la mujer se encontraba bajo cuidado o responsabili
dad del agente. Esta circunstancia agravatoria se justifica por el abuso de la posición de con
fianza o de la responsabilidad conferida al agente.
Violación sexual previa.-Se trata de una circunstancia concursal que, en general sería un concur
so real heterogéneo. El agente demuestra su proterva actitud de desprecio hacia su víctima
violándola previamente al acto de darle muerte. En este caso se vulnera la vida y la libertad
sexual de la mujer, por lo que debe ser sancionado con mayor severidad.
Abuso de discapacidad.-Del mismo modo que en el caso de los menores de edad o las personas
adultas, ef feminicida aprovecha la mayor vulnerabilidad de la mujer discapacitada.
Trata de personas o actos de explotación.- En este caso el feminicidio es el acto culminante de un
proceso previo de sojuzgamiento extremo de la víctima. En la versión anterior del tipo penal
de feminicidio, sólo se consideraba como la trata de personas como circunstancia agravante.
En la nueva versión se ha agregado''óualquiertipo de explotación”
Presencia de los h ijos- Con la últim a reforma al delito de feminicidio se incorporó la circunstan
cia agravante de dar muerte a la mujer “a sabiendas de la presencia de las hijas o hijos de la
víctima o de niños, niñas o adolescentes que se encuentren bajo su cuidado”. Para su configu
ración no se requiere que el feminicidio se cometa en presencia o a la vista de los hijos o niños
bajo su cuidado. Solo que se realice a sabiendas que se encuentran físicamente en el lugar
donde viven con la madre. El feminicidio cometido es más grave precisamente porque genera
un trauma en los hijos o niños, afectando también la integridad psíquica de éstas.
Si el agente actúa en estado de ebriedad, con presencia de alcohol en la sangre en proporción mayor de
o.Z5gram os-litro, o bajo efecto de drogas tóxicas, estupefacientes, sustancias psicotrópicas o sintéticas.
4.3. Concurso con agravantes del homicidio calificado142
El feminicidio se agrava si concurren cualquiera de las circunstancias que configuran el hom i
cidio calificado o asesinato; esto es, ferocidad, codicia, lucro, placer, para faci Iitar u ocultar otro
delito, con gran crueldad o alevosía, por fuego, explosión o cualquier medio capaz de poner en
peligro la vida, o salud de otras personas.
4.4. Concurso143
El feminicidio puede concurrir ideal o realmente con otros delitos. Es probable que el femi-
nicidio concurra con otras modalidades homicidio o lesiones si hay otras víctimas. De igual
manera puede concurrir con el secuestro, tráfico de migrantes, violación sexual, vías de hecho
u otras modalidades típicas.
En los casos en donde el feminicidio se agrava por la presencia de otras circunstancias que, por
sí mismas son delitos, como la coacción, la violación sexual, la exposición de personas en peli
gro o la trata de personas, se genera un concurso aparente que deben ser resueltas conforme
los principios de especialidad, consunción, subsidiaridad.
