4.5. Configuración de! delito de feminicidio y su distinción del tip o penal de agresión
contra mujeres e integrantes del grupo familiar (Cas. N.° 1177-2019 Cusco.
P u b .07/03/2021)
Sobre estos dos delitos se ha desarrollado doctrina jurisprudencial que contribuye a conocer
su sentido y alcances; así, tenemos:
FEMINICIDIO
BASE LEGAL: artículo 108-B del Código Penal.
DEFINICIÓN: Es el acto concreto realizado por un varón que
suprime la vida de una mujer (fundamento 52 del Acuerdo
Plenarto número 1- 2016/C J - l 16)
