8.2. Sicariato
Descripción normativa:
Art. 108-C C.P.: El que mata a otro por orden, encargo o acuerdo, con el propósito de obtener para s í
o para otro un beneficio económico o de cualquier otra índole, será reprimido con pena privativa de
libertad no menor de veinticinco años y con inhabilitación establecida en el numeral 6 del artículo 3 6 ,
según corresponda.
Las m ism as penas se imponen a quien ordena, encarga, acuerda el sicariato o actúa como intermediario.
Será reprimido con pena privativa de libertad de cadena perpetua si la conducta descrita en el primer párrafo
se realiza:
1. Valiéndose de un menor de edad o de otro inimputable para ejecutar la conducta.
2. Para dar cumplimiento a la orden de una organización criminal.
3 . Cuando en la ejecución intervienen dos o más personas.
4 . Cuando las víctimas sean dos o más personas.
5.Cuando las víctimas estén comprendidas en los artículos 107 primer párrafo, 10 8 -A y 10 8 -B primer párrafo.
6. Cuando se utilice armas de guerra,
