La conspiración y el ofrecimiento para el sicariato (A rtio 8-D C R):
Será reprimido con pena privativa de libertad no menor de cinco ni mayor de ocho años:
i. Quien participa en una conspiración para promover favorecer o facilitar el delito de sicariato.
z. Quien solicita u ofrece a otros, cometer el delito de sicariato o actúa como intermediario.
La pena privativa de libertad será no menor de seis ni mayor de diez años, si las conductas
antes descritas se realizan con la intervención de un menor de edad u otro inimputable.
8.3. Homicidio por emoción violenta
El fundamento de este delito atenuado reside en la menor reprochabiIidad que se le puede
efectuar al agente que despliega la acción homicida bajo la influencia de una perturbación
psíquica que le impide mantenerse en pleno control de sus instintos inhibitorios frente a las
incitaciones que lo impulsaron a su actuar. Como bien señalan los juristas Cálvez y Rojas, el
estado de emoción violenta «(...) trata de un supuesto en el que el homicida no pierde totalm ente la
conciencia de su actos, es decir, no sufre una alteración de la conciencia que conduciría a un supuesto de
inim putabilidad, sino de un caso en que el agente es arrastrado al delito por una fuerza impulsora que
afecta de alguna manera su capacidad deliberativa, pero sin anularla»144145. En efecto, la intensidad de
la emoción violenta no debe hacer perder el poder de inhibición al agente, de lo contrario, la
situación se desplazaría hacia los confines de la inim putabilidad,ya que una persona emocio
nada no es un individuo inimputable.
Descripción normativa:
"Art. 109 CP, El que mata a otro bajo el imperio de una emoción violenta que las circunstancias hacen
excusable, será reprimido con pena privativa de libertad, no menor de tres ni mayor de cinco años.
Si concurre algunas de las circunstancias previstas en el artículo 107, la pena será no menor de cinco
ni mayor de diez años."
Tipicidad objetiva: El comportamiento típico del agente consiste en matar a otra persona
bajo los efectos de un estado de emoción violenta, siendo requisito del tipo penal la existencia
de circunstancias que hacen excusante la emoción, es decir, debe acreditarse no sólo un esta
do psíquico emocional en el sujeto activo, sino también que dicha emoción deba fundarse en
circunstancias especiales que la excusen.
La doctrina sostiene que el estado emocional violento del agente activo supone: «a) estar en
estado de emoción violenta en el momento de la determinación homicida; b) estar en ese mismo estado
en el momento de la ejecución delictiva;}/, c) que entre la determ inacióny la ejecución delictiva no exista
solución de continuidad. Esto es así, porque el hecho criminoso debe suponer que en ningún momento de
este tramo, la conducta estuvo dirigida poruña capacidad normal»H5.
Debe entenderse que cuando la norma penal hace referencia al carácter violento de la emo
ción no se está refiriendo a su aparición súbita ante un hecho exterior que debe ser inesperado
