o sorpresivo, ya que esto es connatural a cualquier estado emocional, sino a su potencia para
menguar los frenos inhibitorios del sujeto activo, sin destruirlos totalmente, pues de pasarse
este límite el agente no se encuentra en la capacidad de dirigir su conducta, lo cual configura
un caso de inim putabilidad.
Por otro lado, se requiere de una circunstancia excusante suficiente que desencadene una
emoción violenta en el sujeto activo, tales como, hechos, palabras o escritos provocadores en
sí mismos o por reflexión sobre ellos; por las situaciones ajenas o propias de dolor; o de peli
gro que despiertan emociones que no pueden frenarse inhibitoriamente. Estas causas provo
cadoras o desencadenantes deben ser eficaces con relación al estado emocional violento, de
acuerdo a los parámetros culturales y sociales donde se produce el hecho, sin perder de vista
las singularidades del autor (personalidad) y las circunstancias que rodean al caso146.
La práctica judicial exige para aplicar este tipo penal atenuante, que entre las causas provoca
doras y el estado emocional exista una relación de inmediatez temporal, a saber:
«(...) la reacción del agente debe ser de manera inmediata al estímulo de un hecho que provoque
dicho estado emocional, por lo que la atenuante no se configura cuando el homicidio se ha perpe
trado varias horas después deque el autor fuera insultado y agredido injustamente por el hijo de la
víctima»147.
«(...) el tiempo que sucede entre la provocación y el hecho, esto es, que el delito tiene que cometerse
en los precisos instantes en que el sujeto se encuentra bajo el imperio de la emoción violenta, esto es,
que la reacción del agente debe ser inmediata, siendo que en el caso de autos el acusado reaccionó
momentos después»148.
«(...) el intervalo de tiempo sucedido entre la provocacióny el hecho, esto es que el delito tiene que cometer
se en un lapso de tiempo durante el cual el sujeto se encuentra bajo el imperio de la emoción violenta, por
lo que no puede transcurrir un largo espacio temporal entre el hecho provocanteysu reacción, siendo que
en el caso que se analiza, el acusado reaccionó después de treinta a cuarenta minutos»149.
8.4. Infanticidio
Descripción normativa:
"Art, 110 CR La madre que mata a su hijo durante el parto o bajo la influencia del estado puerperal, será ''
reprimida con pena privativa de libertad no menor de uno ni mayor de cuatro años, o con prestación de
servicio comunitario de cincuentidós a ciento cuatro jornadas". ■
Comportamiento típico
El delito de infanticidio es un delito especial impropio único en su género desde que el sujeto
activo sólo puede serlo la madre durante el parto o bajo la influencia del estado puerperal y el
sujeto pasivo solo puede serlo el hijo naciendo o recién nacido de este parto.
