UBILEX
El delito de infanticidio es perpetrable, en el mayor de los casos solo por comisión pues su per
petración por omisión contradice el supuesto estado de colapso expansivo propio del estado
puerperal o del concomitante al proceso del parto.
La omisión impropia supondría un género de cálculo y de autocontrol incompatible a nuestro
entender con el estado psico-patofisiologico de la parturienta, salvo la única hipótesis que al
estado puerperal se le asociará una crisis depresiva profunda en el que cabría la modalidad
infanticida por omisión impropia, hipótesis que deberá ser verificada mediante pericia psi
quiátrica y psicológica. Si se verificara la muerte del infante por omisión sin que este hecho se
le haya asociado el estado depresivo al que hemos aludido, estaríamos muy probablemente
frente a un tipo penal de parricidio.
8.5. Homicidio culposo
La culpa, por el contrario, es la consecución de un resultado ilícito, pero con ausencia de inten
ción. El hecho dañoso se deriva del comportamiento negligente, imprudente o temerario del
sujeto activo del delito quien, además debe hallarse en la posibilidad psicológica de represen
tarse el resultado.
Descripción normativa:
"Art, W CP. El que, por culpa, ocasiona la muerte de una persona, será reprimido con pena privativa
de libertad no mayor de dos años o con prestación de servicios comunitarios de cincuenta y dos a
ciento cuatro jornadas.
La pena privativa de la libertad será no menor de un año ni mayor de cuatro años si el delito resulta de
la inobservancia de reglas de profesión, de ocupación o industria y no menor de un año ni mayor de seis años
cuando sean varias las víctimas del mismo hecho.
La pena privativa de la libertad será no menor de cuatro años ni mayor de ocho años e Inhabilitación,
según corresponda, conforme al artículo 3 6 -in ciso s 4), 6) y 7)-, si la muerte se comete utilizando vehículo
motorizado o arma de fuego, estando el agente bajo el efecto de drogas tóxicas, estupefacientes, s u s
tancias psicotrópícas o sintéticas, o con presencia de alcohol en la sangre en proporción m ayor de 0 ,5
