Tipicidad objetiva
El comportamiento típico del delito de homicidio culposo supone la producción de una acción
que supere el riesgo permitido, el cual se concreta en el resultado lesivo, por consiguiente, la
conducta típico del homicidio imprudente coincide en su aspecto objetivo con el homicidio
doloso, pues ambos están constituidos por los factores de la imputación objetiva que permite
atribuir el resultado al agente (relación de causalidad), siendo aplicable los mismos criterios
de imputación objetiva del comportamiento y del resultado.
En el juicio de subsunción del delito imprudente resulta necesario recurrir a criterios norma
tivos que nos permitan establecer si el comportamiento desplegado por el agente, desde una
perspectiva ex ante (momento de la ejecución de la conducta), conlleva un riesgo penalmente
relevante de producción de resultado lesivo, lo que equivale a decir, que ha existido una infrac
ción al deber objetivo de cuidado; y desde una perspectiva ex post (circunstancias conocidas
976 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

