Tema 6: Temas de la Especialidad Penal
después de la producción del resultado), si el resultado lesivo ha sido la materialización del
riesgo creado por el actuar del sujeto activo150.
El jurista Salinas Siccha señala que.- «(...) el delito imprudente solo está completo cuando se
comprueba un resultado que es consecuencia de la conducta que infringe un deber objetivo de
cuidado, el cual crea, a su vez, un riesgo típicamente relevante que se concretiza en el resultado
(muerte) y se mantiene él mismo dentro de los alcances del tipo de homicidio imprudente»151.
En esta misma línea, la Sala Penal Transitoria de la Corte Suprema de Justicia refiere que.-
«(...) respecto al tipo del Injusto imprudente hay que tener en cuenta lo señalado por la doctrina i
J | A en el sentido que: -actúa culposa o imprudentemente el que omite la diligencia debida-. (..),
se trata, por lo tanto de una infracción del deber de cuidado, o'' sea, de las normas de conducta
B B | exigióles para el caso, las cuales se extraen de la experiencia común y no dependen necesaria
mente de Leyes o reglamentos. Se trata de un deber objetivo en cuanto que es et que hubiera
observado un ciudadano medio en tales condiciones y con los conocimientos específicos del
agente (...); que, por lo tanto, si la acción se realiza con la diligencia debida, aunque sea previsible :
plantea problema alguno; pues, la acción objetivamente imprudente, es decir, realizada sin la diligencia debida
que incrementa de forma ilegitima el peligro y fundamento de la imputación objetiva del resultado (...) solo son
imputables objetivamente los resultados que aparecen como realización de un riesgo no permitido implícito en ;
la propia acción; en consecuencia, la verificación de un nexo causal entre acción y resultado no es suficiente ;
para imputar ese resultado al autor de la acción»152.
Ahora bien, el comportamiento del agente vulnera el deber objetivo de cuidado cuando realiza
un comportamiento peligroso o no toma las precauciones necesarias y adaptadas al compor
tamiento peligroso, con la finalidad de evitar poner en peligro o lesionar bienes jurídicos pro
tegidos. El deber de cuidado está integrado por el deber de reconocimiento del peligro para el
bien jurídico y, después, por el deber de abstenerse de las medidas cautelosas, originándose de
fuentes diversas como los reglamentos de tránsito, de deporte, de minería, de ingeniería, etc.; y
ante la ausencia de reglamentaciones se aplican las reglas de la experiencia general de la vida.153
Tipicidad subjetiva
El agente que comete el homicidio culposo no actúa con conocimiento que su conducta es
idónea para causar la muerte de la víctima, pero el resultado letal se produce por la inobservan
cia del deber objetivo de cuidado.
De este modo, el delito imprudente se produce cuando el agente actúa con «(...) falta de pre
visión, precaución, prudencia, precognición de un resultado previsible o previéndolo se confía en poder
evitarlo. Es decir, el agente ocasiona un resultado lesivo-letal al actuar culposamente, teniendo la oportu
nidad o alternativa de prever el resultadoy conducirse con el cuidado debido que exigen las circunstancias
(culpa inconsciente). O también se evidencia cuando se produce el resultado lesivo que el agente previo y
por exceso de confianza en evitarlo no realizó la diligencia debida (culpa consciente).»154
