8 . 6 . H o m ic i d i o p ia d o s o
D e sc rip c ió n n o r m a tiv a :
"Alt, 1 12 CR El que, por piedad, mata a un enfermo incurable que le solicita de manera expresa y cons
ciente para poner fin a sus intolerables dolores, será reprimido con pena privativa de libertad no mayor
de tres años."
Comportamiento típ ico :
El agen te ..realiza la conducta delictiva de homicidio piadoso cuando motivado o guiado por un
sentimiento de piedad y, a solicitud expresa y consiente del sujeto pasivo, que sufre de enfer
medad incurable, le pone fin a su vida para liberarle de intolerables dolores.
La conducta típica puede realizarse tanto por acción como por omisión impropia (comisión
por omisión).
Por ejemplo, un caso de acción se produce cuando un médico que a petición de un paciente con
cáncerterminal decide inyectarle una droga para así ocasionarle una muerte rápiday sin dolor.
Por otro lado, un caso de comisión por omisión, sucede cuando a solicitud del enfermo incura
ble, el sujeto activo omite prestarle el medicamento que sirve para mantener con vida a aquel
y como consecuencia de tal omisión, el enfermo llega a fallecer.
Presupuestos
a. Enfermedad incurable-, el sujeto pasivo debe padecer una enfermedad incurable, la misma
que puede ser de naturaleza corporal o psíquica; pero eso sí, debe ser incurable, es decir,
según criterio médico, no sea posible su curación o recuperación. Sin duda, solo los peri
tos médicos podrán determinar aquella circunstancia, siendo de importancia su asesora-
miento para resolver un caso concreto.
b. Dolores intolerables: se exige que el enfermo incurable esté sufriendo de intolerables dolo
res, si ello no se constata, el delito de homicidio piadoso no aparece.
c. Solicitud expresa y consiente: el enfermo incurable debe solicitar de manera expresa y con
siente al sujeto activo que le de muerte. En ese sentido, no se contempla el consentimien
to tácito de la víctima. La exigencia que el pedido del enfermo incurable sea de manera
expresa y consiente excluye numerosos casos en los cuales el enfermo se encuentra, por
su propia dolencia, incapacitado para realizar el pedido en aquellas condiciones.
d. Piedad: el móvil que orienta la acción del agente, debe ser la piedad, circunstancia altruis
ta que se entiende como un estado de dolor o ímpetu de dolor en que hay ofuscación del
ánimo, imposibilidad de control pleno de la voluntad y disminución de las capacidades
de entender y querer. La piedad es la motivación fundamental con que actúa el agente
para ponerfin a la vida del enfermo incurable.
Tipicidad subjetiva
El homicidio por piedad exige que el agente actúe con conocim ientoy voluntad de ponerfin a
la vida del sujeto pasivo, movido porel sentimiento de piedad, caridad, conmiseración, miseri
cordia o compasión, dada las especiales condiciones en que se desenvuelve el sujeto pasivo. Es
decir, se exige el dolo dirigido a ponerfin a la vida del enfermo incurabley, lo más importante,
terminar o concluir con sus intolerables dolores que le agobian.
