Tema 6: Temas de la Especialidad Penal
De este modo, la decisión homicida debe ser producto o resultado del sentimiento de pie
dad, si ello no se constata y, por el contrario, se determina que el agente puso fin a la vida del
enfermo incurable guiado por sentimientos innobles, como, por ejemplo, con la finalidad de
heredar, el delito privilegiado en sede no aparece.
No es posible la comisión por culpa, si ello se evidencia, la conducta se encuadraría en el tipo
penal que regula el homicidio culposo, según las circunstancias.
8.7. Instigación o ayuda al suicidio
Descripción normativa:
“Art. 113 CP. El que instiga a otro al suicidio o lo ayuda a cometerlo, será reprimido, sí el suicidio se
ha consumado o intentado, con pena privativa de libertad no menor de uno ni mayor de cuatro años.
La pena será no menor de dos ni mayor de cinco años, si el agente actuó por un móvil egoísta."
Comportamiento típico
La conducta típica consiste en ayudar o inducir al suicidio. Presupuesto de su realización es, por
lo tanto, que el suicida haya tenido el dominio del hecho, es decir, haya sido autor de la muerte.
De lo contrario entrará en consideración la autoría mediata de homicidio del que ayudo o indujo
al suicida (eventualmente asesinato o parricidio). La determinación de un comportamiento ple
namente responsable del suicida, que permita sostener su dominio del hecho, puede ser proble
mático ya que el estado psicológico del suicida, por regla, parece excluirlo.
L E S IO N E S
Bien jurídico protegido
• Tradicional: La integridad física y la salud (sigue el CP).
• Actualmente: teoría avanzada, se sustenta en circunstancias científicas y contrastables ob
jetivamente:
Si aceptamos que la vulneración de la integridad física trae como consecuencia inmediata una
afección a la salud del que la sufre, automáticamente se descarta la posibilidad de estarfrente
a dos bienes jurídicos diferenciadles.
La Salud puede ser definida como el estado en el cual ésta desarrolla todas sus actividades,
tanto físicas como psíquicas, en forma normal, sin ninguna afección que le aflija.
1. Lesiones graves
Descripción normativa:
“Art. 121 CP. El que causa a otro daño grave en el cuerpo o en la salud física o mental, será reprimido
con pena privativa de libertad no menor de cuatro ni mayor de ocho años.
Se consideran lesiones graves:
i . Las que ponen en peligro inminente la vida de la víctima.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 980 of 1506 --

UBILEX
2. Las que mutilan un miembro u órgano principal del cuerpo o lo hacen impropio para su función, causan a
una persona incapacidad para el trabajo, invalidez o anomalía psíquica permanente o la desfiguran de manera
grave y permanente,
3. Las que infieren cualquier otro daño a la integridad corporal, o a la salud física o mental de una persona que
requiera veinte o más días de asistencia o descanso según prescripción facultativa, o se determina un nivel
grave o muy grave de daño psíquico,
4. La afectación psicológica generada como consecuencia de que el agente obligue a otro a presenciar cual-
quier modalidad de homicidio doloso, lesión dolosa o violación sexual, opudíendo evitar esta situación no lo
hubiera hecho. Cuando la víctima muere a consecuencia de la lesión y el agente pudo prever este resultado, la
pena será no menor de seis ni mayor de doce años. . .
En los supuestos l, 2 y 3 d e l prim er párrafo, la pena privativa de libertad será no menor de seis años ni mayor
de doce años cuando concurra cualquiera de las siguientes circunstancias agravantes:
1. La víctima es miembro de la Policía Nacional del Perú o de las Fuerzas Armadas, magistrado del Poder
Judicial o del Ministerio Público, magistrado del Tribunal Constitucional, autoridad elegida por m andato po
pular, servidor civil o autoridad administrativa relacionada con el transporte, tránsito terrestre o los servicios
complementarios relacionados con dichas materias y es lesionada en ejercicio de sus funciones o como con
secuencia de ellas.
2. La víctima es menor de edad, adulta mayor o tiene díscapacidad y el agente se aprovecha de dicha condición.
3. Para cometer el delito se hubiera utilizado cualquier tipo de arma, objeto contundente o instrumento que
ponga en riesgo la vida de la víctima
4. El delito se hubiera realizado con ensañamiento o alevosía,
En este caso, si la muerte se produce como consecuencia de cualquiera de las agravantes del segundo párrafo
5. La víctima es un profesional o técnico o auxiliar asistencial de la salud que desarrolla actividad asistencia/y
es lesionada a causa del ejercicio de sus labores en el ámbito público o privado.
En este caso, si la muerte se produce como consecuencia de cualquiera de las agravantes del segundo párra
fo, se aplica pena privativa de libertad no menor de quince ni mayor de veinte años.
Tipicidad objetiva
La acción típica de lesiones graves se configura cuando el agente por acción o comisión por omi
sión causa, produce u origina un daño graveen la integridad corporal o salud del sujeto pasivo.
Se entiende por daño a la integridad corporal a toda alteración anormal en la estructura física o
anatómica de la persona. El daño puede ser externo o interno, careciendo de importancia para
su configuración que exista o no derramamiento desangre. Porejemplo: hemorragia interna.
Por lo tanto, la alteración de parte del cuerpo que no afecta la vital idad o que no tenga inciden
cia en ella, no constituye lesión. Por ejemplo: el corte de cabello. En tanto que daño a la salud
se entiende como una modificación funcional del organismo. Afecta el desarrollo funcional
del organismo humano, sea en su aspecto físico como mental. Por lo tanto, cualquier detri
mento o perturbación en el organismo que afecte su desarrollo o equilibrio funcional consti
tuye un daño en la salud tipificado como delito.
En otro aspecto, de la redacción del tipo penal se evidencia en forma clara que las autolesiones
no constituyen injusto penal de lesiones. El tipo comienza indicando que el daño debe ser“a
otro”, es decir, la acción de lesionar debe estar dirigida a un tercero. Si uno mismo se causa las
lesiones en el cuerpo o en la salud no se configura el delito de lesiones y menos en su moda
lidad de graves.
Las cualidades o características de los medios o elementos empleados para la materialización
de la conducta delictiva de lesiones graves carecen de relevancia al momento de calificar los
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 981 of 1506 --

Tema 6: Temas de la Especialidad Penal
resultados producidos sobre la integridad corporal y salud de la víctima. Siendo posible la uti
lización de cualquier medio.
La lesión se torna en grave por su misma magnitud, sin importar el objeto con el cual fue causado.
Los medios, instrumentos, formas o especiales circunstancias solo tendrían trascendencia cuan
do el juez se encuentre en el momento de individualizary graduar la pena a imponer al agente.
Tal es el caso de lo dispuesto en el numeral 3 del segundo párrafo del art.121 CP que señala como
una agravante en la conducta típica al establecer que: “En los supuestos 1,2_y 3 del prim er párrafo, la
pena privativa de libertad será no menor de seis años ni mayor de doce años cuando concurra cualquiera de
las siguientes circunstancias agravantes.- (...) 3. Para cometer el delito se hubiera utilizado cualquier tipo de
arma, objeto contundente o instrumento que ponga en riesgo la vida de la víctima.”
De acuerdo con nuestro sistema jurídico, la integridad corporal y la salud no son bienes o in
tereses fundamentales de libre disposición por las personas. En tal sentido, el consentimiento
de la víctima para que el sujeto activo le cause lesiones en su integridad corporal o salud carece
de relevancia para la configuración del delito, esto es, aun cuando la víctima haya dado su con
sentimiento para que otro le ocasione o cause lesiones graves, el delito se configura.
a. Circunstancias que califican la lesión como grave
i) Poner en peligro inminente la vida del sujeto pasivo: Se entiende que la lesión se con
siderará grave cuando el daño ocasionado o producido en la integridad corporal o en la
salud de la víctima, lo pone en serio, concreto e inminente peligro de vida.
Peligro inminente de vida debe ser entendido como la probabilidad concreta y presen
te que a consecuencia de la lesión producida se origine un resultado letal. El peligro de
muerte debe ser actual, serio, efectivo y no remoto o meramente presumido.
Por ejemplo, Julio en compañía de unos amigos acudieron a una fiesta de una compañera de la uni
versidad. Cerca de las 3 a.m., un grupo de 5 jóvenes ingresaron a la fiesta y empezaron a molestar
al grupo de Julio. Cuando Julio y sus amigos decidieron retirarse de la fiesta para evitar una posible
pelea con el otro grupo, uno de ellos cogió una botella rota y se la clavó en el abdomen de Julio, cau
sándole una gran herida. Inmediatamente, los amigos de Julio procedieron a llevarlo a un hospital,
debido a la profundidad del corte y la cantidad de sangre que perdió después del ataque.
Por otro lado, si la lesión producida en una persona no pone en peligro su vida en algún
momento de su evolución, por más horror que cause en sí misma, por su naturaleza, no
se configurará la modalidad delictiva en comentario.
Por ejemplo, Carlos y Emilio son atacados por unos barristas quienes los golpean porser hinchas de
Alianza Lima. Después del ataque, los jóvenes sólo presentaron hematomas menores en la espalda y
brazos, siendo atendidos por la hermana de Carlos al llegara su casa.
i i) Mutilación de un miembro u órgano principal del cuerpo: En ese sentido, se configura
como graves las lesiones cuando el agente mutila, amputa o cercena algún miembro u ór
gano principal del sujeto pasivo. También se configura esta modalidad agravada cuando
a consecuencia de la acción del agente, se mutile o ampute por prescripción médica, un
miembro uórgano principal de lavíctima.
Por ejemplo, Sergio, quien es una persona violenta, atacó con bate de béisbol a su prim o pom o quiso
comprarle una gaseosa. Producto de los golpes, principalmente en la pierna izquierda, el médico que
lo atendió tuvo que amputársela.
