Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 982 of 1506 --

UBILEX
i i i) H a c e r im p ro p io p a ra su fu n c ió n a u n m ie m b r o u ó rg a n o p rin c ip a l: Estos supuestos se
producen cuando la lesión origina Invalidez e inutilización del órgano o miembro princi
pal de la víctima. La lesión ocasionada hace inapto para la función que el órgano o miem
bro desempeña normalmente.
Aquí no es necesario la amputación sino simplemente hacerlo inapto o impropio para su
función normal. En otros términos, hacer impropio para su función significa que el sujeto
pasivo queda en la imposibilidad de valerse de algún miembro u órgano importante a
consecuencia de la lesión, sin necesidad de que haya sido mutilada.
Nadgi precisa el tipo penal respecto al tiempo que debe durar la impropiedad de la fun
ción de un miembro u órgano importante, no obstante, interpretando sistemáticamente
y tomando en cuenta la drasticidad de la pena a la que se hace merecedor el agente, se
concluye que la impropiedad debe ser permanente y total. En consecuencia, la opinión
médica será necesaria al momento de decidir si la invalidez del órgano o miembro es per
manente e irreversible.
Por ejemplo, Christian es un joven mecánico que ha formado de manera independiente su propio taller.
Un día, llega a su taller el Sr. Rodríguez quien le pide que examine su auto, debido que presentaba una
avería en el m otor Al finalizar su trabajo, Christian le dice al señor Rodríguez que sus honorarios as
cienden aUS$ 5 0 0 .0 0 dólares americanos; sin embargo, el cliente se rehusé a pagar dicha cantidad y
solo le da S /io o . o o nuevos soles porque, a su criterio, el daño del m otor no era severo.
Ante esto, Christian toma un cilindro que contenía brea caliente y la arroja a los ojos del señor Ro
dríguez. Después que es atendido por el médico competente, le informan al Sr. Rodríguez que ha
perdido de manera permanente la visión.
iv) Causar incapacidad para el trabajo: Para explicar este supuesto, corresponde diferenciar
los términos de total, parcial, permanentey temporal. Se acepta que la incapacidad para
el trabajo puede ser parcial y total. Habrá incapacidad parcial cuando el sujeto pasivo a
consecuencia de la lesión, sufre una disminución en su capacidad laboral, es decir, sigue
laborando pero lo hace en menor intensidad con ocasión de la lesión. En tanto que habrá
incapacidad total cuando la víctima a consecuencia de la lesión sufrida, pierde en forma
general y total la capacidad para el trabajo, esto es, de ningún modo puede desempeñar
se en el trabajo que venía realizando hasta antes de la lesión.
Por ejemplo, la incapacidad parcial se presenta cuando una secretaria que presenta una
lesión en la mano derecha no puede realizar de manera completa su trabajo, debido a
que no puede escribir de manera rápida los comentarios que le dicta su jefe.
Por su parte, la incapacidad total se presenta cuando un jugador de fútbol es herido en
una pelea y, producto de la misma, presenta una herida en los meniscos que le imposibi
lita desempeñarse en su labor de futbolista.
Por otro lado, también existe distinción entre incapacidad temporal y permanente. Será
temporal cuando la incapacidad solo es por tiempo determinado o definido, en cambio
será permanente cuando la pérdida de la capacidad para el desempeño de un trabajo es
irrecuperable, es decir, la víctima no podrá volverá cumplir función laboral.
En el caso del futbolista, la incapacidad será temporal si después de la correspondiente operación le
indican que volverá a ju g a r en un tiempo determinado, en cambio, será permanente si le informan
que nunca más podrá volver a ju g a r fútbol.
E82 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 983 of 1506 --

Tema 6: Temas de la Especialidad Penal
En el momento de calificar los hechos y determinar si estamos ante una Incapacidad para el trabajo
total o parcial y temporal o permanente, es indispensable la existencia de un pronunciamiento médico
legal. En ese sentido, corresponde a los médicos legistas orientar al Ministerio Público y después al Juez
Penal, la m agnitud de la incapacidad laboral producida en la víctima a consecuencia de la lesión.
v) Invalidez permanente: La invalidez significa o se entiende que la víctima, como conse
cuencia de la lesión sufrida, no puede desenvolverse por sí misma. Necesita de una terce
ra persona o de algún elemento mecánico o electromecánico para realizarsus actividades
básicas. Aparte de no poder realizar alguna actividad lucrativa, no puede, por ejemplo,
hacer sus necesidades básicas sin la ayuda de un tercero.
La invalidez debe tener carácter permanente. Si en el caso concreto se determina que la
invalidez solo es temporal, el hecho no se subsumirá en este supuesto delictivo. En con
secuencia, resulta primordial el pronunciamiento de los profesionales de medicina legal
para la calificación correspondiente de los hechos.
Por ejemplo, Vanesa acaba de term inar con su novio, debido a que se enteró que lo engañaba con su
compañera Celia. Ante esta frustración, Vanesa espera que Celia salga del salón y cuando se encon
traba bajando por las escaleras, la empuja para que se caiga.
Producto de la caída, Vanesa sufrió un grave daño en la columna vertebral, perdiendo la movilidad
de sus piernas y brazos de manera permanente, lo cual no le permite desplazarse libremente ni
realizar actividad alguna.
vi) Anomalía psíquica permanente: Se entiende por anomalía psíquica a toda alteración,
perturbación o trastorno de las facultades mentales de la persona.
La hipótesis se presenta cuando el sujeto pasivo o víctima a consecuencia de la lesión,
sufre alteración de sus facultades mentales de manera permanente es decir, incurables;
siendo la mayor de las veces, efectos inmediatos de traumatismos encéfalo craneano.
Por ejemplo, Sebastián, alumno de 9° ciclo de la facultad de medicina, postula a una beca integral
para term inar sus estudios en el extranjero. Sin embargo, no logra obtenerla beca, pues se la otorga
ron a un alumno de últim o ciclo. En la ceremonia de entrega de la beca, Sebastián arremete contra el
ganador, empujándolo del estrado que se encontraba a una altura de 5 metros. Producto de la caída
el joven ganador de la beca presentó un grave problema encefálico lo cual no le permite configurar
frases completas.
vii) Desfiguración de manera grave y permanente: Este supuesto se presenta cuando como
resultado de la lesión sufrida por la víctima, esta queda dañada físicamente de manera
grave e irreversible. Es un daño que afecta directamente la integridad física de la persona
en su totalidad y no solo a aquel producido en el rostro.
En este sentido, se considera grave lesión cuando se modifica de manera profunday con
siderada la forma habitual de la persona en su círculo social. Se exige que el daño sea
permanente e irreparable.
Por ejemplo, Daniel se dirige de la oficina a su casa, en el trayecto decide comprar un ramo de flores a
su esposa por su aniversario. A l llegara su casa, se da con la sorpresa que su esposa no se encontraba.
