siones y, por ende, causar daño o perjuicio a la integridad corporal de las personas y a su
salud. En tal sentido, siendo conscientes de aquella situación se hace uso de una fórmula
que vía la interpretación analógica legalmente permitida, se abarca todos supuestos de
