12. Doctrina jurisprudencial vinculante. ~ - -■
Debe concurrir el dolo en la conducta que ocasiona las lesiones gravesy el elemento culpa en
el resultado muerte. La culpa se materializa en la ausencia del debido cuidado o por falta de
diligencia del agente al momento de producir las lesiones graves. El sujeto activo produce la
muerte que en realidad no quiso causar, pero se concretiza por haber actuado sin el debido
cuidado para evitarlo, pudiendo hacerlo.
Si la víctima adolece de una enfermedad oculta o desconocida por el agente, el agente solo
responderá por las lesiones que se propuso realizar mas no la muerte imprevisible.
Por ejemplo, Juan se entera que su novia Lucía lo engaña con su hermano Joaquín, debido a la cólera que
tiene decide enfrentar a su hermano para reclamarle dicha ofensa. Cuando se encuentra con su herma
no para pedirle explicaciones, Joaquín sin motivo alguno golpea a su hermano con palo de madera en la
espalda y cabeza, quedando esté inconsciente. Después de 2 días, Joaquín toma conocimiento que Juan
m urió de un aneurisma, debido que tenía un tum or en el cerebro, enfermedad desconocida por todos has
ta para el mismo Juan.
2. La victimase encuentra en estado de gestación.
3. La víctima es cónyuge; excónyuge; conviviente; exconviviente; padrastro; madrastra; ascendiente o des
cendiente por consanguinidad, adopción o afinidad; pariente colateral del cónyuge y conviviente hasta
el cuarto grado de consanguinidad y segundo de afinidad; habita en el mismo hogar, siempre que no
medien relaciones contractuales o laborales; o es con quien se ha procreado hijos en común, indepen
dientemente de que se conviva o no al momento de producirse los actos de violencia, o la violencia se da
en cualquiera de los contextos de los numeralesi, 2y 3 del primer párrafo del artículo 108-B.
4. La víctima mantiene cualquiertipo de relación de dependencia o subordinación sea de autoridad, econó
mica, cuidado, laboral o contractual y el agente se hubiera aprovechado de esta situación.
5. Para cometer el delito se hubiera utilizado cualquier tipo de arma, objeto contundente o instrumento
que ponga en riesgo la vida de la víctima.
6 . El delito se hubiera realizado en cualquiera de las circunstancias del artículo 108.
7. La afectación psicológica a la que se hace referencia en el numeral 4 del primer párrafo del artículo 121, se
causa a cualquier niña, niño o adolescente en contextos de violencia familiar o de violación sexual.
8 . Si el agente actúa en estado de ebriedad, con presencia de alcohol en la sangre en proporción mayor de
0.25 gramos-litro, o bajo efecto de drogas tóxicas, estupefacientes, sustancias psicotrópicas o sintéticas.
La pena será no menor de doce ni mayor de quince años cuando concurran dos o más circunstancias agravan
tes.
Cuando la víctima muere a consecuencia de cualquiera de las agravantes y el agente pudo prever ese resulta
do, la pena será no menor de quince ni mayor de veinte años.
