Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 986 of 1506 --

2. Lesiones leves
Descripción normativa:
''Aí !. 122 CP. 1. El que causa a otro lesiones en el cuerpo o en la salud física o mental que requiera i
más de diez y menos de veinte días de asistencia o descanso, según prescripción facultativa, o nivel
moderado de daño psíquico, será reprimido con pena privativa de libertad no menor de dos ni mayor
de cinco años.
2. La pena privativa de libertad será no menor de seis ni mayor de doce años si la víctima muere como conse
cuencia de la lesión prevista en el párrafo precedente y el agente pudo prever ese resultado.
3. La pena privativa de libertad será no menor de tres ni mayor de seis años e inhabilitación conforme a los
numerales 5 y 11 del artículo 36 del presente Código y los artículos 75 y 77 del Código de los Niños y Adoles
centes, según corresponda, cuando:
a. La víctima es miembro de la Policía Nacional del Perú o de las Fuerzas Armadas, magistrado del Poder Ju
dicial, del Ministerio Público o del Tribunal Constitucional o autoridad elegida por mandato popular o servidor
civil y es lesionada en el ejercicio de sus funciones oficiales o como consecuencia de ellas.
b. La víctima es menor de edad, adulta mayor o tiene discapacidad y el agente se aprovecha de dicha condición.
c. La víctima es mujer y es lesionada por su condición de tal, en cualquiera de los contextos previstos en el
primer párrafo del artículo 108-B.
d. La víctima se encontraba en estado de gestación.
e. La víctima es el cónyuge; excónyuge; conviviente; exconviviente; padrastro; madrastra; ascendiente o des
cendiente por consanguinidad, adopción o afinidad; pariente colateral del cónyuge y conviviente hasta el
cuarto grado de consanguinidad y segundo de afinidad; habita en el mismo hogar, siempre que no medien
relaciones contractuales o laborales; o es con quien se ha procreado hijos en común, independientemente de
que se conviva o no al momento de producirse los actos de violencia, o la violencia se da en cualquiera de los
contextos de los numerales 7, 2 y 3 d e l primer párrafo del artículo 108-B.
f. La víctima mantiene cualquier tipo de relación de dependencia o subordinación sea de autoridad, económica,
cuidado, laboral o contractual y el agente se hubiera aprovechado de esta situación.
g. Para cometer el delito se hubiera utilizado cualquier tipo de arma, objeto contundente o instrumento que
ponga en riesgo la vida de la víctima.
h. El delito se hubiera realizado con ensañamiento o alevosía.
i. Si el agente actúa en estado de ebriedad, con presencia de alcohol en la sangre en proporción mayor de 0.25
gramos-litro, o bajo efecto de drogas tóxicas, estupefacientes, sustancias psicotrópicas o sintéticas.
j. La víctima es un profesional o técnico o auxiliar asistencial de la salud que desarrolla actividad asistencial y
es lesionada a causa del ejercicio de sus labores en el ámbito público o privado.
4. La pena privativa de libertad será no menor de ocho ni mayor de catorce años si la víctima muere como
consecuencia de la lesión a que se refiere el párrafo 3 y el agente pudo prever ese resultado."
Ti picidad objetiva
Las lesiones leves consisten en todo daño causado de forma dolosa a la i ntegridad física corpo
ral o salud de un tercero que requiere, para curarse, de diez a veinte días de asistencia médica
o descanso para el trabajo.
En ese sentido, resulta necesaria la existencia de un diagnóstico médico que certifique los días
de asistencia o descanso laboral para que se configure el delito analizado (requisito de proce-
dibilidad).
Sin embargo, los límites fijados por el tipo penal (más d e io días y menos de zo días) para la
asistencia médica o descanso laboral no son concluyentes para considerar a un daño en la
integridad física como delito de lesiones leves o falta de lesiones, toda vez que el medio em
pleado por el agente, lugar donde se produjo los hechos, la calidad o cualidad de la víctima o
la calidad del agente, puede servir para catalogarlo como tal aun cuando el daño ocasionadoy
los días para su recuperación, no excedan los diez días de asistencia o descanso.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 987 of 1506 --

Tema 6: Temas de la Especialidad Penal
Por ejemplo, existe jurisprudencia de la Corte Suprema que privilegia la gravedad del medio
empleado por encima de los días de asistencia médica o descanso laboral ocasionado por la
lesión sufrida. A saber: Por el contrario, si la lesión leve no ha sido producida por un elemento
peligroso, no concurre ninguna otra circunstancia que le de gravedady no lo logra superar los
diez días de asistencia médica o incapacidad para el trabajo, aquella, en estricta aplicación del
contenido del artículo 441° del Código Penal, constituirá faltas contra la personay no delito.
Igual que en las lesiones graves, el consentimiento de la víctima es irrelevante para producir
lesiones leves en su integridad corporal o salud. Incluso, si no ha sido factible aplicar el Prin
cipio de Oportunidad previsto en el art. 2o del Código Procesal Penal por parte del Ministerio
Público, así exista una transacción entre la víctima y el agresor sobre las lesiones leves pro
ducidas, la formalización de denuncia continúa y, de encontrarse responsable al acusado de
lesiones simples se le impondrá penay la transacción patrimonial solo servirá para efectos de
la reparación civil.
Según el artículo 122 del Código Penal, toda lesión dolosa que no alcance las características y
magnitud que las señaladas en el artículo 121 debe ser considerada, en principio, como una
lesión leve. Sin embargo, en concordancia con la descripción típica contendida en el primer
párrafo del artículo 44T cabe inferir que es necesario que la lesión ocasionada requiera entre
diez y veinte días para merecer esa consideración penal. También el artículo 1246 estima un indi
cador específico para el caso de lesiones leves consistentes en afectaciones a la salud mental del agraviado.
Al respecto, el literal b de dicha norma exige que se haya ocasionado un «nivel moderado de daño psí
quico».^6
Asimismo, conforme a lo establecido en los artículos 122B156157y 441, también pueden adquirir la
calidad de delito de lesiones dolosas leves aquellas que, sin superar los diez días de asistencia
médica o descanso prescrito, hayan sido inferidas en contextos de violencia contra la m ujer
o contra integrantes del núcleo familiar, o en circunstancias que dan gravedad al hecho; por
156 En https://lpderecho.pe/delitos-lesiones-codigo-penal/
157 Artículo 122-B.- Agresiones en contra de las mujeres o integrantes del grupo familiar.
El que de cualquier modo cause lesiones corporales que requieran menos de diez días de asistencia o des
canso según prescripción facultativa, o algún tipo de afectación psicológica, cognitiva o conductual que no
califique como daño psíquico a una mujer por su condición de tal o a integrantes del grupo fam iliar en cual
quiera de los contextos previstos en el primer párrafo del artículo 108-B, será reprimido con pena privativa de
libertad no menor de uno ni mayor de tres años e inhabilitación conforme a los numerales 5 y ti del artículo
36 del presente Código y los artículos 75 y 77 del Código de los Niños y Adolescentes, según corresponda.
La pena será no menor de dos ni mayor de tres años, cuando en los supuestos del primer párrafo se presenten
las siguientes agravantes:
1. Se utiliza cualquier tipo de arma, objeto contundente o instrumento que ponga en riesgo la vida de la
víctima.
2. El hecho se comete con ensañamiento o alevosía.
3. La víctima se encuentra en estado de gestación.
4. La víctima es menor de edad, adulta mayor o tiene discapacidad o si padeciera de enfermedad en estado
terminal y el agente se aprovecha de dicha condición.
5. Si en la agresión participan dos o más personas.
6. Si se contraviene una medida de protección emitida por la autoridad competente.
7. Si los actos se realizan en presencia de cualquier niña, niño o adolescente.
