UBILEX
ejemplo, con el empleo de armas o cometidas con ensañamiento o alevosía, así como cuando
las lesiones se infirieron a personas ancianas o con discapacidad, etc158.
En el mismo sentido se manifiesta el Acuerdo Plenario 2-2016/Q -116 al señalar que: En el ar
tículo 122-B del C.R se considera delito el ocasionar algún tipo de afectación psicológica, cog-
nitiva o conductual a las mujeres o integrantes del grupo fam iliar en los contextos del primer
párrafo del artículo 108-B del C. R, agravándose este resultado en los supuestos comprendidos
en el segundo párrafo del artículo 122-B.
El legislador consideró síntomas conductuales y cognitivos al referirse a la afectación psico
lógica sin* tomar en cuenta los emocionales, que forman parte de los factores propios de la
personalidad humana, pero ha de entenderse esa ausencia de referencia a la esfera afectiva
no como una exclusión sino como una omisión superable”.
LESIONES LEVES, CIRCUNSTANCIAS AGRAVANTES: Circunstancias agravantes especificas
reguladas en el tercer párrafo del art. 122 del CR entre ellas destacan la condición funcionarial
(cuando el agraviado es miembro de la PNP o FF.AA, magistrado del Poder Judicial o del M i
nisterio Público o del Tribunal Constitucional o autoridad elegida por mandato popular o ser
vidor civil), condición de vulnerabilidad de la víctima (menor de edad, mujer por su condición
de tal, mujer gestante, adulta mayor o tiene discapacidad), sus vínculos familiares con el autor
del delito (cónyuge; excónyuge; conviviente; exconviviente; padrastro; madrastra; ascendien
te o descendiente por consanguinidad, adopción o afinidad; pariente colateral del cónyuge
y conviviente hasta el cuarto grado de consanguinidad y segundo de afinidad) y la muerte
preterintencional y previsible de la víctima de la lesión. En todos estos casos, la penalidad será
incrementada.
LESIONES LEVES SEGUIDAS DE M U E R T E : La hipótesis delictiva se configura cuando a con
secuencia o efecto directo de las lesiones leves que causó el agente a su víctima (debiendo o
pudiendo prever el resultado) esta muere.
En ese sentido, se configura la modalidad agravante del delito de lesiones leves al concurrir el
elemento culpa en el accionar del sujeto activo. La culpa aparece cuando el agente pudiendo o
debiendo prever el resultado letal que se podía producir, no lo hizo y se lim itó a actuar.
Por ejemplo, Luis encuentra a su prometida Les/ie besándose con su amigo W alteren un parque cerca a su
casa. Ante esto, coge a W altery lo golpea con su puño en la nariz ocasionándole una hemorragia, siendo
el caso que ai no ser auxiliado por Luis, aquél muere después de dos horas por desangramiento.
Por otro lado, resulta necesario verificar el nexo causal directo que debe existir entre las lesio
nes leves causadas y la muerte del que las sufrió para estar ante la figura agravada. Si ello no
sucedey el deceso se debe a la concurrencia de otros factores, el ilícito penal con agravante no
se materializa.
Por ejemplo, no sería autor del delito de lesiones leves seguidas de muerte, si Juan Pablo sin saber que su
víctima sufría de problemas cardíaco, le propinó un fuerte golpe en el rostro a M iguel Ángel, quien des
pués de algunos minutos se desplomó muriendo instantáneamente.
Por el contrario, si el sujeto activo conocía el mal que padece el sujeto pasivo y actúa apare
cerán necesariamente en su actuar los elementos constitutivos del injusto penal de lesiones
leves seguidas de muerte.
158 En https://lpderecho.pe/delitos-lesiones-codigo-penal/
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 989 of 1506 --

Tema 6: Temas de la Especialidad Penal
En el caso anterior, Juan Pablo tenía conocimiento que su víctima sufría del corazón, sin em
bargo, no le importo dicho estado y procedió a golpearlo, muriendo Miguel Ángel a los pocos
minutos de un paro cardíaco.
Tipicidad subjetiva:
Para la configuración del injusto penal se requiere, necesariamente, la concurrencia del dolo.
El sujeto activo debe tener conciencia y voluntad de ocasionar una lesión leve o simple a su
hijo menor de edad, cónyuge o pariente cercano, mujer en estado de gestación, adulta mayo o
persona con discapacidad, etc. Por el contrario, si se verifica que el fallecimiento de la víctima
devino a consecuencia de otros factores, el agente no responderá por aquel resultado.
Por ejemplo, Luis Ángel es un arquitecto exitoso, quien si bien nunca se casó, logró la felicidad en compa
ñía de sus padres y amigos. Un día, Luis Ángel se estaba dirigiendo a su trabajo cuando de repente choca
su auto con otro automóvil. Cuando el otro conductor descendió de su auto para reclamarle a Luis Ángel
su imprudencia al conducir, éste procedió a golpearlo con sus puños hasta dejarlo tendido en el pavimen
to. M ortificado por su accionar, Luis Ángel acudió al hospital donde estaba siendo atendido su víctima,
quien presentaba daños que ameritaban 5 días atención médica y 20 días de descanso laboral, se da con
la sorpresa que sus padres estaban en la habitación del paciente. En ese momento, los padres de Luis Ángel
le informan a éste que la víctima era su prim o hermano.
3. Lesiones culposas
Descripción normativa:
“Art. 124 C.P.: El que por culpa causa a otro un daño en el cuerpo o en la salud, será reprimido, por acción
privada, con pena privativa de libertad no mayor de un año y con sesenta a ciento veinte días-multa.
La pena será privativa de libertad no menor de uno ni mayor de dos años y de sesenta a ciento veinte
días-multa, si la lesión es grave, de conformidad a los presupuestos establecidos en el artículo 121.
La pena privativa de libertad será no menor de uno ni mayor de tres años si el delito resulta de la inobservan
cia de reglas de profesión, ocupación o industria y no menor de un año ni mayor de cuatro años cuando sean
varias las víctimas del mismo hecho.
La pena privativa de la libertad será no menor de cuatro años ni mayor de seis años e inhabilitación, según
corresponda, conforme al artículo 36 -incisos 4), 6) y 7)-, si la lesión se comete utilizando vehículo motorizado
o arma de fuego, estando el agente bajo el efecto de drogas tóxicas, estupefacientes, sustancias pslcotrópicas
o sintéticas, o con presencia de alcohol en la sangre en proporción mayor de 0.5 gramos-litro, en el caso de
transporte particular, o mayor de 0.25 gramos litro en el caso de transporte público de pasajeros, mercancías o
carga en general, o cuando el delito resulte de la inobservancia de reglas técnicas de tránsito."
Tipicidad objetiva:
El delito se perfecciona cuando el sujeto activo ocasiona lesiones sobre el sujeto pasivo por
haber obrado culposamente.
El agente obra por culpa cuando produce un resultado dañoso al haber actuado con falta de
previsión, prudencia o precaución, habiendo sido el resultado previsible o, previéndolo, confía
en poder evitarlo. Aparece el delito de lesiones culposas cuando la conducta del agente afecta
el deber objetivo de cuidado y como consecuencia directa deviene el resultado no querido ni
buscado sobre la víctima.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 990 of 1506 --

El comportamiento del agente vulnera el deber objetivo de cuidado que exige la Ley. Por deber
de cuidado debe entenderse aquel que se exige al agente a que renuncie a un comportamien
to peligroso o que tome las precauciones necesarias y adaptadas al comportamiento peligro
so, con la finalidad de evitar poner en peligro o lesionar bienes jurídicos protegidos. La acción
realizada por el autor supone la inobservancia del cuidado objetivamente debido.
A efectos de configurarse la infracción del deber objetivo de cuidado se requiere que el agente
esté en posición de garante respecto de la víctima. El deber de cuidado debido se origina de
fuentes diversas como los reglamentos de tránsito, deporte, de hospitales, de minería, de ar
quitectura, de ingeniería, etc. Ante la ausencia de reglamentaciones se aplica las reglas de la
experiencia general de la vida. En estas circunstancias debe aparecer una mediana inteligen-
ciay sentido común en el Juez para apreciar los hechos de acuerdo a su sana crítica e identifi
car si la conducta del sujeto activo afectó algún deber de cuidado exigido.
Entre la acción im prudentey el resultado lesivo debe mediar una relación de causalidad (ma
nejar el vehículo que ocasionó el accidente; construir el edificio que después se desplomará;
atender al paciente que después quedó seriamente lesionado; etc.), es decir, una circunstan
cia de conexión que permita imputar ya en el plano objetivo ese resultado concreto que ha
producido el autor de la acción culposa.
Conforme a lo anterior, si se determina que la víctima por su actuar imprudente desencadenó
el evento que produjo sus lesiones, se descartará la responsabilidad del imputado.
LESIONES CULPOSAS AGRAVADAS:
a. Conducir bajo efectos de estupefacientes o en estado de ebriedad: la sola circunstan
cia de conducirvehículos motorizados bajo los efectos de estupefacientes o en estado de
ebriedad, constituye delito contra la seguridad pública previsto y sancionado en el art.
274o del CR No obstante, si a consecuencia de conducir en alguno de los estados antes
indicados se ocasiona lesiones a determinada personas, tal circunstancia se constituye en
agravante de las lesiones culposas.
b. Cuando son varias las víctimas del mismo hecho: ello ocurre cuando con una sola ac
ción culposa el agente ocasiona lesiones a varias personas pudiendo evitarlas si hubiese
actuado diligentemente y poniendo el debido cuidado. La agravante se justifica por la
extensión del resultado.
c. El delito resulta de la inobservancia de reglas técnicas de tránsito: esta modalidad se
configura cuando el agente ocasiona lesiones culposas por no haber observado debida
y diligentemente las reglas técnicas de tránsito, esto es, cuando el conductor infringe las
reglas de tránsito descritas en el Reglamento General de Tránsito.
Inobservancia de reglas técnicas de tránsito. El delito de inobservancia de reglas técnicas de tránsito,
es un tipo penal cualificado que por su propia naturaleza no se debe tomar en cuenta la incapacidad
médico legal generada por la lesión imprudente causada. Cas. N° 345-2015- Cajamarca.
d. El delito resulta de la inobservancia de reglas de profesión, de ocupación o industria:
ello tiene plena justificación en el hecho que al desempeñarse en actividades que exigen
