Tema 6: Temas de la Especialidad Penal
del agente la máxima diligencia en observar las reglas técnicas que le son propias para el
desarrollo de su actividad, su inobservancia, sin duda, hacen más reprochable la acción
del sujeto activo.
DAÑO PSÍQUICO CULPOSO GRAVE Y MUY GRAVE
“El segundo párrafo del artículo 124 del CP, fija como circunstancia agravante del delito de le
siones cul posas cuando se ocasiona una lesión grave de acuerdo a lo previsto en el artículo 121.
El legislador del D. Leg.1323 no ha excluido el contenido del segundo supuesto de la prim eray
últim a parte del inc. 3ro. del a r t i2i (El que causa a otro daño grave (...) en la salud, será reprim i
do (...) Se consideran lesiones graves: (...) 3. Las que infieren cualquier otro daño (...) a la salud
(...) mental de una persona (...) o se determina un nivel grave o muy grave de daño psíquico),
concordado con el acápite c del primer párrafo del art. 124-B; por tanto cabe la posibilidad de
daño psíquico culposo pero solo a escala gravey muy grave.
No caben supuestos de afectación psicológica culposa, puesto que tal resultado debe ser por
previsión normativa expresa, consecuencia directa de obligar o permitir la observación de la
agresión violenta de fondo, sin impedirla”159.
4. Exposición al peligro
4.1. Delito de exposición o abandono peligrosos
Descripción normativa:
V''Aífc421 Cft El que expone a peligro de muerte o de grave e inminente daño a la salud o abandona en
¡gualeseireunstancias a un menor de edad o a una persona incapaz de valerse por sí misma que estén
legalmente bajo su protección o que se hallen de hecho bajo su cuidado, será reprimido con pena
privativa de;libertad no menor de uno ni mayor de cuatro años."
Tipicidad objetiva:
La conducta típica exige que el autor retire al menor o incapaz del ámbito o esfera donde nor
malmente se encuentra protegido para luego pasarlo a otro carente de las seguridades debi
das. Resulta importante tener en cuenta la temporalidad, ya sea permanente o meramente
modular. Porotro lado,el peligro de lesión parael bien jurídico protegido vida o salud debe ser
inminente, trascendente y significativo.
El comportamiento del agente se puede dar en los siguientes supuestos:
Exponera peligro de muerte a un menor de edad o incapaz a valerse por sí mismo.
Exponer a peligro de grave e inminente daño a un menor de edad o incapaz a valerse por
sí mismo.
Abandonara un menor de edad o incapaz a valerse por sí mismo a peligro de muerte.
159 Acuerdo Plenario N °002-2016/CM16. Fj. 20.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 991

-- 992 of 1506 --

UBILEX
Abandonar a un menor de edad o incapaz de valerse por sí mismo a peligro de grave e
inminente daño a su salud.
En cuanto al sujeto activo, nos encontramos ante un delito especial debido a que se exige en el
autor una relación de deber legal de protección y cuidado frente a la víctima menor de edad o
incapaz de valerse por sí mismo.
Tipicidad subjetiva:
La redacción del tipo penal, nos indica que estamos ante conductas dolosas. El agente debe te
ner consciencia y voluntad de exponer o abandonar a un menor de edad o incapaz de valerse
por sí mismo a un peligro contra su vida o salud.
Agravante:
Conforme lo establece el artículo 129o del Código Penal, si como consecuencia inmediata o
mediata de la exposición o abandono a peligro a un menor de edad o incapaz de valerse por sí
mismo, y ésta pudo ser previsible por agente, se produce la muerte o lesión grave de la víctima,
se aumentará la pena privativa de libertad de tres a seis años y cuatro a ochos años, respecti
vamente.
4.2. Delito de omisión de socorro y exposición de peligro
Descripción normativa:
"Art. 126 CP El que omite prestar socorro a una persona que ha herido o incapacitado, poniendo en
peligro su vida o su salud, será reprimido con pena privativa de libertad no mayor de tres años."
Tipicidad objetiva:
El delito de abandono de persona en peligro (omisión de socorro) se configura cuando el
agente con una conducta omisiva no presta auxilio o socorro al sujeto pasivo que ha herido o
incapacitado, poniendo con tal comportamiento en peligro su vida o salud. El delito no exige
que la conducta precedente sea dolosa o imprudente, sino sólo que ha sido producida por el
propio agente160.
Tipicidad subjetiva:
El tipo penal requiere una conducta dolosa, por tanto, si la omisión de prestar socorro se debió
a una negligencia, es decir, no tuvo la voluntad de causar un peligro para la vida o salud de su
víctima, la conducta no será delictiva.
160 SALINAS SICCHA, Ramiro. Op. cit., p. 236.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 993 of 1506 --

Tema 6: Temas de la Especialidad Penal
4.3. Delito de om isión de auxilio o aviso a la autoridad
Descripción normativa:
“Art. 127 CP. El que encuentra a un herido o a cualquier otra persona en estado de grave e inminente
peligro y om ite prestarle auxilio inmediato pudiendo hacerlo sin riesgo propio o de tercero o se abstie-
ne de dar aviso a la autoridad, será reprimido con pena privativa de libertad no mayor de un año o con
treinta a ciento veinte días-multa,"
Tipicidad objetiva:
El tipo penal se configura cuando el agente omite prestar auxilio a un herido o cualquier otra
persona en estado de grave e inminente peligro, o cuando el sujeto se abstiene de dar aviso a
la autoridad competente respecto del herido o la existencia de una persona en estado grave e
inminente de peligro.
El hecho precedente se da cuando la víctima se encuentre herida o en estado de peligro pro
ducto del actuar de un tercero, causas fortuitas, producto de la misma víctima o cualquier otro
origen, mientras que dicha situación no sea producida por el sujeto activo, por lo que, el delito
puede ser cometido por cualquiera.
Tipicidad subjetiva:
Nos encontramos ante un delito netamente doloso.
9. DELITOS CONTRA LA LIBERTAD E INDEMNIDAD SEXUAL
A. BIENES JURÍDICOS PROTEGIDOS
i. La libertad sexual
La libertad sexual debe entenderse de dos maneras: como la libre disposición del propio
cuerpo, sin más limitaciones que el respeto a la libertad ajena; y, como facultad de repeler
agresiones sexuales de terceros.
Al respecto, el profesor Caro Coria, señala que la libertad sexual debe entenderse tanto
en sentido positivo-dinámico como negativo-positivo. El aspecto positivo-dinámico de la
libertad sexual se concreta en la capacidad de la persona de disponer libremente de su
cuerpo para efectos sexuales, mientras que el aspecto negativo-positivo se concreta en la
capacidad de negarse a ejecutar o tolerar actos sexuales en los que no desea intervenir.
En consecuencia, la libertad sexual no se enfoca desde un concepto puramente positivo.
No se entiende como la facultad que permita a las personas a tener relaciones sexuales
con todos, sino debe entenderse en un sentido negativo, por el cual no puede obligarse a
nadie a tener relaciones sexuales en contra de su voluntad.
En ese sentido, la libertad sexual es la capacidad de toda persona para comportarse como
a bien tenga en la actividad sexual. Es la capacidad que tiene la persona de elegir libre
mente, el lugar, el tiempo, el contexto y la otra persona para relacionarse sexualmente.
Por otro lado, el Prof. Español Muñoz Conde refiere que el concepto de libertad sexual se
identifica con la capacidad de autodeterminación de la persona en el ámbito de sus rela
ciones sexuales. De ahí que la idea de autodeterminación, en cuanto materialización ple-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 994 of 1506 --

nade una lib e rta d ” amplia, viene limitada por dos requisitos fundamentales: en primer
lugar, por el pleno conocimiento del sujeto del contenido y alcance de dichas relaciones,
lo que evidentemente implica que este ha de contar con la capacidad mental suficiente
para llegara tener dicho conocimiento; y, en segundo lugar, por la manifestación voluntaria
y libre del consentimiento para participaren tal clase de relaciones, lo que tiene como pre
supuesto el que el sujeto pueda adoptar su decisión de manera libre.
Definido así el bien jurídico “libertad sexual”, como señala el Prof. Caro Coria, es indudable
que sólo quienes gocen plenamente del conocimiento necesario del alcancey significado
del aspecto sexual de las relaciones socialesy pueda decidirse con total libertad al respec
to podrá ser considerado titu lar de dicho bien jurídico, por cuanto son sujetos que pueden
auto determinarse en el planos sexual.
La indemnidad sexual
En el caso de los menores o incapaces, de modo alguno puede alegarse que se les protege
su libertado autodeterminación sexual en los delitos sexuales, pues por definición aque
llos carecen de tal facultad. De ahí que, para estos casos, se considere que el bien jurídico
protegido vendría definido por los conceptos de indemnidad o intangibilidad sexuales,
los cuales proceden en principio de la doctrina italiana, y fueron recogidos en la doctrina
española a finales de los años setentay principio de los ochenta (Muñoz Conde).
En consecuencia, vía la doctrina española llegan al Perú los conceptos de indemnidad o
intangibilidad sexual y, en tal sentido, al manifestar que hay comportamientos dentro
de la categoría de los delitos sexuales en los que no puede afirmarse que se proteja la
libertad sexual, en la medida en que la víctima carece de esa libertad o, aún si la tuviera
fácticamente, ha sido considerada por el legislador como irrelevante.
De esta forma, en los tipos penales en los cuales el legislador no reconoce eficacia a la
libertad sexual del sujeto pasivo, el interés que se pretende proteger es la indemnidad o
intangibilidad sexual entendida como seguridad o desarrollo físico o psíquico normal de
las personas.
Por lo tanto, la indemnidad sexual es el verdadero bien jurídico que se tutela con las con
ductas delictivas previstas en los artículos 172o, I73°y 176°-A del CR Esto es, le interesa al
Estado proteger la sexualidad de las personas que por sí solas no pueden defenderla al no
tener la capacidad suficiente para valorar realmente una conducta sexual. Circunstancia
que posibilita el actuar delictivo del agente.
En términos de Muñoz Conde, la protección de menores e incapaces se orienta a evitar
ciertas influencias que inciden de un modo negativo en el desarrollo futuro de su perso
nalidad. En el caso de los menores, para que de adultos puedan decidir en libertad sobre
su comportamiento sexual, y en el caso de los incapaces, para evitar que sean utilizados
como objeto sexual por terceras personas que abusen de su situación para satisfacer sus
deseos o apetitos sexuales.
