Tipicidad objetiva:
El delito de violación sexual o acceso carnal sexual se configura cuando el agente o sujeto
activo haciendo uso de la violencia o amenaza grave, logra realizar el acceso carnal (vaginal,
anal o bucal) o análogo (introducción de objetos o partes del cuerpo vía vaginal o anal) con la
víctima sin contar con su consentimiento o voluntad.
El verbo “obligar” utilizado en la redacción del tipo penal indica que previo al acceso carnal, se
vence o anula la resistencia u oposición de la víctima. De ahí que el acceso sexual sea punible
no por la actividad sexual en sí misma, sino porque tal actividad se realiza sobre la base del
abuso de la libertad sexual del otro. Asimismo, del tipo penal se desprende que los medios
ilícitos previstos por el legislador, para vencer o anular la resistencia del sujeto activo, lo cons
tituye la violenciay la amenaza grave.
