Lafórm ula''óbliga a una persona" que exige el tipo penal puede comprendertanto un compor
tamiento pasivo de la víctima como la realización de actos positivos de penetración vaginal o
análoga, a favor del autor o de un tercero. Esto permite criminalizar comportamientos graves
como el de la mujer que obliga por violencia o amenaza grave a un varón a que le practique el
acto sexual o la coacción a una mujer para que tolere la práctica sexual de un tercero.
En esa línea, el delito de violación sexual se perfecciona mediante acciones sexuales por las
cuales el agente involucra a otra persona en un contexto sexual determinado, entendiendo
por contexto sexual toda situación por cuya valoración el autor de la conducta, cuando menos,
acude a juicios de valor referentes al instinto humano que suscita atracción entre los sexos.
Esto es importante, pues si el agente con su actuar no persigue satisfacer cualquiera de sus
apetencias sexuales, y, por el contrario, solo persigue lesionar la vagina de la mujer, por ejem
plo, se descartará la comisión del delito de violación sexual, así se haya introducido en la cavi
dad vaginal objetos (palos, fierros, etc.) o partes del cuerpo (mano, dedos).
En suma, en los supuestos delictivos es necesario que el agente tenga como objetivo satisfacer
alguna apetencia de carácter sexual, caso contrario, el delito, al menos sexual, no se configura.
De ahí que en doctrina se sostenga que en los delitos sexuales siempre se exige la participa
ción de un "elemento adicional al dolo”.
¿Qué se entiende por objetos y partes del cuerpo?
Se entiende por objetos todos aquellos elementos materiales, inanimados o inanes cuya utiliza
ción conlleva una inequívoca connotación sexual (botellas, palos, bastones, fierros, etc.). En ese
sentido, el objeto es todo elemento material que el sujeto activo identifica o considera sustituti-
vo del órgano genital masculinoy, por tanto, los utiliza para satisfacer sus deseos sexuales.
En tanto que por “partes del cuerpo" se entiende a todas aquellas partes del cuerpo humano
que fácilmente pueden ser utilizados por el agente como elementos sustitutivos del m iem
bro viril para accederá la víctima: dedos, la mano completa, la lengua, etc. En otros términos,
partes del cuerpo para efectos del delito en hermenéutica, son todos aquellos miembros u
órganos que tienen apariencia en pene o miembro viril a los cuales recurre el agente para sa
tisfacer una apetencia o expectativa de tipo sexual en determinado momento, lugary víctima.
La felíatio ¡n ore como modalidad del acceso sexual:
El Prof. Caro Coria sostiene que el denominado “felíatio in ore” o acto bucogenital debe
considerarse como “acto análogo”, pues la limitación del acceso carnal a la penetración
vaginal o anal refleja una concepción de las relaciones sexuales restringida a la “genita-
Iidad”. Sin duda, en el delito de acceso carnal sexual vía bucal se presentarán problemas
para probar la consumación, sin embargo, bastará probarse que el sujeto activo introdujo
su miembro viril en la cavidad bucal de la víctima para alegar que estamos ante un delito
consumado, siendo irrelevante la eyaculación.
El uso de objetos y partes del cuerpo como modalidad del acceso carnal prohibido:
También se materializa el delito de violación sexual cuando el agente en lugar de usar su
órgano sexual, introduce por la vía vaginal o anal, objetos o partes del cuerpo. La amplia
ción de los instrumentos penetrantes en el campo sexual, tiene su explicación en el hecho
que actualmente no tiene mayorsentido lim itar los instrumentos de invasión al miembro
viril, pues si este es el único que puede afectar la reproducción, otros objetos son igual
mente idóneos para producir dicha afectación.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 997 of 1506 --

Tema 6: Temas de la Especialidad Penal
Medios típicos del acceso carnal prohibido:
i. Violencia: consiste en la energía física que desarrolla o ejerce el autor para doblegar
la resistencia u oposición de la víctima. La violencia se traduce en actos materiales
sobre la víctima (golpes, cogerla violentamente de las manos, etc.) tendientes a so
meterlo a un contexto sexual deseado por el agente, pero, a la vez, no querido ni
deseado por el sujeto pasivo.
En este supuesto, se debe señalar que la resistencia de la víctima no constituye un
elemento objetivo del tipo penal sino, solo sirve como un medio de prueba del acto
sexual no deseado. En ese sentido, no se exige un despliegue continuo de la fuerza
física del agente n i menos una conti nuada resistencia de la vícti ma, pues resulta des-
cabellado sostener que se excluye el delito de acceso carnal si la víctima no opone
resistencia.
De modo que, si no se verifique actos de resistencia de parte del sujeto pasivo, se
configura el ¡lícito penal siemprey cuando se acredite la falta de consentimiento de
la víctima o desacuerdo de aquella con el acto sexual practicado abusivamente por
el agente.
ii. Amenaza grave: consiste en el anuncio de un mal o perjuicio inminente para la víc
tim a, cuya finalidad es intim idarlo y se someta a un contexto sexual determinado.
No es necesario que la amenaza sea invencible sino meramente idónea y eficaz. La
amenaza es una violencia psicológica que naturalmente origina intimidación en la
víctima ante el anuncio de un mal futuro.
En este ámbito la amenaza es condicional. La condición es de carácter sexual: para
evitar el mal anunciado, el sujeto pasivo amenazado tiene que someterse al acceso
carnal que le impone el agente.
El mal a sufrirse, mediata o inmediatamente, puede constituirse en el daño de algún
interés de la víctima que le importa resguardar, como su propia persona, su honor,
sus bienes, secretos o personas ligadas por afecto, etc. La amenaza grave, aparte de
lesionar el proceso de formación de la voluntad de la persona, pone en peligro los
bienes sobre el que recae el mal anunciado.
Para la valoración de la intimidación, el juzgador debe tener en cuenta, de acuerdo
a la edad de la víctima, el contexto social o fam iliar que lo rodea. Es decir, el juzgado
deberá determinar si la víctima tuvo serios motivos para convencerse que solo su
aceptación de realizar el acto sexual, evitará el daño anunciadoy temido. Por lo tan
to, la gravedad de la amenaza se medida por la capacidad de influir en la decisión de
la víctima de manera Importante.
iii. Entorno de coacción: Comprende un lugaro espado, no necesariamente oculto o se
creto, ya que ello no es considerado como un requisito para realmente comprender
a una persona víctima del sufrimiento de la coacción en un claroy evidente perjuicio
contra esta.
Sujeto activo:
Actualmente, en el campo de los delitos sexuales la doctrina mayoritaria sostiene que siendo
el bien jurídico protegido la libertad sexual, cualquier persona que imponga la unión carnal
