UBILEX
o acceso carnal sexual, lesionando con ello la libertad sexual del sujeto pasivo, será autor del
delito de violación sexual.
En consecuencia, si la que impone el acto o acceso sexual por medio de violencia o amenaza gra
ve es la mujer, también se configurará el delito de acceso carnal sexual. Al vulnerarse, limitarse o
lesionarse la libertad sexual de la víctima, resulta intrascendente verificar quien accede a quien,
siendo posible que la mujer pueda vulnerar la libertad sexual de un varón uotra mujer.
Tipicidad subjetiva:
i. Dolo’:
El comportamiento delictivo de acceso carnal sexual exige la concurrencia de dolo, esto
es, el agente actúa con conocimiento y voluntad de la comisión del evento ilícito. Esto es,
se requiere que el sujeto activo tenga conocimiento que con la realización de las acciones
voluntarias que pone en movimiento la violencia o que origina la amenaza grave, some
terá a la víctima al acceso carnal sexual, poniéndole en un comportamiento pasivo con la
finalidad que soporte el acceso carnal sexual no querido por ella.
Si junto al dolo, al agente no le orienta o guía alguna satisfacción sexual, su conducta
queda al margen del Derecho penal.
ii. Elemento subjetivo adicional:
La misma naturaleza estructural del delito en comentario exige la concurrencia de un
elemento subjetivo adicional al dolo que se constituye en el objetivo o finalidad que per
sigue el agente con su conducta. La finalidad u objetivo que busca el autor al desarrollar
su conducta no es otro que la satisfacción de su apetencia o expectativa sexual.
Si aquel elemento subjetivo adicional, que la doctrina española lo conoce como ammus
tubhcus o ánimo lascivo, no se verifica en la realidad, y, por ejemplo, el agente solo actúa
motivado por la finalidad de lesionar a su víctima introduciéndole, ya sea por la cavidad
vaginal o anal, objetos o partes del cuerpo, se descartará la comisión del delito de acceso
carnal sexual violento. Sin margen de duda, en la mayoría de supuestos o hipótesis de
lictivas de violencia sexual, el autor obra con tendencia a finalidad principal lasciva, sin
embargo, no siempre es así, pues en la realidad se presentan atentados de carácter sexual
guiados por la finalidad o motivo principal de venganza, burla, curiosidad, despecho, etc.
De tal forma, si en determinada conducta de apariencia sexual no aparece la finalidad
de satisfacción sexual ya sea en forma principal o accesoria, y por el contrario solo se evi
dencia la intención o finalidad de lesionar la integridad física o el honor de la víctima, tal
conducta de agresión no constituirá el delito de acceso carnal sexual, canalizándose tal
hecho al delito de lesiones leves o graves, según sea la m agnitud de la agresión o en su
caso, el delito de injuria.
Circunstancias agravantes del delito de violación sexual:
a. Concurso de dos o más sujetos:
El concurso de dos o más sujetos que exige el tipo penal, debe ser en el hecho delictivo
mismo en que se produce el acceso carnal sexual. No antes no después,y ello solo puede
suceder cuando estamos ante la coautoría. Los instigadores y cómplices no cometen el
delito sino lo determinan y colaboran o auxilian, respectivamente, a los que realmente
