Tema 6: Temas de la Especialidad Penal
realizan el hecho punible. En suma, la agravante se configura cuando dos o más personas
participan en calidad de coautores del delito sexual.
En el caso que dos o más personan participen en la comisión del delito de violación sexual,
todas responderán a título de coautores así uno o varios de ellos no hayan realizado el acto
sexual con la víctima, limitándose solo, por ejemplo, a sujetar a la víctima o inmovilizarla.
Por otro lado, no se configura la agravante si una persona dolosamente determina a otro
cometer la violación sexual contra la víctima ya sea mediante un pago o persuadiéndola
(instigación). Asimismo, tampoco se configura la agravante cuando interviene una per
sona que solo se lim ita a vigilar para que otro sin contratiempos realice el acceso carnal
sexual con la víctima (complicidad).
b. El acceso carnal sexual se realiza a mano armada:
Esta agravante se configura cuando el agente con la finalidad de satisfacer su apetito se
xual, somete a su víctima al acto sexual violento utilizando un arma. El arma puede ser
un revólver, metralleta, arco, ballesta, puñal, hacha, verduguillo, cuchillo, pico, martillo,
vidrio, etc.
El uso del arma tiene como finalidad vencer la resistencia u oposición contraria de la víc
tima. El arma puede ser propia o impropia. Lo que interesa es el aumento del poder agre
sivo en el autory, a su vez, la mayor intimidación que ejerce sobre la víctima.
La agravante se fundamenta en el hecho concreto que el uso de un arma no solo mejora
la posición del agente, sino que también, disminuye ostensiblemente los mecanismos de
defensa del sujeto pasivo. No se exige el real uso del arma en la ejecución del acceso car
nal sexual no deseado por la víctima. Es suficiente el simple enseñar, mostrar o blandir en
gesto intim idante determinada arma. Cabe advertir que, el uso del arma puede ser tanto
para ejercer violencia sobre la víctima como para amenazarla, pues ambos mecanismos
configuran la agravante analizada.
c. El agente se haya prevalido de cualquier posición, cargo o parentesco:
El acoso u hostigamiento sexual: consiste en la conducta física o verbal reiterada de
naturaleza sexual no deseaday/o rechazada, realizado por una o más personas que
se aprovechan de una posición de autoridad o jerarquía, o cualquier otra situación
ventajosa, en contra de otra u otras, quienes rechazan estas conductas por conside
rar que afectan su dignidad.
El parentesco como agravante: en este supuesto, el agente se aprovecha de la rela
ción de parentesco que tiene con la víctima por ser ascendiente, descendiente, her
mano o cónyuge de este.
d. Agravante por la calidad o cualidad especial del agente:
Se agrava el delito de violación sexual cuando en su condición de miembro de las Fuerzas Ar
madas, Policía Nacional, serenazgo o policía municipal, el agente en pleno ejercicio de sufun-
ción pública de brindar seguridad a los ciudadanos, somete al acto sexual violento a la víctima.
La agravante se configura siempre y cuando el acceso carnal violento se haya producido
cuando el agente ejercía la función pública de brindar seguridad. En ese sentido, no es sufi
ciente que el agente reúna la condición personal que exige el tipo penal al momento de los
