Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1000 of 1506 --

UBILEX
1000
hechos, sino es necesario que el acceso carnal se haya producido en el tiempo que el sujeto
activo estaba ejecutando o realizando sus labores o actividades diarias en el marco de su
competencia funcional y territorial. Caso contrario, si por ejemplo, un miembro de la Policía
Nacional realiza el acto sexual bajo violencia en su “día de franco”, solo será denunciado y
sentenciado, de ser el caso, por la violación sexual simple. La agravante no se configura.
Agente portador de enfermedad de transmisión sexual:
Esta circunstancia agravante se configura cuando el agente sabiendo que es portador de
una enfermedad de transmisión sexual (ETS), haciendo uso de la violencia o amenaza
grave somete al acto carnal sexual a su víctima. El fundamento de la agravante radica en
el hecho que aparte de lesionar la libertad sexual, el agente pone en peligro la salud de la
víctima, toda vez que al someterlo al acto sexual existe latirm e posibilidad de contagiarlo
o transm itirle una enfermedad de transmisión sexual grave en perjuicio evidente de su
salud.
En efecto, se trata de una figura de peligro, pues no se exige necesariamente que el con
tagio se haya producido, sino solo el peligro que el contagio se produzca. Conforme lo
señala la doctrina española, la agravante requiere la concurrencia de tres aspectos:
que el autor sea portador de una enfermedad de transmisión sexual,
que con motivo del acto sexual realizado haya existido peligro de contagio.
que el autor al consumar el acceso sexual haya tenido conocimiento de ser portador
de la enfermedad.
El autor es docente o auxiliar de educación:
El inc. 5) del art. 170o del CP señala que la agravante del delito de violación sexual se pro
duce cuando: “el autor es docente o auxiliar de educación del centro educativo donde es
tudia la víctima". Esta agravante es innecesaria por dos motivos:
Primero, tal supuesto ya se encuentra previsto en la modalidad de violación sexual
cuando el agente para “la ejecución del delito se haya prevalido de cualquier posición o caro
que le dé particular autoridad sobre la víctima
Segundo, el legislador al utilizar la nomenclatura de "centro educativo" se está refi
riendo restrictivamente solo a las escuelas o colegios públicos o privados, lugar don
de están y estudian las personas, generalmente, hasta los 17 años de edad. Sin em
bargo, al haberse previsto de modo irracional como delito de violación sexual sobre
menor las conductas sexuales producidas contra menores de 18 años, la agravante
referida deviene en innecesaria, pues existe un tipo penal que sanciona las conduc
tas lesivas contra la indemnidad sexual de los menores.
Muerte de la víctima:
La agravante está prevista en el art. 177o del CP configurándose siemprey cuando el agen
te haya podido prever aquel resultado. Aquí la muerte debe ser producto del acceso carnal
sexual prohibido, pudiendo haberse realizado durante la consumación o materialización
del abuso sexual o como consecuencia inmediata de tal hecho. La muerte de la víctima
es un acontecer culposo que no estaba en los planes del agente, es decir, es un resultado
preterintencional.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1001 of 1506 --

Tema 6: Temas de la Especialidad Penal
Caso contrario, si llega a determinarse que el autor aparte de violentar sexualmente tenía pla
neado o previsto la muerte de su víctima, esta agravante es desplazada por un homicidio cali
ficado (asesinato) o en su caso, por un concurso real de delitos: violación sexual y homicidio.
h. Lesiones graves a la víctima:
También el art. 177o del CP establece como circunstancia agravante el hecho que a conse
cuencia del acceso carnal sexual el agente pudiendo prever el resultado, le haya ocasiona
do lesiones graves a su víctima. La verificación de la agravante exige que las lesiones cau
sadas deban tener la magnitud de las lesiones tipificadas en el art. 121o del CP, pudiendo
ser atentados contra la integridad física o salud mental de la víctima. Las lesiones deben
ser consecuencias inmediatas de la violación sexual.
Las lesiones no deben haber sido queridas no buscadas por el autor, estas deben produ
cirse a consecuencia de un actuar culposo o negligente del agente. Caso contrario, si son
producidas con dolo antes o después del acceso carnal sexual se excluirá la agravante,
apareciendo la figura de concurso real de delitos: violación sexual con lesiones graves.
i. Crueldad sobre la víctima:
Finalmente, el art. 177o del CP prevé la circunstancia agravante que se configura cuando el
agente procede o actúa con crueldad sobre su víctima. Es decir, cuando el agente realiza
el acceso carnal sexual haciendo sufrir en forma inexplicable e innecesaria a la víctima.
La violación sexual en la modalidad de crueldad sobre la víctima exige la concurrencia de
dos circunstancias que lo caracterizan: primero, que el sufrimiento ya sea físico o psíquico
de la víctima, haya sido aumentado deliberadamente por el agente. Este aparte de vio
lentar la libertad sexual de su víctima, guía la intención de hacerla sufrir. Segundo, que el
padecimiento sea innecesario y prescindible para lograr el acceso carnal sexual, ponien
do en evidencia el ensañamiento o insensibilidad del agente ante el dolor humano.
j. Si la víctima tiene entre catorce y menos de dieciocho años de edad:
Mediante la Ley N°30076 de fecha 19 de agosto de 2013 se introdujo la presente agravante
al delito de violación sexual, el cual positiviza la postura jurisprudencial de reconocimien
to de libertad sexual de los menores de edad entre catorce y menores de dieciocho años
de edad, derogando así el inciso 3 del artículo 173o del Código Penal.
Cabe recordar que el mediante el Acuerdo Plenario N° 04-2008/CJ-116 se introdujo una
interpretación doctrinal de la Corte Suprema con relación al inc. 3 del art. 173o del CP (vi
gente en esa fecha) con la finalidad de determinar si la libertad sexual o, en su caso, la
indemnidad sexual son bienes jurídicos de libre disposición, y si un menor cuya edad está
entre los catorce y dieciocho años tiene capacidad jurídica para disponer dicho bien. En
dicho Acuerdo Plenario señala que: «(...) en cuanto a la exención de responsabilidad penal por
consentimiento del titu la r del bien jurídico afectado, aplicable al delito de violación sexual a que se
refiere el artículo 173°, inciso 3), del Código Penal, debe ampliarse (...) a toda relación sexual volun
taria mantenida con adolescentes de catorce a dieciocho años de edad».
En efecto, el Tribunal Constitucional mediante la sentencia recaída en el Exp. 0008-2012-PI/
TC de fecha 24 de enero de 2013 declaró inconstitucional el inciso 3 del art. 173o del Código
Penal señalando que: “En cuanto a la titularidad del derecho a la libertad sexual como parte de su
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DESELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1002 of 1506 --

derecho al libre desarrollo de la personalidad, queda claro que son titulares todos los mayores de i 8
años de edad. En lo que al caso importa, el Tribunal Constitucional estima que, conforme a determi
nados elementos normativos y fácticos que operan en el ordenamiento jurídico peruano, prima facie,
los menores de edad entre 14 años y menos de 18 también pueden ser titulares de dicho derecho. Las
razones que justifican tal consideración son las siguientes: i) La Convención sobre los Derechos del niño,
(...). Por su parte, la Corte Interamericana de Derechos Humanos ha sostenido que “los niños y las ni
ñas ejercen sus derechos de manera progresiva a medida que desarrollan un mayor nivel de autonomía
personal. En consecuencia, el aplicador del derecho, sea en el ámbito administrativo o en el judicial,
deberá tom aren consideración las condiciones específicas del menor de edad y su interés superior para
acordar la participación de éste, según corresponda, en la determinación de sus derechos” [Caso Atala
Riffoy niñas vs. Chile, sentencia del 24 de febrero de 2012, párrafo 199). ü) Los artículos ly II del Títu
lo Preliminar del Código de los niñosy adolescentes (...). iii) La capacidad de los adolescentes entre 14
añosy menos de 18 para autodeterminarse en el ámbito de su sexualidad en el ordenamiento jurídico
peruano se encuentra acreditada, en general, por determinadas disposiciones legales en materia civily
penal, tal como lo resalta de manera acertada la jurisdicción penal en el Acuerdo Plenaño N ° 4 -2 0 0 8 /
C J-ii6 :(...). iv) En el “Estudio Diagnóstico en Adolescentes en el Perú”, elaborado por la Universidad
Peruana Cayetano Heredia (2005), con una población de 2181 adolescentes de 15 a 19 años, de Lima
Metropolitana, Huancayo e Iquitos, ciudades que, según se refere, son "representativas de los tres ám
bitos socio cultural y ecológico de nuestro país”, se sostuvo lo siguiente“La edad de inicio de relaciones
sexuales reportada en el grupo d e is a 19 años varía por ciudades, encontrándose las edades más tem
pranas en Iquitos. En estegrupo etario alrededor del 2 0 % de lasmujeresy 4 0 % de los varones reportan
ya haber tenido relaciones sexuales” (p. 30) [resaltado agregado], v) En la Encuesta Demográfica y de
Salud Familiar (EN DES) 2011, elaborada por el Instituto Nacional de Estadística e Informática (INEI),
se estableció, en cuanto a las características de la población,y específicamente a las “Mujeres en edad
fértil”, que “Las mujeres en edad fértil, de 15 a 49 años de edad, representaron el 25,3 por ciento de la
población total del paísy el 49,7 por ciento de la población femenina del país” [resaltado agregado], vi)
En el''Vlan Nacional de Acción por la Infanclay la Adolescencia 2012-2021", elaborado por el Ministerio
de la M ujer y Poblaciones Vulnerablesy aprobado mediante Decreto Supremo N.° 001-2012-MIMP, se
establece en el punto 2.4, denominado “la adolescencia de 12 a 17 años de edad”, que “de acuerdo a los
resultados de la Encuesta Demográfica y de Salud Fam iliar-EN D ES20i o, el 13,5 % de las adolescentes
de 15 a 19 años de edad tenían al menos una hija o hijo o estaban embarazadas de su primera hija o
prim er hijo” [resaltado agregado]. De lo expuesto, si bien se puede concluir que prima facie, los menores
de edad entre 14 añosy menos de 18, en tanto titulares del derecho fundamental al libre desarrollo de
la personalidad (en el ámbito de la libertad sexual) pueden ejercerlo, también se debe concluirá su vez
dos asuntos de la mayor importancia: i) que conforme al principio de evolución de facultades del niñoy
del adolescente, debe reconocerse que tales adolescentes irán desarrollando, progresivamente, el nivel
psicofísico óptimo de ejercicio del mencionado derecho fundamental, para lo cual es indispensable la
educación que sobre el particular puedan brindarlos padres, el Estadoy la sociedad en genera fy , ii) que
poseer dicha libertad sexual implica también conocer las consecuencias que puede originar su ejercicio,
tal como se destaca en el mencionado “Plan Nacional de Acción por la Infancia y la Adolescencia 2012-
2021” según el cual "existe consenso en que el embarazo en edad temprana es un evento que afecta
la salud física, mental y social de la futura madre, así como del recién nacido. Para las adolescentes
madres o embarazadas pobres, la maternidad viene acompañada de una serie de situaciones adversas
que empeoran su condición. Estas madres a menudo sufren carenciasy tensiones; además, su ambiente
