C. DELITO DE VIOLACIÓN SEXUAL DE MENOR DE EDAD
El delito más grave previsto dentro de la sección “delitos contra la libertad sexual” en nuestro
Código Penal lo constituye el ilícito penal denominado acceso carnal sexual sobre un menor.
Este hecho punible se configura cuando el agente tiene acceso carnal sexual por la cavidad
vaginal, anal o bucal o realizando actos análogos introduciendo objetos o partes del cuerpo
por la vía vaginal o anal, con una persona menor de dieciocho años de edad.
Descripción normativa:
Art, 173 CR "El que tiene acceso carnal por vía vaginal, anal o bucal o realiza cualquier otro acto análogo
con la Introducción de unobjeto: o partedeí cuerpo por alguna de lasdos primeras víasr con un menor:
de catorce años, será reprimido con pena de cadena perpetua."
Tipicidad objetiva
De la redacción del tipo penal se desprende, con claridad, que la verificación del delito de ac
ceso sexual sobre un menor de catorce años de edad no se necesita que el agente actúe ha
ciendo uso de violencia, intimidación, la inconsciencia o el engaño. En tal sentido, si la víctima
presta su consentimiento para realizar el acceso carnal sexual o análogo, el delito se configura,
pues de acuerdo a nuestra Legislación, la voluntad de los menores, cuya edad se encuentra
entre el acto de nacimiento hasta menos de catorce años, no tiene eficacia positiva para hacer
desaparecer la ilicitud del acto sexual del sujeto activo.
Al respecto, tenemos las siguientes ejecutorias supremas:
0 EL CONSENTIMIENTO DE LA VICTIMA ES IRRELEVANTE PARA EXCULPAR Y PARA- LOS
EFECTOS DE REDUCCION DE PENA. "El supuesto consentimiento prestado por la victima resulta
irrelevante para los efectos del presente casor por cuanto la figura de <violación presuntas no
admite el consentimiento como acto exculpatorio ni para los efectos de la reducción de pena,
por cuanto en todos estos casos siempre se tendrán dichos actos como violación sexual, dado
que lo que se protege es la indemnidad sexual de los menores". R.N. N ° 0458- 2003-Callao.
0 INVALIDEZ DEL CONSENTIMIENTO. Aun cuando el imputado no ejerció violencia física o
amenazas contra la agraviada V.R.M.T. para tener acceso carnal con ella, por su minoría de edad tal consenti
miento resulta inexistente. Cas. N ° 308- 2018, Moquegua.
Tipicidad subjetiva
De la redacción del tipo penal se desprende que se trata de un delito de comisión dolosa y que
no cabe la comisión imprudente. Al respecto, la jurisprudencia a sostenido que: «Tratándose
de afirmaciones que el propio acusado formula, fluyen de las mismas que él era consciente tanto de la
conducta que realizaba como de la m inoridad de la agraviada y de su posición respecto de ella, sirviendo
de sustento probatorio del momento subjetivo lo que se tiene referido para el objetivo.»
