UBILEX
1 ^La consumación del delito en análisis se acredita fundamentalmente con el certificado mé
dico legal, documento en el cual los especialistas de medicina legal describen si ha llegado a
producirse la penetración del miembro viril, objetos o partes del cuerpo en la cavidad vaginal
o anal de la víctima menor. Asimismo, se describe las huellas dejadas sobre el cuerpo de la
víctima, el posible uso de la fuerza o violencia por parte del agente.
En los estragos judiciales no existe otro documento que sirva para probar tales circunstan
cias. Al respecto, la jurisprudencia señala: «La comisión del delito de violación sexual de menor está
acreditado con el certificado médico legal de la menor agraviada, que describe el inicio de la relaciones
sexuales a los nueve años, himen con desgarros antiguos en horas II, H ly lV .a l examen de la región anal en
posición genupectural, ano normotómico con borra miento de pliegues en horas XII, II y VI, observándose
depresión del área perianal a horas XII; al examen corporal, presenta cicatrices rosadas recientes en re
gión anterior del cuello derecho e izquierdo de forma semicirculares; concluyéndose que presenta himen
con desfloración antigua, signos de coito contra natura y lesiones extragenitales en fase cicatrización.»
D. ACTOS CONTRA EL PUDOR
1. Tocamientos, actos de connotación sexual o actos libidinosos sin consentimiento
Descripción normativa:
“Art 176 CP. Tocamientos, actos de connotación sexual o actos libidinosos sin consentimiento
El que sin propósito de tener acceso carnal regulado por el artículo 170, realiza sobre una persona, sin
su libre consentimiento, tocamientos, actos de connotación sexual o actos libidinosos, en sus^partes^
íntimas o en cualquier parte de su cuerpo será reprimido con pena privativa de libertad no menor de
tres ni mayor de seis años.
Si el agente realiza la conducta descrita en el prim er párrafo, mediante amenaza, violencia, o aprovechándose
de un entorno de coacción o de cualquier otro que impida a la víctima dar su libre consentimiento, o valiéndose
de cualquiera de estos medios obliga a la víctima a realizarlos sobre el agente, sobre sí misma o sobre tercero,
la pena privativa de libertad será no menor de seis ni mayor de nueve años.
En cualquiera de los casos previstos en el prim er y segundo párrafos, la pena privativa de libertad se incremen
ta en cinco años en los extremos mínimo y máximo, si la víctima es mayor de catorce y menor de dieciocho
Bien jurídico protegido: se pretende tutelar una esfera de libertad personal in fieri que en el
futuro se materializará en un ámbito básico de libre desarrollo de la personalidad del sujeto.
Tipicidad objetiva
El delito denominado “actos contrarios al pudor de una persona” se configura cuando el sujeto
activo sin tener el propósito de practicar el acceso carnal sexual vía vaginal, anal o bucal uotro
análogo como introducción de objetos o partes del cuerpo vía vaginal o anal, haciendo uso
de la violencia o la amenaza grave, realiza sobre su víctima u obliga a esta a efectuar sobre sí
misma o sobre tercero, tocamientos indebidos en sus partes íntimas o actos libidinosos con
trarios al pudor.
Aquí pudor se entiende como la situación de recato, decencia o decoro del que gozamos todas
las personas en sociedad.
