Tema 6: Tem as de la Especialidad Pena!
De la redacción del tipo penal se evidencia que los comportamientos contra el pudor, recato o
decoro de personas pueden realizarse hasta por tres modalidades:
Primero, cuando el agente por medio de la violencia o amenaza realiza sobre la víctima to
camientos indebidos en sus partes íntimas o actos libidinosos.
La segunda modalidad se configura cuando el agente obliga a su víctima a realizarse a sí mis
ma tocamientos indebidos o eróticos. Por ejemplo, Hans obliga a Tania amenazándola con un arma
de fuego a sacarse toda su vestimenta y luego la exige que se toque sus partes íntimasy zonas erógenas.
Finalmente, la tercera modalidad se configura cuando el agente obliga que la víctima rea
lice o efectúe tocamientos indebidos o actos lujuriosos en el cuerpo de un tercero que se
encuentra en la escena del delito.
Agravantes:
Art, 176 CR (...) Si el agente realiza la conducta descrita en el primer párrafo, mediante amenaza, vio- :
lencia, o aprovechándose de un entorno de coacción o de cualquier otro que impida a la víctima dar \
su líbre consentimiento, o valiéndose de cualquiera de estos medios obliga a la víctima a realizarlos
sobre el agente, sobre sí misma o sobre tercero, la pena privativa de libertad será no menor de seis ni
