en cinco años en los extremos mínimo y máximo, s i la víctima es mayor de catorce y menor de dieciocho años.
Tipicidad subjetiva
Se trata de un delito necesariamente doloso. No cabe la comisión por imprudencia, es decir,
si llega a evidenciarse, por ejemplo, tocamientos en los genitales de una persona de manera
casual o imprudente, el delito no se configura por falta de tipicidad.
2. Tocamientos, actos de connotación sexual o actos libidinosos en agravio de menores
Descripción normativa:
Artículo 176-A CR "El que sin propósito de tener acceso carnal regulado en el artículo 170, realiza so
bre un menor de catorce años u obliga a este a efectuar sobre sí mismo, sobre el agente o tercero,
tocamientos indebidos en sus partes íntimas, actos de connotación sexual en cualquier parte de su
cuerpo o actos libidinosos, será reprimido con pena privativa de libertad no menor de nueve ni mayor
de quince años."
Bien jurídico protegido: en los atentados contra personas que no pueden consentir juríd i
camente, entre otros presupuestos, por su minoría de edad, lo que se protege es la llamada
''''intangibilidad” o “indemnidad sexual”. Se sanciona la actividad sexual en sí misma, aunque
exista tolerancia de la víctima, puesto que lo protegido son las condiciones físicas o psíquicas
para el ejercicio sexual en libertad161. R.N. N° 1431-2022 Jlunín. Fjs.yy 8 .
