Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 1006 of 1506 --

UBILEX
1. “Sin propósito de tener acceso camal". Esta referencia legal típica permite distinguir y delim i
tar un acto contrario al pudor de una tentativa de violación sexual.
2. “Realiza sobre un menor de catorce años u obliga a este a efectuar sobre sí mismo o terceros toca-
mientos indebidos en sus partes íntimas". Esta modalidad delictiva implica la imposición (por
el agente) de una conducta sexual no aceptada, la cual no solo se determina por las pro
pias características de los comportamientos delictivos, sino también por el contexto (ac
ción, m odoy tiempo) en el que se ejecuta.
3. “Realiza sobre un menor de catorce años actos libidinosos contrarios al pudor”. Son actos libidino
sos (lascivos, lúbricos, eróticos, lujuriosos e impúdicos) sobre el cuerpo de la víctima con
trarios al pudor, los cuales se realizan con la finalidad de obtener una satisfacción erótica
o lujuriosa que atenta contra el pudor de la víctima. R.N. N ° 1431-2022 Junín. Fjs.y y 8.
Tipicidad subjetiva. El dolo consiste en la finalidad del autor de satisfacer su deseo sexual con
los tocamientos o actos libidinosos. R.N. N ° 1431-2022 Junín. Fjs.y yS .
El agente ha de conocer la conducta que realiza sin el consentimiento de la víctima, y la tras
cendencia de su acción sin propósito de tener acceso carnal; esto es, debe tener el conocimien
to del significado sexual de su conducta. El ánimo lubrico o lascivo por parte del sujeto activo
no está exigido por el tenor literal del Código Penal. No se puede aceptar que el autor persiga
satisfacer su apetito sexual, basta para su realización típica el conocimiento del agente de la
puesta en peligro del bien por la acción agresiva o de imposición de una conducta a la víctima.
Cas. N° 2386-2021 Huánuco. Fj.3.
