Tema 6: Tem as de la Especialidad Penal
Igual penase aplica a quien realiza la misma conducta valiéndose del uso de cualquier tecnología de la infor
mación o de la comunicación o cualquier otro medio tecnológico.
La pena privativa de la libertad será no menor de cuatro ni mayor de ocho años e inhabilitación, según corres
ponda, conforme a los incisos 5,9 ,10 y 11 del artículo 36, si concurre alguna de las circunstancias agravantes:
1. La víctima es persona adulta mayor, se encuentra en estado de gestación o es persona con discapacidad.
2. La víctima y el agente tienen o han tenido una relación de pareja, son o han sido convivientes o cónyuges,
tienen vínculo parental hasta el cuarto grado de consanguinidad o segundo de afinidad.
3. La víctima habita en el mismo domicilio que el agente o comparten espacios comunes de una misma
propiedad.
4. La víctima se encuentra en condición de dependencia o subordinación con respecto al agente,
5. La conducta se lleva a cabo en el marco de una relación laboral, educativa o formativa de la víctima,
6. La víctima tiene entre catorce y menos de dieciocho años".
Bien jurídico protegido: El tipo penal tiene como bien jurídico de protección la libertad sexual
de la agraviada162.
Tipicidad objetiva: Es un delito de modo reiteradoytambién contemplaque la conducta pue
da ser realizada en un solo acto163.
Sujeto activo: es el victimario quien realiza los actos de perturbación de la libertad de la víc
tima; actos como vigilar, perseguir, hostigar, asediar o buscar establecer contacto o cercanía
con una persona, sin el consentimiento de esta para llevar a cabo actos de connotación sexual,
alterando de esta manera el normal desarrollo de la vida cotidiana de la víctima164.
Sujeto pasivo: es la víctima, es decir, contra quien el victimario practica los actos de perturba
ción y altera el normal desarrollo de su vida cotidiana con fines sexuales165.
Tipicidad Subjetiva: Desde la perspectiva subjetiva se exige que la acción sea dolosa. El autor
debe tener pleno conocimiento de que está prohibido todo acto de vigilar, perseguir, hosti
gar, asediar o buscar establecer contacto o cercanía con una persona, sin el consentimiento
de esta, para llevar a cabo actos de connotación sexual, alterando de esta manera el normal
desarrollo de la vida cotidiana de la víctima, y voluntariamente decide no cum plirlo166.
Agravantes:
"Art, 176-B CP. (...) La pena privativa de la libertad será no menor de cuatro ni mayor de ocho años .
e inhabilitación, según corresponda, conforme a los incisos 5, 9,10 y 11 del artículo 36, si concurre i
alguna de las circunstancias agravantes:
1, La víctima es persona adulta mayor, se encuentra en estado de gestación o es persona con dis
capacidad,
2. La víctima y el agente tienen o han tenido una relación de pareja, son o han sido convivientes o cónyuges,:
tienen vínculo parental hasta el cuarto grado de consanguinidad o segundo de afinidad.
3. La víctima habita en el mismo domicilio que el agente o comparten espacios comunes de una misma propiedad.
4. La víctima se encuentra en condición de dependencia o subordinación con respecto al agente.
5. La conducta se lleva a cabo en el marco de una relación laboral, educativa o formativa de la víctima.
6. La víctima tiene entre catorce y menos de dieciocho añ os"
