G. CHANTAJE SEXUAL
Descripción normativa:
"Art. 176-C C R - El que amenaza o intimida a una persona, por cualquier medio, incluyendo el uso de
tecnologías de la información o comunicación, para obtener de ella una conducta o acto de connota
ción sexual, será reprimido con pena privativa de la libertad no menor de dos ni mayor de cuatro años
e inhabilitación, según corresponda, conforme a los incisos 6, 9,10 y 11 del artículo 36.
La pena privativa de libertad será no menor de tres ni mayor de cinco años e inhabilitación, según co
rresponda, conforme a ios incisos 5, 9,10 y 11 del artículo 36, si para la ejecución del delito el agente amenaza
a la víctima con la difusión de imágenes, materiales audiovisuales o audíos con contenido sexual en los que
esta aparece o participa
Bien jurídico protegido: Se advierte que el bien jurídico protegido lo constituye el derecho a la
libertad sexual, pues por medio de la amenaza o la intimación se pretende limitarlo. El propó
sito del agente es lesional o poneren peligro la libertad sexual de la su víctima167.
Tipicidad objetiva: Es necesario que el agente tenga la intención de sacar un provecho sexual
con su conducta amenazante. Si en un caso concreto se determina que la intención o le itm o tiv
del sujeto activo no fue obligar a que la víctima compre su silencio con un acto de naturaleza
sexual, sino otra diferente, la figura penal de chantaje sexual no se verifica. Esto es, se configu
rará el delito de chantaje previstoy sancionado en el artículo zoi del Código Penal, cuando por
ejemplo, el agente haciendo uso de la amenaza tiene la intención de que el agente compre su
silencio por un beneficio patrimonial.
Finalmente, este delito no puede confundirse con el delito de acceso carnal sexual, logrado
por medio de amenaza, previsto en el artículo 170 del Código Penal, pues este delito se confi
gura con la simple amenaza, en cambio el delito de acceso carnal sexual se configura cuando
el agente, a consecuencia de la amenaza, logra tener el acceso carnal sexual en contra de su
voluntad168.
"En ese sentido, puede concluirse razonablemente que lo que buscaba el imputado con los
mensajes de texto enviados a la agraviada, no era solamente retomar una relación sentimental,
sino realizar actos de connotación sexual con ella. De otro lado, el imputado continuamente
amenazó a la menor agraviada con publicar las fotos desnudas de ella, sino accedía a salir una
última vez con él con la finalidad de realizar actos de connotación sexual, como ocurrió en el
pasado cuando eran enamorados."169
167 SALINAS SICCHA, Ramiro. Derecho Penal-Parte Especio!. Tomoi. Editorial Grijley-lustitia, 2019, p. 1158.
168 Idem.
169 Exp. N° 1026-2021-14. Segunda Sala Penal Superior. Fj.13.
8 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 1009 of 1506 --

Tema 6: Tem as de la Especialidad Penal
Sujeto activo: El sujeto activo, agente o actor puede ser cualquier persona imputable. El tipo
penal no exige alguna cualidad, calidad o condición especial. Se trata, en consecuencia, de un
delito común o de dominio.
Si bien es cierto el tipo penal no exige cualidad, calidad o condición especial respecto al sujeto
activo, no obstante, en muchos casos este actuar delictivo puede provenir de una persona del
entorno, como la ex pareja sentimental, que utiliza cualquier medio para vejar o chantajear
y conseguir el retorno sentimental de la pareja o ejercer una situación de control o domina
ción, incluso bajo la amenaza de la difusión de imágenes, materiales audiovisuales o audios
de contenido sexual en los que esta aparece o participa; estas situaciones también presentarse
en el marco de la relación laboral, educativa o form ativa.170
Sujeto pasivo: La víctima, el sujeto pasivo o la persona contra la que está dirigida la conducta
amenazante del agente para obligarle a comprar su silencio, también puede ser cualquier per
sona física. El tipo penal no exige alguna cualidad especial en ella171.
Tipicidad Subjetiva: El delito de chantaje es netamente doloso, no cabe lacomisión culposa o
imprudente. Esto es, el agente actúa con conocimiento y voluntad de hacer saber a su víctima
que se dispone a publicar, denunciar o revelar un hecho o conducta perjudicial para ella, con
el propósito específico de determinarla a comprar su silencio a cambio de la realización de un
acto de connotación sexual172.
Agravantes:
“Árt.176-C CP.- (...) ■ ’
La pena privativa de libertad será no menor de tres ni mayor de cinco años e inhabilitación, según co- ■
rresponda, conforme a los incisos 5,9 ,10 y 77 del artículo 36, si para la ejecución del delito el agente
amenaza a la víctima con la difusión de imágenes, materiales audiovisuales o audios con contenido sexual en
los que esta aparece o participa."
Tentativa y consumación: La figura delictiva del chantaje se perfecciona o consuma con el
solo anuncio del agente que se dispone a publicar, denunciar un hecho o conducta perjudicial
si la víctima no le compra su silencio por medio de una conducta de carácter sexual. Basta que
el agente intente o trate de hacer que la víctima compre su silencio para estar frente al chan
taje sexual consumado. Para la consumación no interesa que la víctima llegue realmente a
realizar la conducta sexual exigida ni que el agente haya satisfecho sus expectativas sexuales.
Es suficiente que se anuncie la divulgación de un hecho o conducta perjudicial. En el caso de la
modalidad agravada es suficiente que el agente amenace con difundir imágenes, materiales
audiovisuales o audios con contenido sexual en los que la víctima aparece o participa, para
obtener de ella un acto de connotación sexual.
170 SALINAS SICCHA, Ramiro. Derecho Penal-Parte Especial. Tomo i. Editorial Grijley-lustitia, 2019, p. 1158.
171 Idem, p.1158.
172 Idem. pp. 1158, 1159.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R A M IE N TO DE JUECES Y FISCALES 100

-- 1010 of 1506 --

UBILEX
Siendo así, jurídico-penalmente no es posible que se presente la figura de la tentativa en el
delito de chantaje sexual173.
10. PROXENETISMO
Descripción normativa:
"Art, 181 CP. El que dirige o gestiona la prostitución de otra persona será reprimido con pena privativa
de libertad no menor de cuatro ni mayor de seis años.
La pena será no menor de seis ni mayor de doce años, cuando:
1. El agente cometa el delito en el ámbito del turismo, en el marco de la actividad de una persona
jurídica o en el contexto de cualquier actividad económica.
2. El agente sea ascendiente o descendiente por consanguinidad, adopción o por afinidad, pariente colate
ral hasta el cuarto grado de consanguinidad o adopción o segundo grado de afinidad: cónyuge, excónyuge,
conviviente, exconviviente o tenga hijos en común con la víctima o habite en el mismo domicilio de la víctima,
siempre que no medien relaciones contractuales o laborales.
3. El proxenetismo sea un medio de subsistencia del agente.
4. La víctima esté en situación de abandono o extrema necesidad económica.
5. Exista pluralidad de personas en prostitución.
6. La persona en prostitución tenga discapacidad, sea adulta mayor, padezca de una enfermedad grave, perte
nezca a un pueblo indígena u originario o presente cualquier situación de vulnerabilidad.
7. Se produzca una lesión grave o se ponga en peligro inminente la vida o la salud de la persona en prostitución.
8. El agente actúe como integrante de una banda u organización criminal."
Bien jurídico protegido
Identificamos el bien jurídico protegido de este delito en la dignidad humana, aunque tal
como está planteado, el tipo penal no parece afectar, siquiera abstractamente, el referido bien
jurídico. Sin embargo, no es posible afirmar que el bien jurídico protegido es la libertad se
xual, porque el tipo penal nunca exige que se lleve a cabo la relación sexual. Ni siquiera exige
que la víctima haya dado un consentimiento viciado paradlo, ni que haya sido efectivamente
entregada a un tercero para ello. Solo basta con la sola conducta de seducción, sustracción o
compromiso para que este se consume.
En tal sentido, lo único que se pretende tutelar con este delito es que la víctima no se vea ex
puesta a una situación de vulnerabilidad para su dignidad como la que se presenta cuando es
entregada a otra persona para que tenga acceso carnal. Se pretende que la víctima no corra
peligro de ser instrumentalizada sexualmente.
Tipicidad objetiva
La conducta delictiva que consiste en comprometer, seducir o sustraer a una persona para en
tregarla a otra con el objeto de mantener acceso carnal (vaginal, anal o bucal) a cambio de una
compensación pecuniaria. Por comprometer se entiende crearen el sujeto pasivo una obliga
ción con otro, de tal modo que resulte exigióle su cumplimiento. De otro lado, seducir, afirma
la doctrina legal, implica engañar o encauzara alguien hacia la toma de una decisión equivo
cada a través del ofrecimiento de un bien. En tanto que sustraer conlleva el apartar, separar o
extraer a una persona del ámbito de seguridad en el que se encuentra.
173 Idem, p.1159.
I
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1011 of 1506 --

Tema 6: Temas de la Especialidad Penal
Como el tipo penal no señala, en forma específica, los medios para el logro de la finalidad
delictiva pueden emplearse cualquier clase de medios, siendo los principales la violencia o la
intimidación.
V il Pleno Jurisdiccional de las Salas Penales Permanente y Transitoria de la Corte Suprema de Justicia de
lA » la República. Acuerdo Plenario N° 3 -2 0 1 1/C J-116 . - - ;
q H j f e S L r "La conducta delictiva consiste en comprometer, seducir o sustraerá una persona para entre- ''
■ ■ ■ garla a otra con el objeto de mantener acceso carnal (vaginal, anal o bucal) a cambio de una ■
compensación pecuniaria. Por comprometer se entiende crear en el sujeto pasivo una obliga
ción con otro, de tal modo que resulte exigible su cumplimiento. Por otro lado, seducir implica ■
engañar o encauzar a alguien hacia la toma de una decisión equivocada a través del ofrecí
miento de un bien. En tanto que sustraer conlleva el apartar, separar o extraer a una persona del ámbito de
seguridad en el que se encuentra El tipo penal no hace referencia a los medios que pueda emplear el agente
para la realización de dichos comportamientos. Generalmente, se empleará algún medio de coerción como la
violencia o intimidación [Bramont-Arias Torres, Luis Alberto / García Cantizano, María del Carmen, Manual de
Derecho Penal, Parte Especial, 4 a ed., Editorial San Marcos, Lima, 2004, p, 273f.
El sujeto activo de este delito se le denomina proxeneta y es conocido, generalmente, como
el facilita u organiza relaciones de prostitución entre dos o más personas, con ánimo de lucro.
Vil Pleno Jurisdiccional de las Salas Penales Permanente y Transitoria de la Corte Suprema de Justicia d e .
la República. Acuerdo Plenario N* 3-2011 /C J - 116.
"En el delito de proxenetismo el agente directamente Interviene en el comercio sexual de la
víctima a la cual, previamente, convence o compromete para que se entregue sexualmente por
una contraprestación económica a terceros. El agente en este delito oferta y administra la pros
titución de la víctima. Desarrolla pues un negocio ¡legal en torno a la venta sexual de a q u é l l a :
Diferencia entre tratante, promotor y proxeneta:
Se podría gradear las diferencias entre tratante, promotor y proxeneta señalando que el pri
mero actúa como proveedor; el segundo como impulsor o facilitador; y, el tercero como ex-
pendedory gestor de la prostitución de las víctimas.
Por consiguiente, el concurso real entre estos tres delitos [Trata de personas, favorecimien-
to de la prostitución y proxenetismo] resulta ser la posibilidad más técnica de conectarlos
hipotéticamente. Así, quien práctica la trata puede, también, dedicarse de modo sucesivo o
paralelo a la promoción o explotación directa de la persona a quien captó, trasladó o retuvo
inicialmente con la finalidad de entregarla a terceros promotores de la prostitución o proxe
netas potenciales o en ejercicio.
En consecuencia, el Juzgador debe analizar con precisión la conducta objetiva y subjetiva del
agente, incidiendo predominantemente en la finalidad perseguida, así como en el modus
operandi y los antecedentes del imputado, para, en base a tales circunstancias o indicadores,
calificar adecuadamente la relevancia penal de los imputados en el caso sub judice.
Identificada la autonomía típica, teleológicay dogmática de los delitos de trata de personas,
favorecí miento de la prostitución y proxenetismo, así como sus posibilidades concúrsales, res
ta señalar que la presencia de circunstancias agravantes específicas similares para cada delito
no afecta tal independencia formal y material, ni lim ita o compromete de alguna manera la
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES ion

-- 1012 of 1506 --

UBILEX
■ ■ determinación judicial de la penaen caso de concurso real. En efecto, como estipulael artículo
50o Código Penal corresponde al Juez determinar penas concretas parciales por separado y
para cada delito integrante del concurso real [Acuerdo Plenario N°4-2009/CJ-i i 6. Asunto: De
terminación de la Penay Concurso Real], Será en ese único espacio donde el Juzgador deberá
identificar las agravantes específicas concurrentes. Las cuales, por lo demás, pueden ser las
mismas en cada delito (minoría de edad de la víctima) o sólo alcanzar a los delitos de favore-
cimiento de la prostitución o proxenetismo, mas no de trata de personas (empleo de medios
violentos o abuso de autoridad).
Tipicidad subjetiva
El tipo penal exige el dolo en la conducta del autory el ánimo de lucro. En la generalidad de los
supuestos del tipo no se hace referencia al ánimo de lucro que posee el sujeto activo, pero este
elemento subjetivo es evidente, cualquier otro interés no oneroso es intrascendente, porque
lo que definitivamente mueve al proxeneta es el lucro.
11. FAVORECIMIENTO A LA PROSTITUCION
Descripción normativa:
(t "Art. 179 CP. "El que promueve o favorece la prostitución de otra persona, será reprimido con pena
privativa de libertad no menor de cuatro ni mayor de seis años.
La pena será no menor de seis ni mayor de doce años cuando:
7. El agente cometa el delito en el ámbito del turismo, en el marco de la actividad de una persona
jurídica o en el contexto de cualquier actividad económica.
2. El agente es ascendiente o descendiente por consanguinidad, adopción o por afinidad, pariente colateral
hasta el cuarto grado de consanguinidad o adopción o segundo grado de afinidad; cónyuge, excónyuge, con
viviente, exconviviente o tenga hijos en común con la víctima; o habite en el mismo domicilio de la víctima,
siempre que no medien relaciones contractuales o laborales.
3. Es un medio de subsistencia del agente.
4. La víctima esté en situación de abandono o extrema necesidad económica.
5. Se realice respecto a una pluralidad de personas.
6. La persona en prostitución tenga discapacidad, sea adulta mayor, padezca de una enfermedad grave, perte
nezca a un pueblo indígena u originario o presente cualquier situación de vulnerabilidad.
7. Cuando el agente, a sabiendas, favorezca o promueva actos de prostitución violentos que produzcan lesio
nes o ponga en peligro grave la integridad o la vida de quien realice la prostitución.
8. El agente actúe como integrante de una banda u organización criminal".
Bien jurídico protegido
Algunos autores nacionales, aunque cuestionan la legitimidad de la intervención penal en
esta clase de delitos, sostienen que el bien jurídico protegido por este delito sería la moral
sexual acuñada por ciertos sectores de la sociedad174. Si bien compartimos la cuestionable le
gitim idad político criminal de la tipificación de este delito (en el caso de víctimas mayores
de edad), consideramos que no coadyuva con el principio de lesividad, considerar como bien
jurídico protegido a la m oral sexual.
174 PEÑA CABRERA FREYRE, Alonso Raúl. Op. Cit. 49; Salinas Siccha, Ramiro. Curso de Derecho Penal Peruano. Parte
Especial II, Lima: Palestra, 2002. p. 429; y Villa Stein, Javier. Derecho Penal. Parte Especial l-B. Lima: San Marcos,
1998. p. 214.
K E B BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1013 of 1506 --

Tema 6: Temas de la Especialidad Penal
Se trata de un concepto extremadamente vago y subjetivo dado que su contenido se presta a
ser llenado con criterios religiosos dominantes. En esa perspectiva, consideramos que el bien
jurídico protegido en este delito es también la dignidad de la persona contextual izada en el
ámbito de la sexualidad. Entendemos por dignidad sexual al principio o derecho de todo ser
humano (mayor o menor de edad) a no ser instrumentalizado por otro, a no ser tratado como
objeto de cambio o mercancía sexual. Evidentemente, no se trata de un delito de lesión o de
peligro concreto hacia la dignidad sexual de una persona en la medida que no se requiere que
el sujeto pasivo del delito (mayor de edad) se encuentre en situación efectiva de explotación
sexual o que se hayan empleado medios coercitivos para determinar a una persona a ejercer
la prostitución (como ocurre en el caso de trata de personas).
Tipicidad objetiva:
En nuestra opinión el delito de favorecí miento a la prostitución es un delito de peligro abs
tracto en la medida que actos de promoción o favorecimiento (sin medios coercitivos) de la
prostitución ajena (de mayores de edad) constituyen actos de promoción o favorecimiento a
una situación (la prostitución) que en abstracto (o mediatamente) pueden conllevarsu explo
tación o instrumentalización.
En el caso concreto no se requiere verificarla puesta en peligro (proximidad espacio-temporal
a la lesión) del bien jurídico ni su lesión efectiva, sino que se presupone per se la peligrosidad
de la conducta.175 Se establece normativamente que el hecho de que una persona promocione
o favorezca la prostitución de otra, implica por sí misma un peligro para la dignidad humana.
Esto debido a que las personas que ejercen la prostitución se encuentran más expuestas y
vulnerables a que sean objeto de explotación o instrumentalización.
La acción típica de este delito consiste en promover o favorecer la prostitución de otra persona.
Comosostiene ladoctrina, promoveres hacerque alguien se inicieen determinada acción, in
citar o ejercer influencia en alguien que decida realizar cierto comportamiento; por otro lado,
favorecer es sinónimo de coadyuvar, cooperar, colaboraren algo.176
Ahora bien, debemos tomar en cuenta que la agravante del numeral 2° del artículo 179o del
Código Penal sanciona al sujeto activo de este delito que emplea violencia, engaño, abuso de
autoridad, o cualquier medio de intimidación para promover o favorecer la prostitución. Es
decir, se recurre a medios coercitivos o fraudulentos para viciar el consentimiento de la vícti
ma, lo cual convertiría a la prostitución sexual en una con rasgos de explotación.
Tipicidad subjetiva:
El delito exige que el autor que favorece o promueve la prostitución de otra persona lo realice
con dolo, es decir, conocimiento y voluntad.
12. RUFIANISIMO
Desde nuestra perspectiva, el rufianísimo es la forma más grave de proxenetismo. El concepto
de explotación puede tener dos sentidos. En el presente caso comprendemos la explotación
175 MIR PUIC, Santiago. Op. Cit. p. 234-
176 PEÑA CABRERA FREYRE, Alonso Raúl. Op. C it pp. 51-52.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1014 of 1506 --

UBILEX
como aprovechamiento económico del ejercicio de la prostitución ajena. El rufián en estricto
no promueve o facilita la prostitución, sino que disfruta del ejercicio de la misma cuando es
realizada por otra persona. Por lo tanto, resulta inherente a esta definición el ánimo de obte
ner provecho (ánimo de lucro) por parte del rufián.
Teniendo en cuenta esta definición, el rufianísimo no exige necesariamente un vicio de la vo
luntad por parte de la prostituta ni ausencia de consentimiento. Es altamente probable que el
rufianísimo coincida con actos de coacción, violencia o amenaza dirigidas contra la prostituta,
sin embargo, ello no siempre tiene que ocurrir así. Es probable, en consecuencia, que la explo
tación del ejercicio de la prostitución ajena no suponga a la prostituta actos de restricción de
su libertad o situación de violación a sus derechos humanos.
Descripción normativa:
"Art. ISO CP. El que gestiona el beneficio económico o de otra índole de la prostitución de otra persona
será reprimido con pena privativa de libertad no menor de cuatro ni mayor de ocho años.
La pena privativa de libertad será no menor de seis ni mayor de doce años cuando:
l El agente cometa el delito en el ámbito del turismo, en el marco de la actividad de una persona jurí
dica o en el contexto de cualquier actividad económica.
2¡ El agente es: ascendientes descendiente por consanguinidad, adopción o por afinidad, pariente colateral
hasta el cuarto grado de consanguinidad, o adopción o segundo grado de afinidad; cónyuge, excónyuge, con
viviente, exconvíviente o tenga hijos en común con la víctima; o habite en el mismo domicilio de la víctima,
siempre que no medien relaciones contractuales o laborales.
3. Es un medio de subsistencia del agente.
4. La víctima esté en situación de abandono o extrema necesidad económica.
5. Exista pluralidad de personas en prostitución.
6. La persona en prostitución tenga discapacídad, sea adulta mayor, padezca de una enfermedad grave, perte
nezca a un pueblo indígena u originario o presente cualquier situación de vulnerabilidad.
7. El agente actúe como integrante de una banda u organización criminal".
Bien jurídico protegido:
Difícilmente se puede sostener que en este delito el bien jurídico protegido es la libertad se
xual, pues al igual que en el delito de promoción y favorecí miento a la prostitución, no existe
ningún medio coercitivo o fraudulento que limite la voluntad o vicie el consentimiento de la
víctima para que decida ejercer la prostitución. Es así que también reconocemos como objeto
de tutela de este delito a la dignidad humana conforme la entendimos precedentemente, de
tal forma que aquel que se aprovecha económicamente de la prostitución de otra persona
despliega una conducta que de alguna forma expone a la víctima a que caiga en un circuito de
explotación sexual en donde se vulneren sus derechos humanos.
Es decir, a partir de un supuesto de aprovechamiento del servicio o las ganancias del ejercicio
libre de la prostitución ajena podríamos pasar a una situación de explotación de la prostituta
en tanto tal (más que de sus servicios) y de afectación de sus derechos fundamentales. Estaría
mos, al igual que en delito del artículoi79°del Código Penal, ante un delito de peligro abstrac
to, pues el mero comportamiento de explotación de ganancias provenientes de la prostitución
de otra persona ya se aprecia por el legislador como peligrosa para la dignidad humana, sin
necesidad de constatar concretamente la cercanía espaciotemporal a su lesión efectiva.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1015 of 1506 --

Tema 6: Temas de la Especialidad Penal
T íp íc íd a d o b je tiv a
La acción típica de este delito consiste en explotar la ganancia de una persona dedicada al
meretricio o ser mantenido por ella total o parcialmente. La explotación en el delito de rufia
nísimo debe ser entendida como el aprovechamiento económico del ejercicio de la actividad
sexual o del ejercicio de un oficio o profesión de otra persona.
Tipicidad subjetiva:
De la redacción del tipo penal se desprende que el autor o “rufián” debe actuar con dolo.
13. DELITOS AMBIENTALES
13.1. Delito de contaminación
Descripción normativa:
"Art. 304 CP. El que, infringiendo leyes, reglamentos o límites máximos permisibles, provoque o realice
descargas, emisiones, emisiones de gases tóxicos, emisiones de ruido, filtraciones, vertimientos o
radiaciones contaminantes en la atmósfera, el suelo, el subsuelo, las aguas terrestres, marítimas o
subterráneas, que cause o pueda causar perjuicio, alteración o daño grave al ambiente o sus campo-
nenies, la calidad ambiental o la salud ambiental, será reprimido con pena privativa de libertad no menor de,
cuatro años ni mayor de seis años y con cien a seiscientos días-multa.
Si el agente actuó por culpa, la pena será privativa de libertad no mayor de tres años o prestación de servicios
comunitarios de cuarenta a ochenta jornadas.”
Bien jurídico protegido: Mediante la tipificación y sanción de la conducta antes descrita se
busca proteger al bien jurídico “estabilidad del medio ambiente”, el mismo que debe ser tu
telado en la medida que es indispensable para la vlday salud de las personasy también en la
medida que el desarrollo de éstas implica el acceso a una serle de valores paisajísticos, eco
nómicos, de calidad de vida, de solidaridad con las futuras generaciones, etc., valores estric
tamente ecológicos en suma, inviables sin la utilización racional de los recursos naturales. Por
todo ello es que el medio ambiente reclama una protección anticipaday el tipo penal materia
de análisis se configura como un delito de peligro concreto.
Tipicidad objetiva: Sí bien la conducta proscrita exige que sea provocada mediante el vocablo
“contaminación”177, la misma presenta dos restricciones.
La primera está expresada en el verbo rector del tipo: contaminar, que debe ser entendida en
la modalidad de “vertidos”. La voz verter gramaticalmente significa derramar o vaciar líquidos
y también cosas menudas; sal, harina, etc.178. Si bien el tipo penal no indica a donde serán ver
tidos los contaminantes en el medio ambiente se entiende que el destino será en el aire, agua
177 El Dr. Carlos Caro define a la contaminación como “(...) si acto de lograr la presencia en el ambiente de ana o más
contaminantes, o cualquier otra combinación de ellos en concentración o en niveles capaces de comprometer, perjudicar o
incomodarla vida, la salud o el bienestar humano." en: Caro Coria, Carlos, Protección Penal del ambiente, Lima, 1995, p.
281. Por su parte, el Dr. Pierre Foy lo define como “(...) el acto o el resultado de introducir artificialmente en un medio
dado, cualquier elemento o factor que altere negativamente las propiedades bióticas del mismo, pomo estar neutralizado
por mecanismos compensatorios naturales." en: Foy Valencia, Pierre, En busca del derecho ambiental, en: Derecho y
ambiente. Aproximaciones y Estimativas. PUCP, Lima, 1997, p .m .
178 Real Academia Española. Diccionario de la lengua española, tomo II, Madrid, 1992, p. 2081.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1016 of 1506 --

UBILEX
o suelo. Los vertidos pueden ser de forma inmediata o directa que se realiza sobre un curso de
agua, cauce público o canal de riego, o de forma indirecta ya que puede realizarse a través de
azarbe, canales de desagüey pluviales.
Por otro lado, la segunda restricción del tipo está referida al medio empleado. Ello significa que
los vertidos deben realizar a través de “residuos” sólidos, líquidos, gaseosos o de cualquier otra
naturaleza cualquiera sea el campo en el que el hombre desenvuelva sus actividades industria
les, agrícolas, sociales o domésticas. Gramaticalmente residuo significa “lo que resulta de la des
composición o destrucción de una cosa”179. En ese sentido, residuo es lo restante, lo que queda
después, de ser sometido a un proceso determinado o sea la parte aprovechable tras ese proceso.
Entonces la adecuación típica de los verbos rectores de “contaminar” mediante "vertidos re
siduales” está condicionada a una serie de elementos normativos y descriptivos, entre lo que
se destaca la dependencia a las infracciones de la legislación administrativa, que es en últim a
instancia, el que define el tipo básico de la contaminación en el medio ambiente. En ese senti
do, se describirá la norma prevista en el art. 304o del Código Penal como una ley penal en blan
co (accesoriedad de la norma administrativa) por cuanto debe recurrir a normas extrapenales
de carácter administrativo concerniente a la Legislación Am biental180 establecer cuando una
conducta se encuentra circunscrita en el tipo penal materia de análisis.
En cuanto a la tipicidad objetiva, conforme a lo prevé el profesor García Cavero, debemos par
tir que el delito de contaminación en el medio ambiente es un delito de infracción de un de
ber en donde la imputación del comportamiento se determina por la infracción de un deber
positivo específico (velar por la estabilidad del ecosistema) mientras que la realización del
resultado se aprecia como una forma de configuración de la sociedad que el vinculado debió
haberevitado (contamina el medio ambiente)181.
Como es evidente las empresas que se dedican a la exploración y explotación de recursos na
turales utilizan determinados químicos para poder desarrollar cabalmente sus actividades;
sin embrago, los residuos de estos materiales tienen caracteres tóxicos en el supuesto que
sean vertidos dentro del medio ambiente por lo que necesitan de un tratam iento especial que
los neutraliza. En ese sentido, la Administración como titu lar de los recursos explotados exige
a las mineras un plan institucional (conforme a Ley) que busque descartar cualquier tipo de
impacto ambiental de sus materiales residuales.
En este orden de ideas, las empresas mineras, en virtud al título concesorio que ostentan a fin
de poder explorary explotar recursos naturales, también tienen el deber especial de proteger
el medio ambiente durante el desarrollo de sus actividades por lo que la imputación del com
portamiento tendrá lugar cuando exista la posibilidad de cumplim iento del deber especial
que se ha incumplido. Para ello, es necesario que estos deberes especiales se encuentres pre
vistos en normas formales (Ley general del Am bientey directivas del OSINERGMIN).
Asimismo, el delito de contaminación ambiental exige la realización de un resultado (“que
causen o puedan causar perjuicio o alteraciones en la flora, faunay recursos hidrobiológicos”)
por lo no será suficiente la imputación del comportamiento. Como señala el profesor García
179 Ibidem, p. 1263.
180 Ejecutoria Suprema, de fecha 12 de agosto de 2003, emitido por Sala Transitoria de la Corte Suprema de Justi-
ca en el Exp. R.N. N° 1389-2003.
181 GARCÍA CAVERO, Percy, Op. cit., p. 435.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1017 of 1506 --

Tema 6: Temas de la Especialidad Penal
Cavero se debe tener presente que “(...) en los delitos de infracción de un deber el resultado no
se presenta como la realización de un riesgo prohibido, sino como la producción de una situa
ción que no se corresponde con la pretendida por la institución social en cuestión”182. En ese
sentido, en el delito de contaminación del medio ambiente el resultado será la desestabilidad
del ecosistema, situación que no corresponde con el deberexigido por la Administración a las
empresas que exploran y explotan recursos naturales.
Tipicidad subjetiva:
En cuanto a la tipicidad subjetiva, el delito de contaminación ambiental exige la concurrencia
de dolo. Este elemento subjetivo abarca el conocimiento del carácter antijurídico de los he
chos porque de otra forma no sería posible poder imputarle subjetivamente al autorel incum
plimiento de un deber positivo institucionalmente exigido.
Para la configuración del injusto de contaminación culposo debe observarse varios elementos
a saber: i) rebasar los límites mínimos permitidos, que contienen en la norma extra penal;
ii) que dicha contravención administrativa genere un riesgo jurídicamente desaprobado con
aptitud de lesión al bien jurídico protegido; y, ¡ii) que la lesión y/o afectación de dicho interés
sea consecuencia directa del riesgo no permitido, provocado por la conducta del agente.
Así, si bien el tipo penal de contaminación ambiental es de naturaleza mixta, no es menos
cierto que el injusto imprudente de éste, únicamente podrá ser objeto de sanción penal, cuan
do se constate un daño al medio ambiente o alguno de sus componentes. Descartándose que
la realización de un peligro de aptitud de lesión culposa puede ser alcanzado por una pena. Si
no existe dolo en la esfera subjetiva del injusto, la reacción estatal ha de ser el Derecho A dm i
nistrativo Sancionador.
Agravantes:
"Art. 305.- Formas agravadas
La pena privativa de libertad será no menor de cuatro años ni mayor de siete años y con trescientos a
mil días-multa si el agente incurre en cualquiera de los siguientes supuestos:
h Falsea u oculta información sobre el hecho contaminante, la cantidad o calidad de las descargas,
emisiones, filtraciones, vertimientos o radiaciones contaminantes referidos en el artículo 304, a la autoridad
competente o a la institución autorizada para realizar labores de fiscalización o auditoría ambiental.
2. Obstaculiza o impide la actividad fiscalizadora de auditoría ordenada por la autoridad administrativa com
petente.
3. Actúa clandestinamente en el ejercicio de su actividad.
4. Desactiva o deja inactivas las áreas, labores, e instalaciones de una unidad minera sin contar o sin cumplir
el respectivo Plan de Cierre de Minas aprobado.
Si por efecto de la actividad contaminante se producen lesiones graves o muerte, la pena será:
1. Privativa de libertad no menor de cinco años ni mayor de ocho años y con seiscientos a mil días-multa, en
caso de lesiones graves.
2. Privativa de libertad no menor de seis años ni mayor de diez años y con setecientos cincuenta a tres mil
quinientos días-multa, en caso de muerte."
182 Ibidem, p. 439.
