UBILEX
13.2. Incumplimiento de las normas relativas al manejo de residuos sólidos (Alt. 306 C.P):
El que, sin autorización o aprobación de la autoridad competente, establece un vertedero o
botadero de residuos sólidos que pueda perjudicar gravemente la calidad del ambiente, la
salud humana o la Integridad de los procesos ecológicos, será reprimido con pena privativa de
libertad no mayor de cuatro años.
Si el agente actuó por culpa, la pena será privativa de libertad no mayor de dos años.
Cuando el agente, contraviniendo leyes, reglamentos o disposiciones establecidas, utiliza
desechQS sólidos para la alimentación de animales destinados al consumo humano, la pena
será no menor de tres años ni mayor de seis años y con doscientos sesenta a cuatrocientos
cincuenta días-multa.
13.3. Tráfico ilegal de residuos peligrosos (Art. 307 C.P.):
El que ingrese ilegalmente al territorio nacional, use, emplee, coloque, traslade o disponga
sin la debida autorización, residuos o desechos tóxicos o peligrosos para el ambiente, resul
tantes de un proceso de producción, extracción, transformación, utilización o consumo, será
reprimido con pena privativa de libertad no menor de cuatro años ni mayor de seis añosy con
trescientos a cuatrocientos días-multa.
13.4. Delito de minería ilegal
Descripción normativa:
"Art. 307-A CR El que realice actividad de exploración, extracción, explotación u otro acto similar de re
cursos minerales metálicos y no metálicos sin contar con la autorización de la entidad administrativa
competente que cause o pueda causar perjuicio, alteración o daño al ambiente y sus componentes,s
la calidad ambiental o la salud ambiental, será reprimido con pena privativa de libertad no menor de
cuatro ni mayor de ocho años y con cien a seiscientos días-multa.
La misma pena será aplicada al que realice actividad de exploración, extracción, explotación u otro acto similar
de recursos minerales metálicos y no metálicos que se encuentre fuera del proceso de formalización, que
cause o pueda causar perjuicio, alteración o daño al ambiente y sus componentes, la calidad ambiental o la
salud ambiental.
Si el agente actuó por culpa, la pena será privativa de libertad, no mayor de tres o con prestación de servicios
comunitarios de cuarenta a ochenta jornadas."
Tipicidad objetiva:
El núcleo típico de este delito está caracterizado por la realización de actividades explorato
rias, extractivas, o de explotación sobre recursos minerales, sin tener la autorización adminis
trativa pertinente.
Sin embargo, el artículo 307-A del Código Penal prevé exigencias típicas adicionales como: i)
que la actividad del agente, cuando menos, pueda causar perjuicio, alteración o daño al am
biente o a sus componentes, a la calidad ambiental o a la salud ambiental (con lo cual no es
necesario verificar la producción de un perjuicio efectivo, sino solo la aptitud perjudicial de la
conducta); i I) la referencia a una cláusula amplia que permite apreciar el delito frente a moda
lidades distintas a las explícitamente mencionadas en el tipo (actos similares a la exploración,
extracción y explotación).
8 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

