Tema 6: Temas de la Especialidad Penal
La posibilidad de perjuicio al medio ambiente dota de contenido material a este delito y lo
aleja de ser una mera contravención administrativa consistente en realizar actividades mine
ras sin autorización.
Tipicidad subjetiva
El tipo penal exige la concurrencia del dolo en el agente; sin embargo, el últim o párrafo con
templa una modalidad imprudente, para la cual contempla una pena alternativa de no más
de tres años de privación de libertad o prestación de servicios comunitarios de cuarenta a
ochenta jornadas.
Agravantes:
® “Art. 307-B CR
La pena será no menor de ocho años n¡ mayor de diez años y con trescientos a m il días-multa, cuando
el delito previsto en el anterior artículo se comete en cualquiera de los siguientes supuestos:
1. En zonas no permitidas para el desarrollo de actividad minera.
2. En áreas naturales protegidas, o en tierras de comunidades nativas, campesinas o indígenas.
3. Utilizando dragas, artefactos u otros instrumentos similares.
4. SI el agente emplea instrumentos u objetos capaces de poner en peligro la vida, la salud o el patrimonio de
las personas,
5, Si se afecta sistemas de Irrigación o aguas destinados al consumo humano.
6. Si el agente se aprovecha de su condición de funcionario o servidor público.
7. Sí el agente emplea para la comisión del delito a menores de edad u otra persona inimputable."
Las modalidades agravadas de este delito prevén que las actividades realizadas por el agente
se lleven a cabo: i) En zonas no permitidas para el desarrollo de la actividad minera; ii) En
áreas naturales protegidas, o en tierras de comunidades nativas, campesinas o indígenas; iii)
Utilizando dragas, artefactos u otros instrumentos similares; iv) Empleando instrumentos u
objetos capaces de poner en peligro la vida, la salud o el patrimonio de las personas; v) Afec
tando sistemas de irrigación o aguas destinados al consumo humano; vi) Aprovechando su
condición de funcionario o servidor público; vii) Empleando para la comisión del delito a me
nores de edad u otra persona inimputable.
Dos aspectos importantes de la norma son:
i) Por un lado, la penalización del fmanciamiento de la minería ilegal (Art. 307-C);
ii) Por otro, la obstaculización de la evaluación, control y fiscalización de la autoridad adminis
trativa relacionada con la minería ilegal (Art. 307-D), pues permite luchar contra las condi
ciones que permiten su perpetración así como contra las que permiten su impunidad.
Asimismo, debe mencionarse que el Art. 307-E tipifica los actos preparatorios de la minería
ilegal. Dicho precepto tiene como verbos rectores al adquirir; vender, distribuir, comercializar y
poseer insumos o maquinarias destinadas a la comisión de los delitos de minería ilegal. Es im
portante señalar que, en rigor, tales comportamientos suelen ser un paso previo a la ejecución
del delito y, por lo mismo, no deberían ser punibles. Sin embargo, el legislador, con base en un
criterio político criminal de máxima protección del medio ambiente, ha decidido adelantar las
barreras de punibilidady criminalizartales actos preparatorios.
El agente de los delitos previstos en los artículos 307--A, 307-B, 307-C, 307-D y 307-E, será ade
más sancionado, de conformidad con el artículo 36, inciso 4, con la pena de inhabilitación para
