14. DELITOS TRIBUTARIOS Y ADUANEROS
14.1. DELITO TRIBUTARIO
En relación al área del Derecho Penal Tributario, en estricto es Derecho Penal con incidencia
tributaria, ésta reúne al conjunto de las normas que describen las contravenciones, las viola
ciones, las infracciones a los deberes y a las responsabilidades que tienen los deudores tribu
tarios. Generalmente tienen como finalidad evitar el pago de la deuda tributaria, utilizando
o abusando de las disposiciones legales que deben cumplir, tanto en relación a la obligación
tributaria, como a los deberes de naturaleza formal.
En nuestro Código encontramos las normas que regulan al Derecho Penal Tributario, en el Li
bro IVdnfracciones, Sanciones y Delitos”. Asimismo, existen normas de naturaleza específica,
mediante las cuales el legislador regula el derecho penal tributario, nos estamos refiriendo al
Código Penal y a la Ley Penal Tributaria (Decreto Legislativo N °8i 3), entre otras.
En cuanto al Delito Tributario “es toda acción u omisión que importe violación de normas tri
butarias de índole sustancial o formal, constituye infracción sancionable”.
Existen dos tesis que señalan cual es el bien jurídico tutelado en esta clase de delitos:
Tesis patrimonialista.-sostienen que lo que se tutela es el patrimonio de la hacienda pública.
Tesis funcionalista.-se refieren a la protección del sistema o funcionamiento de la hacienda pú
blica, entendida como el sistema de recaudación de ingresosy realización del gasto público.
Criterios para determinar el delito tributario:
