Tema 6: Temas de la Especialidad Penal
En cuanto a su contenido: En el delito tributario existe más gravedady mayor trascenden
cia social, porque aquí si se presenta la voluntad criminal.
Violación de la norma: en el delito tributario se infringe maliciosamente la norma trib u
taria tipificada penalmente.
En cuanto a la culpabilidad: se manifiesta por la intención de engañaral fisco.
En cuanto a la investigación y procedimiento: al igual que los demás delitos de investiga-
cióny juzgamiento, le corresponde al Poder] udicial.
En cuanto a la sanción: al delito tributario le corresponde una sanción penal, por estar
previsto en la ley como conclusión de un proceso penal.
TIPOS PENALES
1. Defraudación tributaria
Descripción normativa:
TArfcT (M eg¿ M 3)-£l que, en provecho propio o de un tercero, valiéndose de cualquier artificio, engaño,
M ^ ^ ^ 0 iS Í É ^ iÍ i0 o r m a fraudulenta, deja de pagar en todo o en parte los tributos que establecen las
