Tipicidad objetiva:
El sujeto pasivo es el Estado y la colectividad.
El comportamiento consiste en defraudar, esto es en incumplir la obligación tributaria de pa
gar total o parcialmente los tributos que indica la ley, valiéndose de artificio, engaño, astucia,
ardid u otra forma fraudulenta.
La tipicidad subjetiva está dada por el dolo, así como el ánimo de lucro. Se consuma con la
producción del perjuicio económico, que tiene lugar desde el momento en que no se paga, en
todo o en parte el tributo.
Son modalidades de defraudación tributaria (Art. 2 D.Leg. 813). Estas conductas son reprim i
das con la pena del art. 41o del CP:
a) Ocultar, total o parcialmente, bienes, ingresos rentas, o consignar pasivos total o parcial
mente falsos para anular o reducir el tributo a pagar.
b) No entregaral acreedor tributarlo el monto de las retenciones o percepciones de tributos
que se hubieren efectuado, dentro del plazo que para hacerlo fijen las leyes y reglamen
tos pertinentes.
2. Tipo agravado de la defraudación tributaria (Art. 4» D.Leg. N° 813)
La defraudación tributaria va a ser reprimida con pena privativa de libertad no menor de 8 ni
mayor de 12 años y con 730 a 1460 días multa cuando:
a) Se obtenga exoneraciones o inafectaciones, reintegros, saldos a favor, crédito fiscal, com
pensaciones, devoluciones, beneficios o incentivos tributarios, simulando la existencia
de hechos que permitan gozar de los mismos.
