Tema 6: Temas de la Especialidad Penal
5. Delito tribu tario por guardar recursos con valor superior a 50 UIT en lugares no
declarados (Art. 5-Bf D. Leg. N° 1114)
Será reprimido con pena privativa de libertad no menor de 2 ni mayor de 5 años y con 180
365 días-m ulta, el que estando anotado o bien no frente al órgano administrador del tributo
guarda recursos para su distribución, comercialización, trasferencia y otra forma de predis
posición, cuyo valor total supere las cincuenta UIT, en lugares no declarados como domicilio
fiscal o bien establecimiento anejo, en el plazo que para hacerlo fijen las leyes y reglamentos
pertinentes, para parar de pagar en todo o bien en parte los tributos que establecen las leyes.
Para este efecto se considera:
a) Comovalorde los bienes, a aquél consignado en el (los) comprobante(s) de pago. Cuando
por cualquier causa el valor no sea fehaciente, no esté determinado o no exista compro
bante de pago, la valorización se realizará teniendo en cuenta el valor de mercado a la
fecha de la inspección realizada por la SUNAT, el cual será determinado conforme a las
normas que regulan el Impuesto a la Renta.
b) La Unidad Impositiva Tributaria (UIT) vigente a la fecha de la inspección a que se refiere el
literal anterior.
C o n d u cta típ ica:
Guardar recursos en lugares no declarados.
Valor de los recursos superior a cincuenta UIT.
6. Delito tributario por confeccionar, obtener, vender o bien facilitar comprobantes
de pago, indebidamente, para cometer o bien posibilitar la comisión de delitos
tributarios. (Art. 5-C, D. Leg. N° 1114)
Será reprimido con pena privativa de libertad no menor de 5 ni mayor de 8 años y con 365 a
730 días-multa, el que confeccione, consiga, venda o bien facilite, a cualquier título, Compro
bantes de Pago, Guías de Remisión, Notas de Crédito o bien Notas de Débito, con el objeto de
cometer o bien perm itir la comisión de delitos tipificados en la Ley Penal Tributaria.
C o n d u cta s típ ica s:
El acto de elaborar, conseguir, vender o bien facilitar comprobantes de pago.
El objeto es cometer o bien permitir delitos tributarios (inferir gastos irreales, crédito fiscal).
Ejem plo: En el caso de facturas clonadas, cuando esta es emitida por una compañía Informal
(no registrada en SUNAT) que suplanta a una compañía formal y efectúa una venta o bien
servicio con dicha factura, produce un incremento del débito fiscal a la compañía formal y una
supuesta omisión de ingresos para está causándole de este modo contingencias tributarias.
De este modo, la compañía informal consigue ingresos por ventas sin carga tributaria, a costa
de dañar de forma directa a la compañía formal que suplanta; violando el deber de contribuir
a los gastos públicos a través de un sistema fiscal justo, de Igualdad, positiva progresividady
conforme a nuestra capacidad económica.
