14.2. Delitos aduaneros
El Dec. Leg. N°i542 que modificó la Ley N° 28008 que establece los delitos aduaneros, cuyo
bien jurídico protegido es el proceso de ingresos y egresos del Estado, pero referido específica
mente a los que percibe el Estado a través del control aduanero de las mercancías.
La referida norma señala los siguientes delitos:
Contrabando, defraudación de rentas de aduana, receptación aduanera, financiam ientoy trá
fico de mercancías prohibidas o restringidas.
B ien ju ríd ic o protegido: Estará constituido p o rla s relaciones emanadas de un libre comercio
nacional e internacional.”
T ip o su b je tivo : Es exigióle la existencia de dolo o sea la concienciay voluntad del agente acti
vo de cometer determinado delito aduanero.
T en tativa : Será reprimida la tentativa con la pena mínima legal que corresponda al delito con
sumado Se exceptúa de punición los casos en los que el agente se desista voluntariamente de
proseguir con los actos de ejecución del delito o impida que se produzca el resultado.
La dogmática penal hace la salvedad en el caso de que los actos practicados constituyan por
si otros delitos.
1. Delito de contrabando
D escrip ció n n o rm a tiva :
"Alt. 70 L e y N ° 2 8 0 0 8 m odificado p o r Dec. Leg. N ° 1 5 4 2 .- Contrabando
Comete delito de contrabando y es reprimido con pena privativa de la libertad no menor de cinco ni
mayor de ocho años y con trescientos sesenta y cinco a setecientos treinta días-multa, siempre que el
valor de las mercancías sea superior a cuatro (4) Unidades Impositivas Tributarias, el que:
a) Interna mercancías del extranjero al territorio nacional sustrayendo, eludiendo o burlando el control
aduanero.
b) Extrae mercancías del territorio nacional sustrayendo, eludiendo o burlando el control aduanero.
c) No presenta las mercancías para la verificación, reconocimiento físico u otra acción de control aduanero
dentro del proceso de despacho aduanero. La acción de ocultar o sustraer la mercancía al control adua
nero equivale a la no presentación.
