Tema 6: Temas de la Especialidad Penal
d) Extrae, consume, dispone o utiliza las mercancías que se encuentran en la zona prim ariaóelim itadapor
la Ley General de Aduanas, sin que la Administración Aduanera haya otorgado el levante o autorizado el
retiro, según corresponda.
e) Consume, almacena, dispone o utiliza las mercancías durante el traslado, autorizado por la Adminis
tración Aduanera, de una zona primaria a otra, para su reconocimiento físico u otra acción de control
aduanero, sin el pago previo de los tributos o gravámenes.
f) Interna mercancías de una zona franca, zona de tratamiento aduanero especial o zona de tributación
especial y sujeta a un régimen especial arancelario hacia el resto del territorio nacional sin contar con la ;
autorización de la Administración Aduanera, el pago previo de los tributos diferenciales o sin el cumplí- ;
miento de otros requisitos de ley.
g) Conduce en cualquier medio de transporte, hace circular, embarca, desembarca o transborda mercan
cías dentro del territorio nacional, sin que hayan sido sometidas al control aduanero".
Tipicidadobjetiva: En el contrabando la esencia de la conducta delictuosa está dada en la expre
sión sustrayendo, eludiendo o burlando el control aduanero, internando, extrayendo mercancías, o
no presentando las mercancías para la verificación del control aduanero o previo pago de los tribu
tos diferenciales, ingresando mercaderías del extranjero o las extrae de territorio nacional.
Se entiende por ingreso, el internamiento físico que se hace de mercaderías por un valorsupe-
rior a cuatro unidades impositivas tributarias. Este internamiento físico debe sobrepasar los
límites geográficos del Estado peruano para configurar la consumación.
En relación a la extracción, cabe precisar que se trata de la exportación, entendida ésta en un
sentido físicoy no económico, en otras palabras, es el traslado de mercancías del ámbito geo
gráfico peruano al ámbito geográfico de otro Estado.
El concepto de territorio expresado por el art.i°d el Código Penal es entendido en su real sentido
desde una perspectiva jurídica y no geográfica; sin embargo, para efectos del contrabando se
hace razonable únicamente aceptar un criterio de territorio entendido en sentido geográfico.
El comportamiento de ingresando o extrayendo ha de realizarse eludiendo o burlando el con
trol aduanero mercancías sin control aduanero o sin el pago de tributos diferenciales. El tipo
base no precisa los medios para logrartal fin, por lo que cabe la utilización de cualquier medio
o forma para burlar dicho control.
El art. i° de la Ley N° 28008 modificado por Dec. Leg. 1542 precisa las formas de realizar este he
cho. Por ejemplo, Internar mercancías de una zona franca, sin contar con la autorización de la Ad
ministración Aduanera, el pago previo de los tributos diferenciales, o interna o extrae mercan
cías del extranjero al territorio nacional sustrayendo, eludiendo o burlando el control aduanero.
En cuanto a los medios, si bien es válido cualquiera que el agente pueda utilizar, es factible ejem
plificar como lanzándola desde el aire por paracaídas, por correo público privado, por transporte
terrestre, marítimo o aéreo o por medio de traficantes profesionales. En cuanto al monto de las
mercaderías éstas deben superar las cuatro unidades impositivas tributarias. Si es inferior a esta
cuantía estaremos ante una “infracción administrativa de Contrabando”.
Tipicidad subjetiva: Se trata de un delito eminentemente doloso. El dolo que se exige pre-
ponderantemente es el dolo directo de primer grado; en cuanto al dolo eventual, es de más
difícil realización. Además el tipo no exige la concurrencia de algún ánimo trascendente como
el lucro, incrementar la economía, satisfacer un deseo cualquiera, etc.
Modalidades de contrabando: Según el art. i° de la Ley N° 28008 modificado por Dec. Leg.
1542, serán reprimidas con pena privativa de libertad no menor de cinco ni mayor de ocho
