I años y con trescientos sesenta y cinco a setecientos treinta días multa las siguientes modali
dades del delito de contrabando que superen las 04UITS:
a) Interna mercancías del extranjero al territorio nacional sustrayendo, eludiendo o bur
lando el control aduanero: Este inciso hace referencia al ingreso ilegal de la mercadería, lo
que significa introducir mercadería sin los requisitos que la ley Aduanera prescribe. Se preci
sa también, porel tipo penal, que este hecho deba producirse burlando el control aduanero.
Esto hace referencia también a aquel supuesto en el cual el agente ingresa la mercadería por
una ruta distinta a la ruta legal exigidayque lo debiera encaminar a la aduana de su destino,
en este segundo caso se precisaría también que el agente burle el control aduanero.
b) Extrae mercancías del territorio nacional sustrayendo, eludiendo o burlando el con
trol aduanero: Este inciso hace referencia a la extracción ilegal de la mercadería, lo que
significa sacar mercadería sin los requisitos que la ley Aduanera prescribe. Se precisa tam
bién, por el tipo penal, que este hecho deba producirse burlando el control aduanero.
Esto hace referencia también a aquel supuesto en el cual el agente se extrae la mercadería
por una ruta distinta a la ruta legal exigiday que lo debiera encaminar a la aduana de su
destino, burlando el control aduanero.
c) No presenta las mercancías para la verificación, reconocimiento físico u otra acción
de control aduanero dentro del proceso de despacho aduanero. La acción de ocultar o
sustraer la mercancía al control aduanero equivale a la no presentación: Con esta mo
dalidad se remarca la protección jurídico penal del control aduanero, en la conducta del
sujeto que transporta por cualquier medio una mercadería que él sabe producto de contra
bando y evita la verificación, reconocimiento físico, esto es la no presentación para su res
pectivo control. Evidentemente el sujeto no seguirá la ruta que lo lleve al control aduanero,
sino que lo burlará. Se dice que se ha remarcado la protección jurídico-penal debido a que
el transportista (terrestre, marítimo o aéreo) más allá que exista o no la presente disposi
ción deberá responder penalmente como cómplice primario o secundario o como coautor
dependiendo de la evaluación que se haga de la situación en la que el sujeto se encuentre,
esto es, si es solo contratado para el transporte o si además tiene la obligación del reglstroy
control. Las mercaderías a transportarse deberán sobrepasar las cuatro unidades tributarias
ya que si no la actividad del transportista no enmarcaría dentro de la infracción de contra
bando (Art. 35°del Dec. Leg. N°i542. Ley de los Delitos Aduaneros),
d) Extrae, consume, dispone o utiliza las mercancías que se encuentran en la zona pri
maria delimitada por la Ley General de Aduanas, sin que la Administración Aduanera
haya otorgado el levante o autorizado el retiro, según corresponda: La acción para ser
típica debe producirse antes del levante, retiro autorizado por la administración aduane
ra, esto implica antes de la diligencia de reconocimiento de las mercaderías, diligencia
que la realizará el funcionario acreditado en el local donde se hallen dichas mercaderías.
e) Consume, almacena, dispone o utiliza las mercancías durante el traslado, autorizado
por la Administración Aduanera, de una zona primaria a otra, para su reconocimiento
físico u otra acción de control aduanero, sin el pago previo de los tributos o graváme
nes: La acción para ser típica debe producirse antes del levante, retiro autorizado por la
administración aduanera, esto implica el pago de los tributos diferenciales, antes de la
diligencia de reconocimiento de las mercaderías, diligencia que la realizará el funciona
rio acreditado en el local donde se hallen dichas mercaderías.
