f) interna mercancías de una zona franca, zona de tratamiento aduanero especial o zona
de tributación especia! y sujeta a un régimen especial arancelario hacía el resto del te
rritorio nacional sin contar con la autorización de la Administración Aduanera, el pago
previo de los tributos diferenciales o sin el cumplimiento de otros requisitos de ley: Este
inciso requiere inicialmente que las mercancías se ubiquen en territorio peruano, y que se
encuentren en zonas geográficas en las cuales el Estado Peruano les exija una tributación
especial, por tanto, es fácil deducir que la mercadería tiene un menor costo que la mercade-
ría que transite definitivamente a una zona de tributación regular. La conducta del agente
perpetrará el tipo únicamente en el caso que traslade, o introduzca mercancías al territorio
nacional más no en sentido inverso. Las mercancías no pueden ser de cualquier clase, sino
específicamente aquel las que gozan por ley de un menor arancel tributario por la ubicación
geográfica, en relación a otras de la misma calidad que se internen en zonas de tributación
regular. No todas las mercancías por el sólo hecho de la ubicación geográfica gozan de este
especial tratamiento, por lo que nos encontramos ante una ley penal en blanco que requiere
para su precisión de otra norma administrativa específica. Estas mercaderías que gozan de
este beneficio tributario por zona geográfica deben ingresar a otras zonas sin haber paga
do el reintegro o diferencial que por ley se exige. Vgr. sujeto “A” que adquirió un automóvil
conforme a las normas de las zonas de tributación menor y decide venderlo en Lima; en
este caso deberá pagar el reintegro de ley para no incurrir en delito, situación diferente es la
del sujeto que no desea vender su auto ya que sólo lo piensa utilizar para un viaje de ¡da y
vuelta; en este caso deberá solicitar la autorización pertinente pues no sería razonable que
pague reintegros cada vez que vaya a zonas de tributación regular.
g) Conduce en cualquier medio de transporte, hace circular, embarca, desembarca o trans
borda mercancías dentro del territorio nacional, sin que hayan sido sometidas al control
aduanero”: Con esta modalidad remarca la protección jurídico penal del Estado con el con
trol aduanero hada el sujeto que transporta por cualquier medio de transporte una merca
dería dentro del territorio evitando el control aduanero. Evidentemente el sujeto no seguirá
la ruta que lo lleve al control aduanero, sino que lo burlará. Se dice que se ha remarcado la
protección jurídico-penal debido a que el transportista (terrestre, marítimo o aéreo) más
allá que exista o no la presente disposición deberá responder penalmente como cómpli
ce primarlo o secundario o como coautor dependiendo de la evaluación que se haga de la
situación en la que el sujeto se encuentre. Las mercaderías a transportarse deberán sobre
pasar las cuatro unidades tributarias ya que si no la actividad del transportista enmarcaría
dentro de la infracción de contrabando (Art. 35° de la Ley de los Delitos Aduaneros).
