3. Defraudación de rentas de aduana
Descripción normativa:
© Art. 4° Ley N° 28008 modificado por Dsc. Leg. 1542- Defraudación de rentas de aduana
"Comete delito de defraudación de rentas de aduana y es reprimido con pena privativa de la libertad
no menor de cinco ni mayor de ocho años y con trescientos sesenta y cinco a setecientosUrelntar
días-multa, el que, mediante trámite aduanero, valiéndose de artificio, engaño, astucia u otra forma
fraudulenta:
a) Deja de pagar en todo o en parte los tributos, recargos o cualquier otro importe a consecuencia de la utili
zación de documentación o información falsa, adulterada, indebida o incompleta, con relación al valor, cali
dad, cantidad, peso, especie, antigüedad, estado, origen, marca, código, serie, modelo, rotulado, etiquetado,
u otra información de las mercancías, así como de la indebida asignación de la subpartida nacional.
b) Obtiene o aprovecha ilícitamente una exoneración, inafectación, incentivo, devolución, beneficio tributario,
beneficio aduanero u otro beneficio de cualquier índole indebidamente obtenido como consecuencia de la:
i. Utilización de documentación o información falsa, adulterada, indebida o incompleta.
ii. Simulación total o parcial de una operación de comercio exterior.
iii. Sobrevaloración o subvaluación de las mercancías.
iv. Alteración de la cantidad, descripción, marca, código, serie, rotulado o etiquetado de las mercancías.
v. Indebida asignación de la subpartida nacional o indebida declaración del origen de las mercancías.
vi. Utilización o disposición indebida de las mercancías que ingresaron con inafectación, exoneración
o suspensión del pago de tributos, destinándola a una finalidad distinta a la señalada por la norm a
tiva nacional.
c) Consume, almacena, utiliza, sustrae o dispone de las mercancías en tránsito, transbordo, reembarque
o durante su traslado a una zona franca, zona de tratamiento aduanero especial o zona de tributación
especial, incumpliendo la legislación nacional.
El delito de defraudación de rentas de aduana se configura cuando el monto de los tributos, recargos o
cualquier otro importe no cancelado, o de la exoneración, inafectación, incentivo, devolución, beneficio
tributario, beneficio aduanero u otro beneficio de cualquier índole indebidamente obtenido, en provecho
propio o de terceros, sea superior a una (1) Unidad Impositiva Tributaria.
Se entiende por recargos a los conceptos comprendidos en la definición prevista en el artículo 2 de la Ley
General de Aduanas".
Tipicidad objetiva: El propio artículo 4 de la Ley 28008 modificado por el Dec. Leg. 1542, de
termina la descripción del tipo jurídico que sanciona la conducta de la defraudación de rentas
de aduanas. Así, dicho artículo precisa que: mediante trám ite aduanero, valiéndose de artifi
cio, engaño, astucia u otra forma fraudulenta: Deja de pagar en todo o en parte los tributos,
recargos o cualquier otro importe a consecuencia de la utilización de documentación o in
formación falsa, adulterada, indebida o incompleta, con relación al valor, calidad, cantidad,
peso, especie, antigüedad, estado, origen, marca, código, serie, modelo, rotulado, etiquetado,
u otra información de las mercancías, así como de la indebida asignación de la subpartida
nacional; u obtiene beneficios mediante actos simulados, sobrevaloración, alteración de mar
ca, cantidad, rotulado, u origen para obtener exoneraciones; o consume, almacena, utiliza,
