Tema 6: Temas de la Especialidad Penal
sustrae o dispone de las mercancías en tránsito, transbordo, reembarque o durante su traslado
a una zona franca, zona de tratamiento aduanero especial o zona de tributación especial, in
cumpliendo la legislación nacional será reprimido con pena privativa de libertad no m enorde
cinco ni mayor de ocho añosy con trescientos sesentay cinco a setecientos treinta días-multa.
Sobre el tema del Delito de Defraudación Tributaria TOCUNACA menciona q u e "... en materia
penal defraudar a la renta de aduanas significa eludir el pago de tributos que por derecho le corresponde
percibir al fisco, como acreedor del tributo aduanero (...), ahora bien, la defraudación de rentas de adua
nas, puede conceptualizarse como la acción dolosa destinada a valerse de un trám ite aduanero, con el
deliberado propósito de eludir el pago de los tributos de esa renta''’183.
Como se observa, en la configuración de este tipo de delito se presenta una acción dolosa
destinada a valerse de un trámite aduanero con el deliberado propósito de eludir el pago de
todo o parte del tributo.
Configuración: Para configurar entonces la conducta sancionable el transgresor al sistema
ingresa y busca someterse al control aduanero, gestiona el despacho aduanero, de manera
formal y ordinaria, utilizando los documentos y desarrollando el procedimiento establecido
en la Ley, pero de una manera deliberada procura ocultar, engañar, para dejar de pagar trib u
tos uotro gravamen.
Constituyen modalidades del delito de Defraudación de Rentas de Aduanay serán reprimidas
las acciones siguientes:
a) Deja de pagar en todo o en parte los tributos, recargos o cualquier otro importe a con
secuencia de la utilización de documentación o información falsa, adulterada, indebida
o incompleta, con relación al valor, calidad, cantidad, peso, especie, antigüedad, estado,
origen, marca, código, serie, modelo, rotulado, etiquetado, u otra información de las mer
cancías, así como de la indebida asignación de la subpartida nacional.
b) Obtiene o aprovecha ilícitamente una exoneración, inafectación, incentivo, devolución,
beneficio tributario, beneficio aduanero u otro beneficio de cualquier índole indebida
mente obtenido como consecuencia de la:
i. Utilización de documentación o información falsa, adulterada, indebida o incompleta.
ii. Simulación total o parcial de una operación de comercio exterior.
iii. Sobrevaloración o subvaluación de las mercancías.
iv. Alteración de la cantidad, descripción, marca, código, serie, rotulado o etiquetado
de las mercancías.
v. Indebida asignación de la subpartida nacional o indebida declaración del origen de
las mercancías.
vi. Utilización o disposición indebida de las mercancías que ingresaron con inafecta
ción, exoneración o suspensión del pago de tributos, destinándola a una finalidad
distinta a la señalada por la normativa nacional.
c) Consume, almacena, utiliza, sustrae o dispone de las mercancías en tránsito, transbordo,
reembarque o durante su traslado a una zona franca, zona de tratam iento aduanero es
pecial o zona de tributación especial, incumpliendo la legislación nacional.
