Tipicidad subjetiva: Se requiere dolo, el tipo penal en análisis no prescribe que el injusto se
pueda cometer por culpa.
4. Receptación aduanera
Descripción norm ativa:
"Alt. 6° Ley N° 28008. - Receptación aduanera
El que adquiere o recibe en donación, en prenda, almacena, oculta, vende o ayuda a comercializar
mercancías cuyo valor sea superior a cuatro (4) Unidades Impositivas Tributarias y que de acuerdo a
las circunstancias tenía conocimiento o se comprueba que debía presumir que provenía de los delitos
contemplados en esta Ley, será reprimido con pena privativa de libertad no menor de tres ni mayor de seis
años y con ciento ochenta a trescientos sesenta y cinco días-multa."
Tipicidad objetiva: Se sanciona al que adquiere o recibe en donación, en prenda, almacena,
oculta, vende o ayuda a comercializar mercancías cuyo valor sea mayor a 4 U IT y que de acuer
do a las circunstancias tenía conocimiento o se comprueba que debía presumir que provenía
de los delitos contemplados en esta Ley. Es importante destacar que esta figura tomada de los
Delitos contra el patrimonio tampoco admite la figura de la doble receptación o receptación
por receptación, es decir, se constriñe la responsabilidad a nivel de autoría solamente al pri
mer adquiriente de bienes de procedencia presuntamente ilícita.
Dichas mercancías serán apreciadas por el sujeto que de acuerdo a las circunstancias tenía
conocimiento de su procedencia ilegal o se comprueba que debía presumir que provenía de
los delitos contemplados en la Ley.
A veces entra en conflicto el interés del consumidor en este tema, quien no está obligado a pre
munirse de documentación de importación de bienes adquiridos para consumo final por ejemplo.
Tipicidad subjetiva:
Se requiere dolo.
5. Tráfico de mercancías prohibidas o restringidas:
Descripción norm ativa:
“Art.8° Ley N° 28008 Tráfico de mercancías prohibidas o restringidas.- El que utilizando cualquier medio
o artificio o infringiendo normas específicas introduzca o extraiga del país mercancías por cuantía
superior a cuatro (4) Unidades Impositivas Tributarias cuya importación o exportación está prohibida
o restringida, será reprimido con pena privativa de libertad no menor de ocho ni mayor de doce años y
con setecientos treinta a m il cuatrocientos sesenta días-multa.1''
Tipicidad objetiva: La conducta típica del delito puede realizarse de dos formas: i) mediante
la introducción al país de mercancías cuya importación esté prohibida o restringida (im porta
ción); o, i i) mediante la extracción del país de mercancías cuya exportación esté igualmente
prohibida o restringida (exportación). El eje de la prohibición penal se centra fundam ental
mente en el objeto sobre el que recae la operación de comercio exterior, es decir, en mercan
cías cuya importación o exportación se encuentra prohibida o restringida.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1031 of 1506 --

Tema 6: Temas de la Especialidad Penal
Asimismo, para que se configure el delito se requiere que el autor haya utilizado un medio irregu
lar para introducir o extraer la mercadería, o se haya valido de algún artificio para burlar el control
aduanero (por ejemplo, mediante la utilización de un documento falso), o haya infringido las nor
mas específicas que regulan los procedimientos de importación o exportación de estas mercancías.
Tipicidad subjetiva: El delito de tráfico de mercancías prohibidas o restringidas exige que la
conducta típica sea realizada con dolo, es decir, el autor debe actuar con conocimiento de que
está introduciendo o extrayendo del país mercancías cuya importación o exportación se en
cuentra prohibida o restringida.
15. LAVADO DE ACTIVOS. INTELIGENCIA FINANCIERA CONTRA EL LAVADO DE ACTIVOS.
OPERACIONES SOSPECHOSAS EN LA LEGISLACIÓN NACIONAL.
15.1. Descripción norm ativa:
“Decreto Legislativa de lucha eficaz contra el lavado de activos y otros delitos relacionados a la minería ilegal y
crimen organizado
Decreto Legislativo N° 1106
Art. 1 “Actos de conversióny transferencia “El que convierte o transfiere dinero, bienes; efectos oganancias-
cuyo origen ¡lícito conoce o debía presumir, con la finalidad de evitar la ¡dentiñcacíómdesuorigemsuíncautacióm
o decomiso, será reprimido con pena privativa de la libertad no menor de ocho ni mayor de quince años y con
ciento veinte a trescientos cincuenta días multa e inhabilitación de cinco a veinte años de conformidad con los
incisos I,2 y 8 d e la rtíc u lo 36 del Código Penal.
Artículo 2°.~ Actos de ocultamiento y tenencia “El que adquiere, utiliza, posee, guarda, administra, custodia, recibe,
oculta o mantiene en su poder dinero, bienes, efectos o ganancias, cuyo origen ilícito conoce o debíapresumir;:
será reprimido con pena privativa dé la libertad no menor de ocho ni mayor de quince años y con cientoiveínte-
a trescientos cincuenta días multa e inhabilitación de cinco a veinte años de conformidad con los incisos 1, 2
y 8 del artículo 36 del Código Penal".
Artículo 3 “ - Transporte; traslado, ingreso o salida porterritorio nacional de dinero o títulos valores de origen ilícito
"El que transporta o traslada consigo o por cualquier medio dentro del territorio nacional dinero en efectivo o
instrumentos financieros negociables emitidos “al portador" cuyo origen ilícito conoce o debía presumir, con
la finalidad de evitar la identificación de su origen, su incautación o decomiso; o hace ingresar o salir del país
consigo o por cualquier medio tales bienes, cuyo origen ilícito conoce o debía presumir, con igual finalidad,
será reprimido con pena privativa de libertad no menor de ocho ni mayor de quince años y con ciento veinte a
trescientos cincuenta días multa e inhabilitación de cinco a veinte años de conformidad con los incisos 1,2 y
8 del artículo 36 del Código Penal".
Se identifica como lavado de activos a todo acto o procedimiento realizado para dar una apa
riencia de legitimidad a los bienes y capitales que tienen un origen ilícito. El Lavado de Activos
es un delito no convencional y constituye en la actualidad un notorio exponente de la mo
derna criminalidad organizada. Desde la promulgación de la Ley N° 27765 del 17 de junio de
2002, este ilícito penal se encuentra tipificado y sancionado fuera del Código Penal de 1991.
Es por ello que en la actualidad la identificación del bien jurídico tutelado en este tipo de he
cho punibleya no puede deducirse de la ubicación sistemática que tenían en la Parte Especial
de nuestra legislación penal fundamental, los derogados artículos 2 9 6 °-Ay 2 9 6 °-B. Por consi
guiente, el precisar la calidady alcances del bien jurídico tutelado en el lavado de activos cons
tituye un primer problema dogmático que se aborda en el Acuerdo Plenario 3-2010/CJ-116.
Bien jurídico protegido: En el Acuerdo Plenario No. 3-201 o/Q-116 se establecen las diferentes
interpretaciones sobre lo que debería entenderse por bien jurídico protegido en el delito de
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1032 of 1506 --

UBILEX
lavado de activos. La doctrina agrupa las distintas posturas en varias categorías según quienes
consideran que:
1. El bien jurídico es la actividad y orden socio económicoy los bienes conexos a ellos;
2 . El lavado de activos es pluriofensivo (lesiona diversos bienes jurídicos);
3. El bien jurídico lesionado es el de la administración de justicia;
4. El bien jurídico protegido es el del delito fuente y;
5. El bien jurídico es la seguridad, la soberaníay la democracia de los Estados.
Concluye el mencionado acuerdo plenario que, "el lavado de dinero no está orientado hacia la
afectación de un bien jurídico exclusivoy determinado,ya que dicha infracción se presenta en
la realidad como un proceso delictivo que según sus manifestaciones concretas perjudica de
modo simultáneo o paralelo distintos bienes jurídicos. Se trata, pues, en definitiva, de un deli
to pluriofensivo que compromete a varios intereses jurídicamente relevantes como la eficacia
de la administración de justicia, la transparencia del sistema financiero, la legitimidad de la
actividad económica e, incluso, en un plano sumamente mediato, la incolumidad de la salud
pública. Este últim o en razón que en susentido funcional, el lavado de dinero aparecería como
un acto de favorecí miento o facilitación del tráfico ilícito y, porende, del consumo indebido de
drogas” [Cfr. Víctor Roberto Prado Saldarriaga. El Delito de Lavado de Dinero. Su tratamiento
Penal y Bancarioen el Perú. Idemsa. Lima. 1994, pp. 65 y 6 6 ],”184
Sujeto Activo: Se trata de un típico delito común que puede ser realizado porcualquier persona.
Sujeto Pasivo: Entendiéndolo como aquél sobre el cual recae el agravio de la acción típica, es
el Estado.
Tipicidadobjetiva: “La Convención de Viena dejó sentados tres tipos básicos en el delito de la
vado de activos: 1) los actos de ocultamiento del origen, la cualidad, o situación de disposición
sobre el patrimonio ilícito; 2) los actos de conversión, transferencia o transporte; 3) los actos de
posesión, adquisición o utilización de los bienes ilícitos.
Al respecto, el Acuerdo Plenario 3-2010 ha establecido una división de las modalidades típicas
del delito. Por un lado, tenemos a los que se encuentran en la categoría de delitos instantáneos y,
por el otro, a los de la categoría de delitos permanentes. Entre las modalidades típicas de la pri
mera categoría, la de delitos instantáneos, tenemos a la conversión y la transferencia. Mientras
que en el ámbito de los delitos permanentes encontramos al ocultamientoy la tenencia.
Según distintos autores, los actos de conversión suponen la mutación, el cambio de estado,
la transformación del patrimonio ilícito en uno nuevo, por lo cual puede quedar cubierta su
apariencia delictiva, cambiándola por una que parezca lícita. Asimismo, encontramos que la
conversión puede ser de dos tipos; ideal y material. En el primer tipo tenemos como ejemplo
el intercambio de patrimonio ilícito a cambio de una casa y, en el segundo, la conversión de
joyas de oro en un lingote. Tal como puede advertirse, en ambos casos hay una conversión de
un patrimonio que podría tener origen ilícito, solo que mientras uno supone una conversión
meramente ideal, el otro sí sufre una modificación sustancial en su materia.
184 A cu erd o P le n a rio N °. 3 -2 0 1 0 /Q -1 1 6 . Fj.12.
32 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1033 of 1506 --

Tema 6: Temas de la Especialidad Penal
La transferencia, en primera medida, implica la transmisión y el traslado del patrimonio, los
bienes, el dinero y, en general, el objeto material del delito. Un ejemplo de transmisión es el
de la persona que trasmite de una cuenta bancaria a otra, patrimonio ilegal. Y un ejemplo de
traslado es el de la obtención fraudulenta de devoluciones o subvenciones, en tanto que hay
un traslado de patrimonio que parte de las arcas estatales, hacia el patrimonio de la persona
que provoca el fraude.
Respecto a las otras dos modalidades típicas, ocultación y tenencia, podemos decir que estas
se encuentran recogidas en el artículo 2 del Decreto Legislativo No. 1106, bajo ocho verbos
típicos: “adquirir”, “utilizar”, “guardar”, “administrar”, “custodiar”, “recibir”, “ocultar” y "mantener
en su poder”, aludiendo, desde luego, al patrimonio de origen ilícito. Estos mismos pueden
ordenarse en cuatro grupos, según la naturaleza de los actos: 1) adquirir; 2) recibiry mantener
en su poder; 3) guardar, custodiary ocultar; 4) utilizary administrar”185.
Tipicidadsubjetiva: Se trata de un delito eminentemente doloso. El dolo que se exige prepon-
derantemente es el dolo directo de primer grado; en cuanto al dolo eventual, es admisible su
realización. Esto se desprende a partir de que los comportamientos típicos deberán ser efec
tuados por el agente “conocimiento” (dolo directo) o “debiendo presumir” (dolo eventual) el
origen delictuoso de los bienes.
Por tanto, conforme a la legislación peruana y la de procedencia convencional, mediante el
lavado de activos se reprime a quien, con la finalidad de dificultar la identificación de la fuen
te criminal, convierte, transfiere, oculta, mantiene en su poder, transporta o hace ingresar o
salir al país activos cuyo origen delictivo conoce o debía presumir. Sobre la primera modalidad
subjetiva concierne al dolo directo, mientras que la segunda modalidad subjetiva concierne
al dolo eventual186.
15.2. Modalidades delictivas:
Actos de conversión y transferencia: Los actos de conversión y transferencia se sitúan en las
primeras etapas del proceso de reciclaje: la “colocación” y el "ensombrecimiento”. Esta m odali
dad de lavado de activos, además de constituirse en un delito co m ú n -q u e puede ser incluso
realizada por el interviniente en el delito previo-, representa una estructura típica de consu
mación instantánea, conforme es reconocido en el Acuerdo Plenario N° 03-2010.
Actos de Ocultamiento y tenencia: Conforme al A rt 2 del Dec. Leg. 1106, prevé hasta nueve ver
bos típicos: adquirir utilizar, poseer, guardar, administrar, custodiar, recibir, ocultary mantener en
el poder. De los comportamientos solo da lugar a un acto de ocultamiento el verbo típico “ocultar”,
mientras que los otros pueden aproximarse o considerarse como actividades de tenencia.
Se reprimen operaciones de integración de los activos lavados en la economía legal (nuevas
inversiones y depósitos bancarios, posesión de bienes o usufructo de inmuebles adquiridos
con activos lavados, etc.)
