De acuerdo al Profesor Prado Saldarriaga, estas modalidades de conducta representan la fase
final del proceso de reciclaje, es decir, la etapa de “integración"187.
Actos de transporte, traslado, ingreso o salida: De acuerdo con esta modalidad, se incrimina
a quien “transporta o traslada dentro del territorio nacional dinero o títulos valores [...] o hace
