Primer grado o nivel: La pena será privativa de la Ii bertad no m e n o rd e io ni mayor de 20 años
y 365 a 730 días multa, cuando:
a) el agente utilice o se sirva de su condición de funcionario público o de agente del sector
inmobiliario, financiero, bancario o bursátil.
b) el agente cometa el delito en calidad de integrante de una organización criminal.
c) el valor del dinero, bienes, efectos o ganancias involucrados sea superior al equivalente a
500 U IT.
Segundo grado: La pena será privativa de la libertad no m enorde 25 años cuando.-
Los actos de conversión y transferencia o de ocultamientoy tenencia se relacionen con dinero, bie
nes, efectos o ganancias provenientes del: i) tráfico ilícito de drogas; ii) terrorismo, iii) secuestro, iv)
extorsión, v) trata de personas o delitos contra el patrimonio cultural previsto en los artículos 228y
230 del C.P; vi) minería ilegal, vii) tráfico ¡lícito de drogas, vi i i) terrorismo, ix) secuestro, x) extorsión.
15.4. El Delito Precedente en el Decreto Legislativo N° 1106
El delito precedente de lavado de activos es la conducta criminal subyacente que genera el
producto susceptible de ser lavado.
Según el D. Leg. N ° iio 6 : “El conocimiento del origen ilícito de los activos debe sercomprendi-
do por el dolo del agente del delito (Art. 10o, segundo párrafo).
“La vinculación objetivay acreditada de los activos a un delito precedente específico sólo es un
requisito indispensable para la configuración del agravante de segundo grado (Art.4°, segun
do párrafo)”.
Al respecto, en el Fj. 6 de la ejecutoria del R.N. N°4003-20ii-Lim a, analizando la Ley 27765,
“el Acuerdo Plenario 3-201 o/Cj-n 6 señala:’!., el delito de lavado de activos requiere que previamente
se haya cometido otro delito, cuya realización haya generado una ganancia ilegal, que es precisamente
lo que el agente pretende integrara la economía y, en su caso, al sistema financiero” (...)”El delito fuente,
empero, es un elementos objetivo del tipo legal- como tal debe ser abarcado por el dolo-ysu prueba condi
ción asimismo de tipicidad”. Si bien es necesario que para la configuración del delito de lavado de activos,
quede establecido el delito que origina el mismo, pues es naturaleza de este delito- que incluso origino su
187 P R A D O S A L D A R R IA G A , Criminalidad Organizada, oh. cit., p. 268.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1035 of 1506 --

Tema 6: Temas de la Especialidad Penal
crim inalización- com batir los actos que dificultan la judicialización de los delitos precedentes así como
los que perjudican al sistema económico del Estado-pues se trata de un delito pruriofensivo-sin embargo,
para impulsare! proceso contra quienes se presume la comisión del delito de lavado de activos no hace fal
ta, aún, que haya quedado establecido, con seguridad rayana a la certeza, el delito precedente, pues para
la investigación es necesario únicamente que existan indicios reveladores que vinculen al procesado con el
delito precedente. Dicha vinculación de los activos, así como la existencia del delito previo se considerarán
determinadas al constatarse la existencia de- a) Una conexión o relación del autor o participe con activi
dades delictivas o con personas o grupos relacionados a dichos ámbitos a p a rtir de determinados hechos
concluyentes; b) Existencia de un incremento notorio del patrim onio personal de la persona durante el
periodo de tiempo en el que se produjo dicha vinculación: c) Ausencia de negocios lícitos que justifiquen el
aumento del patrim onio; d) Existencia de negocios aparentemente lícitos que no producen utilidades; e)
el hecho que ante una investigación adm inistrativa o policial no se pueda justificar un depósito banca rio,
de otra índole, por una suma de dinero elevada. Similares criterios han sido desarrollados por la Corte Su
prema en el Acuerdo Plenario3-2 0 io /C ]- n 6 , que señala “a p a rtir de aportes Criminológicos, la experien
cia criminalística y la evolución de la doctrina jurisprudencial, es del caso catalogar algunas aplicaciones
déla prueba indicaría”. Por tanto, se concluye que para la investigación es necesario únicamente
que existan indicios reveladores que vinculen al procesado con el delito precedente.
Sin embargo, en el año 2012 la Corte Suprema en su ejecutoria del R.N. N °3091-2013-Líma,
analizando la Ley 27765, señalo expresamente que: “El delito precedente o también llamado delito
fuente, en el delito de lavado de Activos es un elemento im portante a corroborar en la configuración de
este delito; si bien se ha precisado que no se necesita que dicho delito se encuentre siendo investigado, sí
deberá ser corroborado mínimamente.
Recientemente, la Sala Penal Transitoria de la Corte Suprema, analizando el D.Legnoó m odi
ficado D.Legi249, en suCAS N° 92-2017-Arequipa (Fj.17) estableció como criterio jurispruden
cial de carácter vinculante: “No obstante la deficiencia de técnica legislativa expuesta en las conside
randos precedentes; una interpretación sistemática y teleológica de la ley vigente, permite concluir que el
delito fuente sigue siendo un elemento normativo del tipo objetivo de los artículos 1° 2°y 3 o, del Decreto
Legislativo N ° n o 6 , modificado por el Decreto Legislativo N ° i2 4 9 ;y que cumple, además, una triple
función dogmática; esto es: i) otorga contenido al objeto m aterial del delito; ii) da sentido a la imputación
subjetiva;y, ¡ii) justifica la agravante de la pena.”
15.5Jerrtativa
Con las modificaciones que introdujo el Decreto Legislativo 986 en los artículos i° y 2° de la
Ley 27765 el delito de lavado de activos ha quedado configurado como un delito de resulta
do. Por tanto, en los actos de conversión, transferencia ocultamiento y tenencia de activos de
procedencia ilícita la consumación del delito requiere, necesariamente, verificar si el agente
logró con tales conductas, cuando menos momentáneamente, dificultar la identificación de
su ilícito origen, o su incautación o decomiso. Esto es asegurar, siquiera mínimamente, tales
activos y su potencial o real aplicación o integración en el circuito económico. En consecuen
cia, pues, si dichos resultados no se realizan, esto es, se frustra de cualquier modo la operación
de cubierta que el agente busca construir o consolidar sobre los activos que pretende lavarse
deberá calificar a tal inicio de ejecución como una tentativa la cual será punible conforme a
lo dispuesto en el artículo 16o del Código Penal. Esto ocurrirá, por ejemplo, cuando el agente
no alcance a culminar el procedimiento de conversión o de transferencia de los activos ilícitos
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1036 of 1506 --

UBILEX
p W : que hubiera emprendido, sea por la intervención de terceros o por otras razones o condiciones
ajenas a su voluntad188.
15.6. Consumación
El momento consumativo coincidirá con la mera realización de cualquiera de las formas señala
das por la ley. Sin embargo, en lo concerniente a los actos que tipifica el artículo 2o como supues
tos de ocultamiento y tenencia, su estructura ejecutiva es la propia de los delitos permanentes.
En ellas, pues, las posibilidades delictivas incluidas imponen que el momento consumativoy la
producción del estado antijurídico generado por la conducta realizada se mantenga en el tiem
po por voluntad expresa o implícita del agente. La permanencia del estado antijurídico, pues, y
por consiguiente de la consumación, durará lo que el agente decida o lo que este logre mantener
sin que las agencias de control descubran o detecten la procedencia ilícita o lo ficticio de la apa
riencia de legalidad de los activos. No obstante, cabe distinguir que los actos de transporte, in
troducción o extracción de activos en el territorio nacional que también se incluyen en el artículo
2o, desde la vigencia del Decreto Legislativo 982, debido a su operatividad ejecutiva deben ser
apreciados como delitos de consumación instantánea. La necesidad de distinguir la condición
instantánea o permanente de la consumación en los actos que constituyen delitos de lavado de
activos, adquiere importancia práctica para resolver problemas relacionados con la prescripción
de la acción penal o con las posibilidades de una participación post consumativa. Por tanto, es de
identificar tal condición para aplicar debidamente las reglas particulares que para estos casos ha
definido la legislación y la doctrina nacionales189.
15.7. Autolavado de activos
La figura del autolavado de activos, recién fue incorporada como modalidad delictiva en la mo
dificación a la Ley de lavado de activos dispuesta por el D. Leg. 986, publicado el 22/07/2007. Al
respecto la Sala Penal Permanente de la Corte Suprema a través de la ejecutoria R.N. N° 3657-
2012-Lima (26/03/2014) ha determinado que sólo son reprimióles los autolavados cometidos
a partir del 22/JUI/2007 (fecha en que el D. Leg N° 986 modificó la Ley N° 27765).
Actualmente esta figura delictiva se encuentra regulada en el últim o párrafo del art. 10 del
D. Leg. 1106, el mismo que señala.- “(...) También podrá ser considerado autor del delito y por tanto
sujeto de investigación y juzgam iento por lavado de activos, quien ejecutó o participó en las actividades
criminales generadoras del dinero, bienes, efectos o ganancias”.
15.8. Unidad de Inteligencia Financiera:
La UIF-Perú lidera el sistema de prevención del lavado de activos y del financiamiento del
terrorismo. Los sujetos obligados a informar están legalmente determinados. A partir de los
informes de aquél los y de las solicitudes e instancias que curse la UIF-Perú, ésta iniciará el aná
lisis e investigación de todas aquellas operaciones que puedan estar vinculadas a actividades
de lavado de activos y/o de financiamiento del terrorismo. En el plano de la investigación del
delito de lavados de activos, la Ley reconoce las atribuciones de otras instancias de investiga-
188 A cu erd o P le n a r io 3 - 2 0 io /C J - ii6 . FJ.15.
189 A cu erd o P le n a rio 3 - 2 0 1 0 /C H 1 6 . FJ.16
R	E36 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1037 of 1506 --

Tema 6: Temas de la Especialidad Penal
ción, con las que puede incluso participar en actividades conjuntas de investigación. El Infor
me de la UIF-Perú, portanto, no constituye requisito de procedíbiI¡dad alguno.
Según el artículo 13o.2 del Reglamento de la Ley que crea la UIF-Perú, aprobado por Decreto
Supremo número 018-2006-JUS, del 25 de julio de 2006, el Informe que envía al Ministerio
Público se denomina "Informe de Inteligencia”. Contiene la labor de análisis producto de los
reportes de operaciones sospechosas que recibey de las investigaciones conjuntas que pueda
solicitar, y su evaluación de las operaciones que presuma estén vinculadas con el delito de
lavado de activos y/o financiamiento del terrorismo. El sustento de la información producto
del desarrollo del trabajo de inteligencia está inserto en los Anexos al Informe de Inteligencia.
La naturaleza jurídica del Informe de Inteligencia no puede asimilarse a una Auditoria Espe
cializada de carácter financiero o pericia institucional, en función a las limitaciones y rasgos
propios con el que ha sido regulado. En efecto, según el párrafo final del artículo 13o.2 del Re
glamento, el destinatario del Informe de Inteligencia está obligado a guardar la debida confi
dencialidad de la entidad informante y la reserva del contenido de la información. La informa
ción que sustenta el Informe de Inteligencia tiene carácter reservado. No puede ser empleada
en el proceso jurisdiccional ni como medio probatorio, salvo que la UIF-Perú autorice expre
samente sus anexos, que es el sustento de la información proporcionada. El emplazamiento
judicial de un funcionario de la UIF-Perú sólo procede respecto de los documentos que obren
en autosy que han sido autorizados poresa institución par constar en ellos.
Más allá de lo lim itado del uso procesal del Informe de Inteligencia, y de la falta de claridad
para su utilización en relación al cuerpo del citado Informe y al sustento de la información
-los anexos-, llama la atención que el propio Estado lim ite el esclarecimiento de un delito de
tanta gravedady niegue el acceso fluido a la autoridad penal de información cuya pertinencia
y utilidad corresponde valorar al órgano jurisdiccional, pero que en este caso reconoce una
potestad decisoria a la UIF-Perú.
Así las cosas es evidente que si el Informe de Inteligencia es de libre acceso a las partes y al
órgano jurisdiccional -en la medida en que así lo decida el UIF-Perú-; y, en tanto está acom
pañado de documentación, análisis financieros y contables, y diversa información bancariay
comercial, así como de las conclusiones y valoraciones consiguientes, primero, servirá como
indicio procedimental para incoar el correspondiente proceso penal o inculpación formal, y,
segundo, luego de ser sometido a contradicción por su nítido carácter pericial, podrá ser valo
rado como pericia institucional con arreglo al principio de libre valoración190.
Respecto de los sujetos obligados a proporcionar información a la UIF, al largo listado ya
existente en la Ley N° 29038(Art. 3), a través del D.S. N° 006-2023-]US, se incorpora a los Pro
veedores de Servicios de Activos Virtuales (PSAV) que comprenden cualquier persona física
o jurídica, domiciliada o constituida en el país, que no esté cubierta en ninguna otra de las
Recomendaciones del Grupo de Acción Financiera Internacional (GAFI) y que, como negocio,
realiza una o más de las siguientes actividades u operaciones para o en nombre de otra per
sona física o jurídica: i) Intercambio entre activos virtuales y monedas fia t o de curso legal; ii)
Intercambio entre una o más formas de activos virtuales; iii) Transferencia de activos virtuales;
