-- 1038 of 1506 --

iv) Custodia y/o administración de activos virtuales o instrumentos que permitan el control
sobre activos virtuales; y v) Participación y provisión de servicios financieros relacionados con
la oferta de un emisory/o venta de un activo virtual.
15.9. Omisión de comunicación de operaciones o transacciones sospechosas
Delito tipificado en el art. 5 del D. Leg. N °iio 6 que señala: "El que incumpliendo sus obligaciones
funcionales o profesionales, omite comunicara la autoridad competente, las transacciones u operaciones
sospechosas que hubiere detectado, según las leyes y normas reglamentarias, será reprimido con pena
privativa de la libertad no menor de cuatro ni mayor de ocho años, con ciento veinte a doscientos cincuen
ta días m ulta e inhabilitación no menor de cuatro ni mayor de seis años, de conformidad con los incisos 1),
2)y 4) del artículo 36 del Código Penal.
La omisión por culpa de la comunicación de transacciones u operaciones sospechosas será reprimida con
pena de m ulta de ochenta a ciento cincuenta días m ulta e inhabilitación de uno a tres años, de conformi
dad con los incisos 1), 2)y 4) del artículo 36 del Código Penal”.
Según lo señalado en la sentencia que resuelve la acción de inconstitucionalidad planteada
contra el art. 5 del D. Leg. 1106 ante el Tribunal Constitucional (STC 06-2014--PI de fecha 05 de
marzo de 2020, Caso comunicación de operaciones sospechosas):
En el presente caso, el deber de los sujetos obligados consiste en comunicar a la autori-
dad competente las operaciones o transacciones sospechosas que hubieren detectado,
entendiéndose por tales — como ya hemos visto— aquellas operaciones de naturaleza
civil, comercial o financiera, de magnitud o rotación inusual, o de complejidad inusitada
o injustificada, que haga presumir que proceden de alguna actividad ilícita o no tengan
un fundamento lícito aparente.
Lo que sanciona el tipo penal en cuestión es la conducta del sujeto activo que incumple
su deber de comunicar a la autoridad competente de las operaciones sospechosas que
hubiere detectado, por resultar potencialmente peligroso para el bien jurídico estabili
dad, transparencia y legitimidad del sistema económico y financiero. Se trata, pues, de
una conducta relevante e intolerable para el bien jurídico en mención, y no de una mera
infracción administrativa, por lo que merece que sea castigada penalmente.
Así, este Tribunal concluye en que la medida adoptada por el legislador de sancionar penal
mente a quien omite comunicar a la autoridad las operaciones sospechosas que hubiere
detectado y que podrían estar vinculados con los delitos de grave''afectación social resulta
necesaria para la protección del bien jurídico estabilidad, transparencia y legitimidad del
sistema económico y financiero frente a la amenaza de lesión o peligro de lesión de este.
16. ALCANCES REFERIDOS A LA REGULACIÓN DE PÉRDIDA DE DOMINIO
La extinción de dominio tiene sus antecedentes internacionales en la Convención de Viena
(1988), la Convención de Estrasburgo (1990), la Convención de Palermo (2000), la Convención
de Mérida (2003), la Ley N°7 9 3 (Colombia, 2002) y la Ley Modelo sobre Extinción de Dominio
-UNODOC (2on).
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1039 of 1506 --

Tema 6: Temas de la Especialidad Penal
En el Perú se dieron diversas medidas legislativas para la regulación y tratamiento del proceso
de perdida de dominio tales como el Decreto Legislativo N° 992 que regula el proceso de Pérdida
de Dominio, la Ley N° 29212 que modifica el Decreto Legislativo N°992, Decreto Legislativo que
regulael procesode Pérdida de Dominio; Decreto Legislativo N °ii0 4 q u e modifica la legislación
sobre Pérdida de Dominio y por ultimo del Decreto Legislativo N°1373 sobre Extinción de Domi
nio así como su Reglamento aprobado mediante el Decreto Supremo N° 007-2019.
Mediante Resolución Administrativa N ° i22-2019 -CE-PJ, de fecha 20 de marzo de 2019, se consti
tuye el Sub Sistema Nacional Especializado en Extinción de Dom inioy se dispone la creación de
21 Juzgados Especializados y 3 Salas de Apelaciones Especializadas a nivel nacional.
El artículo III numeral 3.10 del Título Preliminar del Decreto Legislativo N ° i373 define que la
Extinción de dom inio es “consecuencia jurídico-patrimonial que traslada a la esfera del Estado
la titularidad de los bienes que constituyen objeto, instrumento o efectos o ganancias de acti
vidades ilícitas, mediante sentencia emitida respetando el debido proceso, sin indemnización
ni contraprestación alguna a favor del requerido o terceros”. En tal sentido la extinción de do
minio se constituye es una herramienta de política criminal para la prevención y lucha contra
la delincuencia organizada.
Dicho esto, debemos tener presente que el artículo 70 de la Constitución Política del Estado
determina la inviolabilidad del derecho de propiedad “El derecho de propiedad es inviolable. El
Estado lo garantiza. Se ejerce en armonía con el bien común y dentro de los límites de ley. A nadie pue
de privarse de su propiedad sino, exclusivamente, por causa de seguridad nacional o necesidad pública,
declarada por ley, y previo pago en efectivo de indemnización justipreciada que incluya compensación
por el eventual perjuicio. Hay acción ante el Poder Judicial para contestar el valor de la propiedad que el
Estado haya señalado en el procedimiento expropiatorio.”
Ante ello mediante Sentencia N° 3881-2012 -AA/TC el Tribunal Constitucional ha establecido
además que el derecho de propiedad puede verse restringido en virtud a los siguientes su
puestos: a) estar establecidas por ley; b) ser necesarias; c) ser proporcionales, y d) hacerse con
el fin de lograr un objetivo legítimo en una sociedad democrática. Así, el derecho de propie
dad solamente puede ser materia de restricciones por las causas y finalidades señaladas en la
propia Constitución.
En el proceso de Extinción de Dominio lo que se investiga son los bienes relacionados con acti
vidades ilícitas que tiene una acepción ampliay puede abarcar las acciones delictivas pero no se
agotan en ellas, así el artículo I el título preliminar señala que “El presente decreto legislativo se
aplica sobre todo bien patrimonial que constituya objeto, instrumento, efectos o ganancias que
tienen relación o que se derivan de las siguientes actividades ilícita: contra la administración pú
blica, contra el medioambiente, tráfico ilícito de drogas, terrorismo, secuestro, extorsión, trata de
personas, lavado de activos, contrabando, defraudación aduanera, defraudación tributaria, mi
nería ilegal y otras con capacidad de generar dinero, bienes, efectos o ganancias de origen ilícito
o actividades vinculadas a la criminalidad organizada”191. En consecuencia la calificación jurídica
que se le dé a la acción delictiva en un proceso penal carece de importancia para el procesode ex
tinción de dominio, puesto que bastará la existencia tan solo de una actividad ilícita relacionada
con un bien patrimonial para que se declare su extinción de dominio.
