Y NOMBRAMIENTO DE JUECES Y FISCALES 103 1

-- 1040 of 1506 --

UBILEX
Del mismo modo, la Sala Penal Permanente mediante la sentencia recaída en la Cas. N °i40 8-
20 17-Puno en su fundamento Décimo Sextoy Vigésimo, determino que“La pérdida o extinción
de dominio, como institución, fue incorporada en nuestro ordenamiento legal por el Decreto
Legislativo N.° 9 9 2 . Su finalidad es obtener mecanismos para la lucha contra la delincuencia
organizaday la generación de desincentivos en la obtención de ganancias ilícitas. La legitim i
dad constitucional de la institución se sustenta en que la propiedad o el dom inio obtenido al
margen de la ley no cae en el ámbito de la inviolabilidad de la propiedad, constitucionalmente
protegible. No se trata de una institución puramente penal, pues su activación no descansa
necesariamente en la afectación de las ganancias ¡lícitas (penales) propiamente dichas. Es
más, en la extinción de dom inio se ataca el patrimonio obtenido ilícitam entey no a la persona
que lo obtuvo. Por ello, tiene igualmente una naturaleza civil, "e Igualmente, nada impide que
se pueda incoar el proceso de pérdida de dom inio en caso de sentencias absolutorias. En este
caso, se debe verificar si la incoación del proceso cumple con alguno de los supuestos de pro
cedencia previsto en el artículo 4 de la legislación de pérdida de dom inio”, respectivamente.
Es necesario precisar que los supuestos de procedencia para la extinción de dom inio con la
vigencia del Decreto Legislativo N°iB73 han variado, sin perjuicio de ello su finalidad y natu
raleza no han cambiado según se puede apreciar de la sentencia descrita precedentemente.
En el ordenamiento jurídico peruano se puede asemejar la extinción de dom inio con otras
figuras jurídicas como:
