16.1. Naturaleza jurídica del proceso de extinción de dominio
El artículo 3 del Decreto Legislativo N ° i373 establece las características del proceso de Extin
ción de dom inio de la siguiente manera:
Es Autónoma, pues es independiente de la acción y del proceso penal, civil, administrativo o
de cualquier otra naturaleza jurisdiccional o arbitral.
Es Pública, pues porsucaráctertuitivoes ejercida porel Estado a través del Ministerio Público.
Es Real, pues se dirige contra bienes muebles o inmuebles, activos o derechos reales.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1041 of 1506 --

Tema 6: Temas de la Especialidad Penal
Es P a t r im o n ia l, pues los bienes muebles o inmuebles, activos o derechos integran el patrimo
nio del agente del delito.
16.2. Bienes susceptibles de extinción de dom inio
Conforme a lo dispuesto en el artículo III numeral 3 3 del Título Preliminar del Decreto Legis
lativo N°1373- Todos aquellos que, según las definiciones de los artículos 8 8 5 y 8 8 6 del Código
Civil, son muebles e inmuebles. Igualmente lo son las partes integrantes, accesorios, frutos y
productos de esos bienes.
16.3. Presupuestos de procedencia del proceso de extinción de dom inio
El artículo 7 del Decreto Legislativo N ° i373 establece los presupuestos de procedencia del pro
ceso de extinción de dominio:
a) Cuando se trate de bienes resultado de la comisión de actividades ilícitas, salvo que por
ley deban ser destruidos o no sean susceptibles de valoración patrimonial.
b) Cuando se trate de bienes que constituyan un incremento patrimonial no justificado, por
no existir elementos que razonablemente permitan considerar que provienen de activi
dades lícitas.
c) Cuando se trate de bienes de procedencia lícita que han sido utilizados o destinados para
ocultar, encubrir, incorporar bienes de ilícita procedencia o que se confundan, mezclen o
resulten indiferenciables con bienes de origen ilícito.
d) Cuando se trate de bienes declarados en abandono o no reclamados y se tenga informa
ción suficiente respecto a que los mismos guardan relación directa o indirecta con una
actividad ilícita.
e) Cuando los bienes o recursos de que se trate provengan de la enajenación o permuta de
otros que tengan su origen directo o indirecto en actividades ilícitas o constituyan objeto,
instrumento, efectos o ganancias de las mismas.
f) Cuando se trate de bienes y recursos que han sido afectados dentro de un proceso penal y
que el origen de tales bienes, su utilización o destino ilícito no hayan sido objeto de inves
tigación; o habiéndolo sido no se hubiere tomado sobre ellos una decisión definitiva por
cualquier causa.
g) Cuando se trate de bienes objeto de sucesión por causa de muerte y los mismos se en
cuentren dentro de cualquiera de los presupuestos anteriores.
16.4. Principios y criterios aplicables al proceso de extinción de dom inio
El artículo III numeral 3 3 del Título Preliminar del Decreto Legislativo N ° i373 establece como
principiosy criterios aplicables, los siguientes:
i. Nulidad: todos los actos que recaigan sobre bienes de origen o destino contrario al orde
namiento jurídico, son nulos de pleno derecho, sin perjuicio de los derechos de terceros
de buena fe.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1042 of 1506 --

UBILEX
2. Especialidad: los vacíos y ambigüedades que pudiera presentar este decreto legislativo
en su interpretación o aplicación, se resuelven según la propia naturalezay principios del
proceso que regula. Si a pesar de esto, el vacío o ambigüedad persiste, se acude a la octava
disposición complementaria final.
3. Autonomía: el proceso de extinción de dominio es independientey autónomo del proce
so penal, civil u otro de naturaleza jurisdiccional o arbitral, por lo que no puede invocarse
la previa emisión de sentencia o laudo en éstos para suspender o impedir la emisión de
sentencia en aquél.
4. Dominio de los bienes: la protección del derecho de propiedad u otros derechos que re
caigan sobre los bienes patrimoniales, se extiende únicamente a aquéllos que recaigan
sobre bienes obtenidos con justo título o estén destinados a fines compatibles con el or
denamiento jurídico.
5. Aplicación en el tiempo: la extinción de dom inio se declara con independencia de que
los presupuestos para su procedencia hayan ocurrido con anterioridad a la vigencia del
presente decreto legislativo.
6 . Tutela Jurisdiccional y Debido Proceso: en el trám ite y ejercicio del proceso de extinción
de dominio se observan los derechos a la tutela jurisdiccional y al debido proceso, reco
nocidos en el inciso 3 del artículo 139 de la Constitución Política del Perú.
7. Publicidad: el proceso de extinción de dom inio es público a partir de la notificación del
auto que admite la demanda o desde que se materializan las medidas cautelares. Las
actuaciones comprendidas desde el inicio de la indagación son reservadas.
8 . Cosa juzgada: En materia de extinción de dom inio aplica la cosa juzgada, siempre que
exista identidad de sujeto, objeto y fundamento.
9. Carga de la prueba: para la admisión a trám ite de la demanda de extinción de dominio,
corresponde al Fiscal ofrecer las pruebas o indicios concurrentes y razonables del origen o
destino ilícito del bien. Adm itida a trám ite la demanda, corresponde al requerido demos
trar el origen o destino lícito del mismo.
Respecto de la carga probatoria en los procesos de extinción de dominio, resulta importante
ofrecer un pronunciamiento judicial reciente donde se establece que la Fiscalía debe probar
que el propietario prestó su consentimiento para la utilización ilícita de su vehículo como ins
trum ento del del ito: “En el PED no basta que la Fiscalía se lim ite a probar, i. el vínculo o nexo de relación
entre cualquiera de los supuestos para declararla extinción de dominio, ¡I. la actividad ilícita que corres
ponde, y ¡11. los bienes objeto de extinción de dominio (artículo 14.1.d LED). A ello, deberá adicionarse
cuando se trate de los Instrumentos con que se hubiere ejecutado la actividad ilícita el delito, si pertenecen
a terceros iv. que estos hayan prestado su consentimiento para su utilización (artículo 102 de! Código
Penal), sea de forma dolosa o con negligencia grave, es decir, en forma contraria al principio de buena fe.
Satisfecha la carga probatoria por la parte demandante que sostiene la pretensión de carácter real, co
rresponde a la parte demandada acreditarlos hechos impeditivos, extintivos o excluyentes que sustentan
su resistencia, consistente en: i. el destino lícito del bien objeto de extinción (artículo II.2.9 LED)y, ii. la
existencia de buena fe -cualificada o exenta de culpa- en el uso del bien, de cara a obtener una sentencia
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1043 of 1506 --

Tema 6: Temas de la Especialidad Penal
que declare infundada la demanda.” Exp. 92-2024-o-i6oi-SP-ED-oi/Piura. Sala de Apelaciones
Transitoria Especializada en Extinción de Dom inio de La Libertad. FJ. 32.
16.5. Competencia del proceso de extinción de dom inio
El artículo 8 del Decreto Legislativo N ° i373 refiere en primer lugar que la competencia es del
Juez Especializado de Extinción de Dominio del distrito judicial donde se encuentre ubicado
el bien materia de indagación. De encontrarse los bienes en diversos distritos judiciales, es
competente el Juez Especializado de Extinción de Dominio del distrito judicial en donde se
inicie la primera indagación a cargo del Ministerio Público. En caso se tuviera conocimiento
de la existencia de otros bienes ubicados en distintos lugares, una vez iniciado el proceso de
extinción de dominio, mantiene la vigencia el Juez que conoce la primera demanda.
Cuando el proceso de extinción de dominio se haya iniciado en más de un país, se estará a lo
resuelto en el respectivo tratado, convenio internacional o cooperación judicial internacional,
de acuerdo a lo prescrito por el artículo 51 del Decreto Legislativo N ° i373.
16.6. Etapas del proceso de extinción de dom inio
La norma establece que existen dos etapas diferenciadas en el proceso de extinción de dominio.
Etap a d e In d a g ació n P a trim o n ia l, tiene el carácter de reservado y está a cargo del Fis
cal Especializado bajo las facultades atribuidas en el artículo 10 del Decreto Legislativo
N ° i373, quien puede solicitar medidas cautelares (orden de inmovilización, incautación,
inhibición o inscripción sobre cualquiera de los bienes) que resulten necesarias para el
aseguramiento de los bienes materia de investigación las cuales deben ser resueltas
en audiencia reservada dentro de las 24 horas de recibida la solicitud, además pueden
solicitar información y requerir la intervención de la Policía Nacional del Perú y la cola
boración de los funcionarlos y servidores públicos, con estricto respeto de los derechos
fundamentales. En caso el fiscal de manera excepcional por razones de urgencia ejecute
una medida cautelaren esta etapa deberá ser confirmada o rechazada por el Juez dentro
de las veinticuatro (24) horas de ejecutada. Esta etapa concluye en un plazo de doce (12)
meses prorrogables por un plazo igual, o de ser declarado complejo en tre in ta y seis (36)
meses prorrogables por un plazo igual, o con la presentación de la demanda de declara
ción de extinción de dominio ante el Juez competente, o con el archivo de la indagación
patrimonial cuando no sea posible fundamentar ninguno de los presupuestos invocados
en el Decreto Legislativo N °1373- Esta últim a puede ser objeto de queja en un plazo no
mayor de cinco (05) días hábiles de notificada por el Procurador Público, debiendo el Fis
cal Superior resolver en un plazo no mayor a diez (10) hábiles de recibidos los actuados.
De declarar fundada la queja puede ordenar al Fiscal a cargo de la indagación patrimonial
que presente la demanda de extinción de dominio o continuar con la Indagación. De lo
contrario puede aprobar el archivo. De no interponerse queja contra la disposición de ar
chivo, esta se eleva en consulta al Fiscal Superior a fin que en un plazo de veinte (20) días
hábiles se pronuncie respecto de la confirmación de archivo u ordenar la presentación de
la demanda. La disposición de archivo del superior constituye cosa decidida y solo pue
de iniciarse una nueva indagación patrimonial sobre los mismos bienes si se encuentran
