nuevas pruebas. Sin perjuicio de ello, las decisiones de archivo están sujetas a las audito
rias)/ controles del Ministerio Público.
E tap a Ju d icia l, la cual se inicia con la presentación de la demanda al Juez por parte del
Fiscal de Indagación Patrimonial, debiendo contener los hechos, la identificación y valua
ción económicas de los bienes objetos de la demanda, el nexo de relación entre los bienes
y la actividad ilícita o el incremento injustificado, datos de identificación de las personas
que pudieran tener interés en el asunto, ofrecimiento de las pruebas o indicios concurren
tes y razonables que amparan su pretensión, solicitar medidas cautelares de considerarlo
necesario. El fiscal además debe notificar con la demanda al Procurador Público dentro
de las 24 horas a efectos que participe como sujeto procesal.
El Juez en un plazo de tres (03) días hábiles puede admitir, declarar inadmisible o impro
cedente la demanda. En caso se traten de casos declarados complejos el plazo será de
diez (10) días hábiles. En la resolución que se admite la demanda el juez resuelve sobre las
medidas cautelares solicitadas. En caso se declare inadmisible la demanda el juez otor
gara un plazo de tres (03) días hábiles para que sea subsanada. Vendido el plazo, de nos
subsanarse, se archiva la demanda. En caso se declare improcedente la demanda podrá
ser impugnada mediante recurso de apelación en un plazo de cinco (05) días hábiles. De
no apelarse en el plazo indicado se archiva la demanda.
17. DELITOS CONTRA LA ADMINISTRACIÓN PÚBLICA COMETIDOS POR FUNCIONARIOS
PÚBLICOS
Se debe tener en cuenta quienes cometen este delito, necesariamente tienen que ser funcio
narios Públicos, es decir, tiene que ser un sujeto activo especial y para ello debemos tener
claro quiénes son considerados funcionarios Públicos. El Art. 425 del Código Penal, considera
funcionarios o servidores públicos a las siguientes personas:
i. Los que están comprendidos en la carrera administrativa.
ii. Los que desempeñan cargos políticos o de confianza, incluso si emanan de elección popular.
iii. Todo aquel que, independientemente del régimen laboral en que se encuentre, mantiene
vínculo laboral o contractual de cualquier naturaleza con entidades u organismos del Es
tado, incluidas las empresas del Estado o sociedades de economía mixta comprendidas
en la actividad empresarial del Estado, y que en virtud de ello ejerce funciones en dichas
entidades u organismos.
iv. Los administradoresy depositarios de caudales embargados o depositados por autoridad
competente, aunque pertenezcan a particulares.
v. Los miembros de las Fuerzas Armadas y Policía Nacional.
vi. Los designados, elegidos o proclamados, por autoridad competente, para desempeñar
actividades o funciones en nombre o al servicio del Estado o sus entidades.
vii. Los demás indicados por la Constitución Política y la ley.
Con fecha 29 de junio de 2022 se publicó en el diario Oficial El Peruano, la Ley N° 31501, que
modifica diversos artículos del Código Penal e incorpora el art. 425-A al mismo cuerpo ñor-
