serán considerados dentro de dicha clasificación a “todo aquel que, independientemente de la na
turaleza del vínculo que mantenga con las entidades u organismos de un Estado extranjero, cuerpos
castrenses, policiales o cualquier agencia de seguridad nacional extranjera, empresas o sociedades que
estén comprendidas en la actividad empresarial de un Estado extranjero y que en virtud de ello actúan
como miembro, funcionario, designado, nombrado o representante de estos, incluso si su cargo emana de
elección popular Se incluye dentro de estos alcances a quienes ejercen estas funciones o roles en los orga
nismos internacionales”, a efectos de im putar los delitos de los arts. 393-A CP y 397-A CP Sin bien
nuestro Código Penal ya nos ofrece una definición sobre el “funcionario o servidor público” en
el art. 425 CR este hace referencia a los funcionarios o servidores públicos nacionales.
El artículo 425 es una norma abierta (numeras apertus) son todas aquellas no mencionadas
líneas arriba, ya sea porque tienen un régimen propio de carrera Administrativa, como los
funcionarios o servidores Judiciales, docentes y funcionarios de universidades, como decanos,
rectores etc, o porque simplemente carecen de un sistema de Carrera Administrativa como el
de los notarios, y árbitros.
La intervención de terceros (extraneus) que no tienen la calidad de funcionarios públicos que
exige la ley para ser autor del delito, debe ser reprimida a título de complicidad o, en su caso,
de instigación en relación al mismo hecho puniblefuncionarial. Esta conexión del partícipe ha
sido validada expresamente en el párrafo tercero del artículo 25 del C.P: «El cómplice siempre
responde en referencia al hecho punible cometido por el autor, aunque los elementos especia
les que fundamentan la penalidad del tipo legal no concurran en él».
La mayoría de los delitos funcionariales contra la administración pública son dolosos y de
realización comisiva. Sin embargo, en algunos casos se ha introducido modalidades culposas
(Art. 387, cuarto párrafo del C.R) pero también delitos de estructura omisiva (Art. 377 C.P).
La penalidad que contempla la ley para los delitos funcionariales es conjuntay considera tres
clases de penas: privativa de libertad, multa e inhabilitación.
1. Concusión (Art. 382 C.P.)
La concusión se diferencia de la extorsión en cuanto la violencia o el engaño provienen del fun
cionario que abusa de su cargo. La concusión se distingue de la Estafa porque éste es un delito
con sujeto independiente, es decir puede ser cometido por cualquiera ciudadano; mientras
que la concusión fraudulenta puede ser cometido por sujeto calificado, es decir solamente
por funcionario público abusando de su calidad. La concusión se distingue de la corrupción
en el uso de la violencia o del engaño, que faltan en la corrupción, por cuanto hay un concurso
de voluntades. En la Corrupción, el particular es sujeto activo junto con el funcionario por que
cooperan con este en el delito (delito bilateral), y en la concusión hay solamente un sujeto
pasivo no imputable (delito unilateral).
La concusión se diferencia del peculado, porque en este últim o la causa de la posesión es le
gítima (razón de cargo), mientras que en la concusión hay un aprovechamiento viciado por la
violenciay fraude.
