1.1. Bien Jurídico Protegido: La norma penal al conminar penalmente los comportamientos
señalados busca proteger el regular funcionamiento, el prestigio y la buena reputación de la
administración pública conjuntamente a la corrección y probidad de los funcionarios y servó
dores públicos.
1.2 . T ip ic id a d o b je tiv a
S u je to A ctivo: Sujetos activos pueden ser tanto los funcionarios, como los empleados o servi
dores públicos en.ejercicio. Incluso si éstos han cesado en sus funciones, si el bien o beneficio
patrimonial es producto de un acto abusivo cometido durante el ejercicio del cargo.
S u je to Pasivo: La administración pública (Estado).
El agraviado físico, que puede ser una persona natural o jurídica, o un colectivo social, es aquí
la víctima material.
C o m p o rta m ie n to s T íp ico s:
Los componentes materiales de tipicidad del comportamiento son los siguientes: a) abuso del
cargo; b) obligar o inducirá una persona a dar o prometer; c) el elemento normativo: indebida
mente; d) el objeto de la concusión un bien o un beneficio; y e) El desti natario: para sí o para otro.
a) Abuso del cargo
Abusando del cargo es sinónimo de haciendo mal uso de la calidad que le ha sido otor
gado, es decir, del oficio o investidura pública poseída, aprovechando así ilícitamente el
funcionario o servidor de las facilidades o ventajas que confiere el cargo.
b) Obligación de dar o prometer
El abuso del cargo practicado por el sujeto activo debe comprender el uso de la violencia
o el convencimiento ejercido sobre la víctima quien es forzada en su voluntad a acceder a
las ilegítimas pretensiones del agente.
c) Inducir a dar o prometer
Aquí el medio que emplea el sujeto activo consiste en vencer la voluntad de la persona
mediante la persuasión, el convencimiento, la apariencia, haciendo uso de estratagemas,
falsedades o silencios que tengan la suficiente fuerza determinadora para que la víctima
dé o prometa dar el bien o beneficio patrimonial.
d) El dary el prometer dar
El dary el prometer tienen como presupuestos típicos necesarios la existencia previa de
un uso abusivo del cargo expresado en el obligar o inducir que operan o actúan sobre la
voluntad de la víctima.
