Tema 6: Temas de la Especialidad Penal
Tipicidad subjetiva.- El elemento constitutivo del delito, “obligar” o “inducir” implica que ne
cesariamente tiene que haber dolo (concienciay voluntad); este tipo de delito está constitui
do sobre la base del dolo pero no cualquier dolo sino el dolo directo en los actos del agente ya
que de los medios empleados y el propósito buscado resulta impracticable que se produzca
con dolo eventual.
