2.2. Bien ju rídico protegido:
Salinas (2019) considera que «el delito de colusión al ser uno de infracción de deber, el bien
jurídico genérico esel norm aly recto funcionamiento de la Administración Públicaque es ma
nifestación material del Estado» (p. 361); asimismo, se da especial relevancia a las funciones
que el funcionario público debe realizar, cuyo incorrecto desempeño constituye precisamente
la lesión al bien jurídico protegido (Cáceres, 2016).
En relación a ello, algunos autores, como Abanto (2003), sostienen que «el bien jurídico es
pecífico de este delito viene a ser el patrimonio del Estado (p. 261); desde una óptica crítica,
Salinas (2019) afirma que el patrimonio vendría a ser el objeto del delito, mas no así el bien
jurídico por no tratarse de un delito contra el patrimonio».
En esta misma línea de razonamiento, es posible concluirque el patrimonio estatal por sí solo,
no puede ser considerado como el bien jurídico de especial protección de este delito, pues más
allá de confundirse con el objeto del delito, bien podría equipararse a otros delitos como el
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1048 of 1506 --

UBILEX
peculadoy la malversación de fondos donde también se ve afectado el patrimonio del Estado,
o a la vez, podría liar indebidamente los conceptos de bien jurídico y objeto del delito.
2.3. Tipicidad objetiva:
Sujeto activo: Se trata de un delito contra laadministración pública cometido porfuncionario
público. Por lo tanto, el sujeto activo del delito siempre será un funcionario o servidor público.
Sin embargo, la condición de funcionario no es suficiente para que un sujeto pueda ser con
siderado autor de este delito, ya que adicionalmente deberá manifestar un deber especifico.
Siguiendo dicho razonamiento, un sector de la doctrina nacional afirma que “no basta dicha
calidad para tener por realizado el injusto penal, dado que es necesario contar con una com
petencia normativa específica para intervenir en los procesos de contratación pública” (Casti
llo, Z017, p. 146).
Siendo que el tipo penal sanciona un pacto o acuerdo colusorio, es necesario que además de
verificarse la participación del funcionario público, se identifique la intervención del interesa
do, quien no es otro que el administrado que participa en la contratación o en las operaciones
estatales; este interesado, denominado también como extraneus, no podrá responder a título
de autor, al no ostentar función pública, por lo que el título de imputación que le corresponde
es la de cómplice primario.
Sujeto pasivo: De conformidad con nuestra legislación Penal, el Estado es el afectado por este
delito. Justamente, para cumplir sus respectivas funciones, las diversas entidades del Estado,
como los Gobiernos Regionales, las Municipalidades, los hospitales, las universidades, el pro
pio Poder Judicial y Ministerio Público, entre otras, requieren celebrar contratos, así como rea
lizar operaciones de naturaleza económica; en estos actos sus funcionarios pueden concertar
con los terceros interesados para defraudar a la entidad.
Concertación: El tipo penal del delito de colusión, previstoy sancionado en el artículo 384 del
Código Penal, tipifica la conducta representada por el verbo rector de «concertar». El Dicciona
rio de la Real Academia Española define al verbo «concertar» como «acordar el precio de algo»,
«pactar, ajustar, tratar o acordar un negocio» (Real Academia Española (RAE), s.f.).
Un sector de la doctrina nacional se refiere a la conjunción de la conducta del funcionario con
la conducta del contratista, en cuyo encuentro se configura la concertación, la cual siempre
debe tener una finalidad defraudatoria del Estado (Castillo, 2017; Reátegui, 2015). En contras
te con ello, la jurisprudencia nacional estableció que la conducta del sujeto activo “determina
un alejamiento del agente respecto a la defensa de los intereses públicos que le están enco
mendados, y de los principios que informa la actuación administrativa”. (Corte Suprema, R.N.
N 01296-2007''Li ma).
Así, respecto al sujeto activo del delito, se distinguen al funcionario público y al extraneus,
entre quienes se configura el acuerdo colusorio, determinando que el delito de colusión sea
uno de convergencia, o denominado también «delito de encuentro, o pluripersonal» (Castillo,
2017, p. 239)- De esta manera, se diferencian de los denominados delitos monosubjetivos don
de «el tipo penal solo puede ser realizado por un individuo en calidad de autor» (ViIlavicencio,
2006, p. 308). Por lo tanto, será necesaria la participación de un funcionario y un tercero inte
resado para que pueda configurarse la concertación.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1049 of 1506 --

Tema 6: Temas de la Especialidad Penal
La concertación constituye el principal elemento de la conducta ilícita que sanciona el delito
de colusión, pues es de esta forma que surge el pacto o acuerdo subrepticio entre el funcio
nario y el extraneus, y es a raíz de esta concertación que se vulnera el bien jurídico tutelado.
Por otro lado, no se establece cómo deba realizarse este acuerdo, pudiendo representarse de
distintas formas, ahora bien, esta am plitud de posibilidades conlleva a plantearse si es que
pueda existir la concertación a través de conductas omisivas y si una omisión impropia puede
equipararse a una concertación.
Defraudación: La doctrina nacional señala que “defraudar, estafar o tim ar al Estado significa
el quebrantamiento del rol especial asumida porel agentey laviolación del principio de con
fianza depositado” (Rojas, 2002, p. 281). Cabe recalcar que la concurrencia de dicho elemento
será distinta en las modalidades del delito de colusión.
En la modalidad simple del delito de colusión, la defraudación a la que hace referencia el pri
mer párrafo del artículo 384 del Código Penal «no constituye un elemento objetivo del tipo,
sino un elemento tendencia». (Garcíay Castillo, 2008, p. 28).
En cuanto a la modalidad agravada del delito de colusión, se tiene que al ser su nota caracte
rística la defraudación, «el concepto de defraudare o tim ar al Estado significa engaño al inte
rés público y, como consecuencia de ello, un efectivo perjuicio patrimonial al erario público».
(Salinas, 2019, p. 351)
Siendo ello así, existe el criterio que refiere que la afectación sobre los intereses del Estado se
verificará objetivamente a través de un perjuicio de naturaleza patrimonial, por más que se
trate de forzar dicha comprobación a través de otros mecanismos no necesariamente patri
moniales (Reátegui, 2015). Por lo tanto, no sería posible afirm ar que la modalidad agravada
se configura por un perjuicio potencial, si fuere ello así, la conducta podría subsumirse en la
modalidad simple.
2.4. Modalidades agravadas:
El 08 de abril de 2021 se publicó la Ley N° 31178 que modificó varios artículos del Código Penal,
una modificación importante fue la incorporación de nuevas agravantes para el delito de co
lusión, así tenemos (3er párrafo art. 384 CP):
"La pena será privativa de libertad no menor de 15 ni mayor de 20 años; inhabilitación a que se refieren los
incisos 1 , 2 y 8 del artículo 36, de naturaleza perpetua, y, con 365 a 730 días-multa, cuando ocurra cualquiera
de los siguientes supuestos:
1. El agente actúe como integrante de una organización criminal, como persona vinculada o actúe por encar
go de ella.
2 . La conducta recaiga sobre programas con fines asistenciales, de apoyo o inclusión social o de desarrollo,
siempre que el valor del dinero, bienes, efectos o ganancias involucrados supere las diez unidades imposi
tivas tributarias.
3 . El agente se aproveche de una situación de calamidad pública o emergencia sanitaria, o la comisión del
delito comprometa la defensa, seguridad o soberanía nacional."
