Y NOMBRAMIENTO DE JUECES Y FISCALES 1049

-- 1050 of 1506 --

UBILEX
2.5. Diferencia básica entre colusión simple y agravada (CAS. N.° 1 6 4 8 -2 0 1 9 /
Moquegua. Sala Penal Permanente 3 1 /0 8 /2 0 2 1 )
El nomen ¡uris legalmente fijado de este tipo delictivo es: colusión sim pley colusión agravada
(contempla dos variantes). El primer párrafo (colusión simple) importa que el agente oficial
se concierta con los interesados para defraudar al Estado o entidad u organismo del Estado.
El segundo párrafo (colusión agravada) exige que la concertación con los interesados importe
una defraudación patrimonial al Estado o entidad u organismo del Estado.
Lo especialmente relevante es el deber del oficial público (deber positivo) de velar por los in
tereses patrimoniales del Estado en las contrataciones públicas. Éste debe preservar los in
tereses patrimoniales del Estado, excluyéndose acuerdos con los particulares que impliquen
un abandono de su posición de defensa [Ejecutoria Suprema RN 79-2003/Madre de Dios, de
15 de febrero. García Cavero, Percy: El delito de colusión desleal. En AA.VV.: Delitos contra la
Administración Pública, Editorial Ideas, Lima, 2020, p. 167].
El acuerdo colusorio se debe dar entre el agente oficial competente y el extraneus. Éste su
pone un pacto o compromiso (generalmente oculto y, por tanto, de acreditación mediante
prueba por indicios: ex artículo 158, numeral 3, del Código Procesal Penal) que excluya una
negociación correcta con perjuicio parala Administración (condiciones menos ventajosas), y
puede tener lugar desde la generación de la necesidad y el requerimiento, pasando por las
etapas subsiguientes, hasta la ejecución y la liquidación incluso.
La colusión simple se consuma con el acuerdo colusorio. No es necesario que se haya ejecu
tado lo acordado, ni que se haya generado un peligro concreto de lesión o una lesión efectiva
al patrimonio del Estado (ha de ser un acuerdo colusorio idóneo para defraudar: (peligro abs
tracto) .
La colusión agravada se produce con la defraudación patrimonial al Estado-es un delito de
lesión, de resultado: lo ejecutado ha de importar un perjuicio para el Estado-, y si el acuerdo
colusorio se ejecuta y solamente se genera un peligro concreto de afectación patrimonial al
Estado, tal conducta se castiga como tentativa de colusión agravada [García Cavero, Percy: Ibí-
dem, pp. 187,192 y 195], dato que a menudo se olvida por focalizar el delito desde la exclusiva
perspectiva de su consumación, sin advertir las formas imperfectas de ejecución delictiva.
3. Peculado
Es motivo de debate doctrinario, aún no concluido, si los delitos de peculado poseen funda
mentalmente naturaleza patrimonial o son en cambio manifestaciones de deslealtad del
funcionario para con la gestión de los recursos públicos, si se trata de un delito pluriofensivo
-com o sostiene la mayoría de la doctrina ita lia na - lesionando, por lo mismo, por igual el pa
trim onio públicoy el regular ejercicio de las funciones públicas.
