Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1051 of 1506 --

Tema 6: Temas de la Especialidad Penal
3.1. Descripción norm ativa:
.Peculado doloso:
Alt, 387, primer párrafo del C .fi: "El funcionario o servidor público que se apropia o utiliza, en cualquier
forma, para s í o para otro, caudales o efectos cuya percepción, administración o custodia le estén
confiados por razón de su cargo, será reprimido con pena privativa de libertad no menor de cuatro ni
mayor de ocho años; inhabilitación a que se refieren ios incisos l , 2 y 8 del artículo 36, de cinco a veinte años, ■
y, con ciento ochenta a trescientos sesenta y cinco días-multa. ''
Peculado culposo;
Art, 387, último párrafo del C.fi: S i el agente, por culpa, da ocasión a que se efectúe por otra persona la
sustracción de caudales o efectos, será reprimido con pena privativa de libertad no mayor de dos años y con
prestación de servicios comunitarios de veinte a cuarenta jornadas. Constituye circunstancia agravante si los
caudales o efectos estuvieran destinados a fines asistenciales o a programas de apoyo o inclusión social. En
estos casos, la pena privativa de libertad será no menor de tres ni mayor de cinco años y con ciento cincuenta
a doscientos treinta días-multa."
3.2. Bien Jurídico Protegido:
Para la existencia del delito de peculado no es necesario que sobre los bienes que se le haya
confiado por razón de su cargo en cualquiera de las formas y que constituyan el objeto mate
rial del hecho ¡lícito, el agente ejerza una tenencia material directa. Es suficiente que el sujeto
activo tenga la llamada disponibilidad jurídica, es decir, aquella posibilidad de libre disposi
ción que en virtud de la ley tiene el funcionarlo o servidor público; debe tener, por tanto, com
petencia funcional específica. La disponibilidad a que se hace referencia se encuentra íntim a
mente ligada a las atribuciones que el agente ostenta como parte que es de la administración
pública. Todo ello nos lleva a sostener que tratándose el peculado de un delito pluriofensivo,
el bien jurídico se desdobla en dos objetos específicos merecedores de protección jurídico
- penal: a) garantizar el principio de la no leslvldad de los intereses patrimoniales de la Ad
ministración Públlcay b) evitar el abuso del poder del que se halla facultado el funcionario o
servidor público que quebranta los deberes funcionales de lealtady probidad192.
3.3. Tipicidad objetiva
Sujeto Activo: Tanto en el delito doloso como culposo de peculado sólo puede ser autor el
funcionario o servidor público que reúne las características de relación funcional exigidas por
el tipo penal, es decir, quien por el cargo tenga bajo su poder o ámbito de vigilancia, en per
cepción, custodia o administración las cosas (caudales o efectos) de los que se aproplay utiliza
para sí o para otra.
"El sujeto activo debe tener una calidad especial (sujeto cualificado) que lo diferencie del resto
de personas, lo que se traduce en ser funcionarlo o servidor público; adicionalmente, el tipo
penal también precisa como un elemento determinante que debe reunir el sujeto activo, que
este actúe respecto de los bienes protegidos “por razón de su cargo”. Esto quiere decir que no
cualquier funcionario o servidor público puede ser Imputado por el delito de peculado, pues
192 Acuerdo Plenario N.° 4-2005/Q-116. Fj. 6 .
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 1051

