UBILEX
se debe requerir una especial atribución respecto de los bienes que se habría apropiado (vin
culación especial).” Cas. 160-2014» Del Santa. Fj. 9. Doctrina Jurisprudencial.
Sujeto Pasivo: El Estado, en la amplia diversidad de sus manifestaciones.
Com portam ientos Típicos:
Es necesario tener en cuenta los comportamientos típicos que la norma en análisis nos seña
la a efectos de lim itar o restringir la relevancia penal de los actos del delito de peculado. La
norma, por consiguiente, al describir la acción dolosa utiliza dos supuestos para definir los
comportamientos típicos del sujeto activo: apropiaro utilizar, los mismos que deben contener
ciertos elementos para su configuración; estos son, en tal virtud, los elementos materiales del
tipo penal:
a. Existencia de una relación funcional entre el sujeto activo y los caudales y efectos. Se en
tiende por relación funcional el poder de vigilancia y control sobre la cosa como mero
componente típico, esto es, competencia del cargo, confianza en el funcionario en virtud
del cargo, el poder de vigilary cuidar los caudales o efectos.
La existencia de una relación funcional entre el sujeto activo y los caudales y efectos. La
relación funcional alude al poder de vigilancia y control sobre la cosa, sobre criterios de
competencia del cargo, confianza en el funcionario en virtud del cargo; el poder de vigilar
y cuidar los caudales y efectos.193
b. La percepción, no es más que la acción de captar o recepcionar caudales o efectos de pro
cedencia diversa pero siempre lícita. La administración, que implica las funciones activas
de manejo y conducción. La Custodia, que importa la típica posesión que implica la pro
tección, conservación y vigilancia debida por el funcionario o servidor de los caudales y
efectos públicos.
c. Apropiación o utilización. En el primer caso estriba en hacer suyo caudales o efectos que
pertenecen al Estado, apartándolo de la esfera de la función de la Administración Pública
y colocándose en situación de disponer de los mismos. En el segundo caso: utilizar, se
refiere al aprovecharse de las bondades que permite el bien (caudal o efecto), sin tener el
propósito final de apoderarse para sí o para un tercero.
d. El destinatario: para sí. El sujeto activo puede actuar por cuenta propia, apropiándose él
mismo de los caudales o efectos, pero también puede cometer el delito para favorecer a
terceros. Para otro, se refiere al acto de traslado del bien, de un dom inio parcial y de trán
sito al dom inio final del tercero.
e. Caudales y efectos. Los primeros, son bienes en general de contenido económico, incluido
el dinero. Los efectos, son todos aquellos objetos, cosas o bienes que representan un valor
patrimonial público, incluyendo los títulos valores negociables.
Respecto a la conducta culposa, es de precisar que dicha figura no está referida a la sustrac
ción por el propio funcionario o servidor público de los caudales o efectos, se hace referencia
directamente a la sustracción producida por tercera persona, aprovechándose del estado de
descuido imputable al funcionario o servidor público. Es decir, se trata de una culpa que ori
193 R.N. N°i78o-20i5-Tacna.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1053 of 1506 --

Tema 6: Temas de la Especialidad Penal
gina (propiciando, facilitando, permitiendo de hecho) un delito doloso de tercero; sea que lo
sustrajo con la intención de apropiación o de utilización, sea que obtuvo o no un provecho. El
tercero puede ser un particular u otro funcionario o servidor público que no tenga la percep
ción, administración o custodia de los bienes sustraídos, no se castiga la sustracción de cauda
les o efectos, sino el dar lugar culposamente a que otro lo sustraiga dolosamente.194
Dentro de los componentes típicos de la modalidad culposa tenemos:
a) La sustracción.- El verbo rector “sustraer” significa el alejamiento de los caudales o efec
tos del ámbito de vigilancia de la administración pública, con aprehensión física de los
mismos por parte del tercero, que se aprovecha así del estado de culpa incurrido por el
funcionario o servidor. La disponibilidad es un elemento no necesariamente exigible para
perfeccionar la sustracción, lo que implica que no se requiere que el agente disponga del
bien o que éste sea irrecuperable. Sustraeres, así, extraer, retirar o alejar el bien del lugar
donde se encuentra, en este caso bajo dom inio de la administración pública.
b) La culpa del funcionario o servidor público.- Habrá culpa en el sujeto activo del delito,
cuando éste no toma las precauciones necesarias para evitar sustracciones (la culpa del
delito de peculado se refiere exclusivamente a sustracciones, no al término impreciso de
“pérdidas”), vale decir cuando viola deberes del debido cuidado sobre los caudales o efec
tos, a los que está obligado por la vinculación funcional que mantiene con el patrimonio
público.
3.4. Tipicidad subjetiva
El peculado en su modalidad dolosa requiere o exige que el funcionario o servidor público
actúe con conocimiento que tiene el deber de lealtad y probidad de percibir, adm inistrar o
custodiar adecuadamente los bienes públicos confiados a su cargo195. El delito de peculado
culposo, por su parte, se configura cuando el funcionario o servidor público, por culpa o negli
gencia, da ocasión que un tercero sustraiga de la Administración Pública, caudales o efectos
que están confiados a él en razón del cargo que ostenta para el Estado196. Sin embargo, si el
funcionario o servidor público tenía conocimiento de los hechos de sustracción de caudales
o efectos por parte de otras personas, y no obstante ello permite que otras personas hagan
sustracciones; este hecho será considerado, ya no como autor del delito de peculado culposo,
sino de autor del delito de peculado doloso.
3.5. Autoría y participación
En cuanto a la autoría y participación, de la lectura del tipo penal regulado en el artículo 387
del CP se concluye que no estamos ante un delito especial, como señala la doctrina, sino ante
un delito especialísimo de infracción de deber. Aquí, además de exigirse que el agente cuente
con la condición de funcionario o servidor público, se exige que tenga también una relación
funcional ineludible con el objeto del delito. Es decir, no cualquier funcionario o servidor pú
194 Acuerdo Plenario N.°4-2005/C]-il6. Fj. 7,8.
195 SALINAS SICCHA, en Delitos contra la Administración Pública, Idemsa/Centro de Estudios Penales, 2013, p. 366.
196 BENAVENTE CHORRES/CALDERÓN VALVERDE, Delitos de corrupción de funcionarios, p. 165.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1054 of 1506 --

blico puede ser autor del delito de peculado. Está reservado para determinados sujetos públi
cos. Solo son candidatos a ser autores de este delito aquellos sujetos públicos que tienen la
función de administrar, custodiaro percibir los fondos públicos. Los demás que participan jun
to al sujeto público obligado en la sustracción o utilización del fondo estatal sin tener aquellas
funciones o condiciones, serán a lo más cómplices del delito. La complicidad en el delito de pe
culado se da desde la etapa de preparación del hecho hasta antes de la consumación, siendo
el cómplice primario (o necesario) aquel que desde dicha etapa aporta al hecho principal, una
contribución sin la cual el delito no hubiera sido posible de cometer; estando compuesto por
dos elementos, a saber: i) La intensidad objetiva de su aporte al delito, vale decir que sin este el
hecho no hubiera podido cometerse,y ii) El momento en que realiza su aporte, el mismo que
debe ser anterior a la ejecución y en algunos casos hasta durante la ejecución del mismo, pero
en este últim o caso se debe verificar que no tuvo dom inio del hecho, en tal caso respondería
como autor.197
Aquí debe precisarse que no solo los funcionarios o servidores públicos de la burocracia tradi
cional pueden ser autores del delito de peculado, sino también, de acuerdo con el artículo 425,
inciso 3, del CP, pueden serlo los particulares que han sido contratados para ejercer la función
específica de percibir, custodiaro administrar fondos públicos.
3.6. Consumación
La consumación del delito de peculado por apropiación se da con la incorporación del patri
monio público al patrimonio personal, siendo de naturaleza instantánea (Rojas, 2007, p. 501).
El delito de peculado se configurará incluso cuando se haya restituido el bien materia de apro
piación. Porotro lado, en la modalidad de utilización, la consumación se presentará con el uso
privado del caudal o efecto. Cuando el destinatario de los caudales o efectos es otra persona,
el delito se consuma cuando se hace entrega de los bienes públicos, «momento en que ellos
salen de la esfera de dom inio estatal».
El tipo penal de peculado no requiere que se produzca para consumarse un provecho econó
mico o utilidad para el sujeto activo o tercero, aunque podría interpretarse que la incorpora
ción de los efectos o caudales sea una modalidad de provecho. Si bien es cierto, este provecho
no resulta requerible como componente del tipo penal, sí resulta ser un dato objetivo-subjeti
vo que lo acompaña tanto para los intraneus como para los extrawews.198
En el caso del delito de peculado culposo, al ser de resultado material, se halla consumado
al producirse la sustracción de los caudales o efectos por acción de un tercero (es decir, me
diante el inicio del alejamiento del caudal o efecto de la esfera de dom inio oficial, no siendo
necesaria la disponibilidad del bien o efecto por dicho tercero), bajo la circunstancia anota
da de culpa del funcionario o servidor que propicia o facilita culposamente dicho resultado
de sustracción.
197 Cas. N.° 102-2016 Lima. Segunda Sala Penal Transitoria de la Corte Suprema. 11/07/2017.
198 R.N. 525-2015, Ayacucho.
