Tema 6: Temas de la Especialidad Penal
3.7. Circunstancias agravantes
Entre las circunstancias que agravan el delito de peculado tenemos: i. El agente actúe como
integrante de una organización criminal, como persona vinculada o actúe por encargo de ella.
2. Los caudales o efectos estuvieran destinados a fines asistenciales o a programas de apoyo
o inclusión social o de desarrollo. 3. El agente se aproveche de una situación de calamidad
pública o emergencia sanitaria, o la comisión del delito comprometa la defensa, seguridad o
soberanía nacional. 4 - El valor de lo apropiado o utilizado sobrepase 10 UIT.
En estos casos, la conducta es más reprochable penalmente y, por tanto, la pena será privativa
de libertad no menor de ocho ni mayor de quince años; inhabilitación a que se refieren los
incisos 1,2 y 8 del artículo 36, de naturaleza perpetua, y, con trescientos sesenta y cinco a sete
cientos treinta días-multa.
4. Corrupción de funcionarios (Ver páginas 203 y ss.)
18. DELITOS CONTRA LA SEGURIDAD PÚBLICA
18.1. Delito de peligro común
El concepto de peligro común, es aquel en el que las posibilidades de dañar bienes jurídicos se
extiende a un número indeterminado de personas que son titulares de ellos, amenaza a los de
toda una comunidad o colectividad.
— Peligro por medio de incendio o explosión: Según el Art. 273 C.R-. “El que crea un peligro co
mún para las personas o los bienes mediante incendio, explosión o liberando cualquier clase de
energía, será reprimido con pena privativa de libertad no menor de tres ni mayor de diez años”.
El tipo penal descrito, se trata de un delito de peligro abstracto. En estos delitos, a diferencia
de los delitos de peligro concreto, se castiga una acción típicamente peligrosa o “peligrosa en
abstracto”, sin exigir que se haya puesto efectivamente en peligro el bien jurídico protegido.
Formas agravadas:
La pena será privativa de libertad no menor de 06 ni mayor de 15 años cuando en la comisión deldelta»
previsto en el artículo 273 concurre cualquiera de las siguientes circunstancias: í®¡¡
1. Si hay peligro de muerte para las personas.
2. Si el incendio provoca explosión o destruye bienes de valor científico, histórico, artístico, cultural,
religioso, asistencial, militar o de importancia económica.
3. Si resultan lesiones graves o muerte y el agente pudo prever estos resultados.
— Producción de peligro en el servicio público de transporte de pasajeros: Señala el Art. 273-A
del C.R: “El que presta el servicio público de transportes de pasajeros y/o el que conduce vehículos de dicho
servicio, con o sin habilitación otorgada por la autoridad competente, que pueda generar un peligro para la
vida, la salud o la integridad física de las personas al no cum plir con los requisitos de ley para circular y que,
además, dicho vehículo no cuente con el correspondiente Seguro Obligatorio de Accidentes de Tránsito vigen
te o no haya pasado la últim a inspección técnica vehicular, será reprimido con pena privativa de libertad no
menor de uno (1) ni mayor de tres (3) años e inhabilitación conforme al artículo 36, inciso 7.”
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1056 of 1506 --

UBILEX
Este delito solo podrán cometerlo aquellos que presten o conduzcan un vehículo de servicio pú
blico de transporte de pasajeros. Se trata de un delito de peligro concreto porque el tipo penal es
tablece que “pueda generar un peligro para la vida, la salud o la integridad física de las personas”,
al señalar que "no cumplir con los requisitos de ley para circular” la vulneración normativa es la
que debe haber provocado el riesgo jurídicamente desaprobado, es decir, que con esa vulnera
ción se pone en peligro (concreto) al bien jurídico.
Asimismo, no contar con el SOAT o no contar con la últim a inspección técnica vehicular se
vuelve elemento típico imprescindible de configuración legal.
— Conducción en estado de ebriedad o drogadicción: Según lo dispuesto en el art. 274 del
C.R: “El que encontrándose en estado de ebriedad, con presencia de alcohol en la sangre en proporción
mayor de 0 .5 gram os-litro, o bajo el efecto de drogas tóxicas, estupefacientes, sustancias psicotrópicas o
sintéticas, conduce, opera o maniobra vehículo motorizado, será reprimido con pena privativa de la liber
tad no menor de seis meses ni mayor de dos años o con prestación de servicios comunitarios de cincuenta
y dos a ciento cuatro jornadas e inhabilitación, conforme al artículo 36 inciso 7).
Cuando el agente presta servicios de transporte público de pasajeros, mercancías o carga en general, en
contrándose en estado de ebriedad, con presencia de alcohol en la sangre en proporción superior de 0.25
gramos-litro, o bajo el efecto de drogas tóxicas, estupefacientes, sustancias psicotrópicas o sintéticas, la
pena privativa de libertad será no m enor de uno ni mayor de tres años o con prestación deservicios comu
nitarios de setenta a ciento cuarenta jornadas e inhabilitación conforme al artículo 36, inciso 7).”
Bien jurídico protegido: El delito de conducción de vehículo en estado de ebriedad es un de
lito pluriofensivo, pues ofende a una pluralidad de bienes jurídicos como la vida, la salud, la
seguridad pública, la seguridad en el tráfico, etc., sin embargo, en atención a nuestra norma
punitiva, tenemos que el bien jurídico tutelado es la seguridad pública y, dentro de ella, la
seguridad del tráfico rodado.
La seguridad pública engloba un conjunto de condiciones que el Estado debe de proveer para
latranquilidady sosiego desús miembros; hallándose la seguridad del tráfico rodado inmersa
dentro de aquella.
Tipicidad objetiva: Del artículo 274 del Código Penal se advierten ciertos elementos configu
rativos del delito sub examine, como son:
a) Conducir, operar o maniobrar un vehículo motorizado. La norma penal hace referencia
a tres verbos de manera indistinta: conducir, operar y maniobrar, que semánticamente
significan:
Conducir: Es llevar, transportar de una parte a otra; guiar o dirigir hacia un lugar;
guiar o dirigir a un objetivo o a una situación; guiar un vehículo automóvil; manejar
se, portarse, comportarse, proceder de una u otra manera, bien o mal.
Operar: Es realizar o llevar a cabo algo; producir una cosa el efecto para el cual se
destina; obrar, trabajar, ejecutar diversos menesteres u ocupaciones; maniobrar, lle
var a cabo alguna acción con auxilio de aparatos.
Maniobrar: Es realizar maniobras (operaciones que se hacen con otros vehículos
para cambiar de rumbo, operación material que se ejecuta con las manos).
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1057 of 1506 --

Tema 6: Temas de la Especialidad Penal
Como se observa, las acepciones de dichos verbos guardan cierta sinonimia: dichas accio
nes están orientadas a manejar o manipular los mecanismos de dirección, control y pro
pulsión de un vehículo motorizado, desplazándolo del lugar donde se encuentra. Dicha
afirmación cobra relevancia, en tanto el vehículo motorizado debe ponerse en marcha, de
modo que dicho desplazamiento tenga cierta duración temporal e implique el recorrido
de cierto espacio.
Así, no se encuadraría en el tipo penal la conducta de quien, encontrándose dentro de un
vehículo en estado de ebriedad, únicamente lo enciende, pero no opera los mecanismos
de desplazamiento (v. gr. embrague, acelerador, caja de cambios, etc.), de forma que el
vehículo se mantiene inmóvil en su posición.
La conducción del vehículo debe realizarse en la vía pública, descartándose la conducción
que se produce en un descampado, en un terreno desértico, en un pueblo abandonado,
en un estacionamiento particulary similares; lugares que no tienen por finalidad el des
plazamiento o circulación de vehículos o peatones, atendiendo, además, a los criterios de
mínima lesividad.
Debe tenerse presente que quien conduce sea quien manipule, dirija y controle el vehí
culo motorizado, vale decir quien traslade un vehículo de un lado a otro, manejando sus
mecanismos de impulso y dirección, y que dicho desplazamiento se produzca gracias al
impulso del motor. No es por ende, jurídico penalmente relevante el hecho de empujaren
estado de ebriedad un vehículo malogrado.
b) Encontrarse en estado de ebriedad, con presencia de alcohol en la sangre en propor
ción mayor de 0.5 gramos-litro: Las drogas tóxicas, estupefacientes, sustancias psico-
trópicas o bebidas alcohólicas y similares producen el efecto de dism inuir las facultades
psíquicas, reflejos, atención, etc., en los conductores. Pero esta disminución no comienza
hasta cierta cantidad y varía de un sujeto a otro; por eso, se plantea el problema de de
terminar cuáles son las dosis que hacen incurrirá un conductor en este delito. La práctica
tiende a fijar unos índices de alcoholemia, que se determinan con una serie de procedi
mientos técnicos; por encima de estos índices, no está permitido ponerse al volante de un
vehículo).
Nuestra legislación, mediante la Ley N° 27753, estableció una cuantificación de alcohol
en la sangre (más de 0.5 gramos-litro), a efectos de establecer el estado de ebriedad y
estimar la conducción de un vehículo automotor como ilícito penal.
Tipicidad subjetiva: En el tipo subjetivo es necesaria la conciencia que se conduce en esta
do de ebriedad, siendo necesario, por lo tanto, el dolo requiere tanto el conocimiento por el
autor del hecho de conducir tras haber ingerido las sustancias descritas en el tipo penal y de
la influencia negativa de estas sobre la conducción, así como la voluntad de actuar en esas
condiciones.
Consumación: “La razón para incriminar dicha conducta es el peligro que genera para la segu
ridad del tráfico público. De esta manera, estamos ante un delito de peligro abstracto donde
la mera conducción en estado de ebriedad acarrea, sin más, la comisión del hecho punible. En
otras palabras, el delito de conducción en estado de ebriedad se consuma por el solo hecho de
