-- 1059 of 1506 --

Tema 6: Temas de la Especialidad Penal
Con fecha 14 de diciembre de 2023 se publica el Decreto Legislativo N° 1592, dispositivo legal
que modifica varios artículos del Decreto Legislativo N ° i24i (decreto legislativo que fortalece
la lucha contra el tráfico ilícito de drogas) y 3 artículos del Código Penal, entre ellos el artículo
296, que en su segundo párrafo amplía la definición de drogas tóxicas para abarcar también
las «nuevas sustancias psicoactivas», enfatizando que su uso debe ser ilegal, ello con el objeto
de actualizar el marco normativo sobre el tráfico ilícito de drogas.
El artículo 296 del Código penal ha sido considerado como el tipo base del delito del tráfico
¡lícito de drogas, al definir qué actos configuran dicho delito. Sin embargo, este artículo no
tipifica un solo delito, sino cuatro delitos diferentes entre sí. Es a raíz de esto que cabe conside-
rarlo como un tipo penal de composición múltiple, que además dota de características propias
a cada una de las cuatro conductas delictivas, identificándose, por tanto, elementos típicos y
momentos consumativos diferenciables.
El comportamiento consiste en: a) De la promoción, favorecí miento o facilitación del consu
mo ilegal de drogas mediante actos de fabricación o tráfico b) De la posesión de drogas para
su tráfico ilícito c) Del suministro, la producción o comercialización de materias primas o insu
mos destinados a la elaboración de drogas y actos afines de promoción d) De la conspiración
para promover, favorecer o facilitar el tráfico ¡lícito de drogas.
1. Déla promoción, favorecí miento o facilitación del consumo ilegal de drogas mediante
actos de fabricación o tráfico: Con los términos PROMOVER, FAVORECER O FACILITAR,
se comprueba como nuestro legisladorsigue latendenciaomnicomprensivaen loque se
ha dado en llamar “ciclo de la droga”, es decir, la penalización de todo comportamiento
que suponga una contribución, por mínima que sea, su consumo. Pero hay que precisar
el Código Penal no castiga todo promoción, favorecimiento o facilitación del consumo
ilegal de droga, sino solo sólo aquellos comportamientos que se realizan mediante actos
de fabricación o tráfico o que consistan en su posesión con dicho fin.
Por ACTOS DE FABRICACIÓN se entiende cualquier proceso de elaboración, mecánico o
químico, sin excluir la simple adición de una sustancia a otra u otras (composición), dado
que no solo se fabrica cuando se obtiene droga de una a más materias, que antes no te
nían ese carácter, sino también con la reproducción, transformación o perfeccionamiento
de materias ya de por sí estupefacientes.
El término TRÁFICO se refiere a todo acto de comercio, negociación o actividad que busca
la obtención, venta, almacenamiento, distribución, transporte, etc.
Este supuesto es un tipo penal alternativo, pues comprende varias opciones para la mate
rialización de la conducta punible, aunque para su tipificación tan solo será necesario que
el sujeto activo realice cuando menos uno de aquellos comportamientos que constituyen
actos de fabricación o tráfico.
2. De la posesión de drogas para su tráfico ilícito: Actos de Posesión, relación de hecho
que une al sujeto con la droga, se reprime la posesión con fines de comercialización no la
simple posesión.
El sujeto que posee para su consumo no será reprimido con una sanción punitiva; tiene
que ser una posesión con fines lucrativos. También se considera o están inmersos dentro
