Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1061 of 1506 --

Tema 6: Temas de la Especialidad Penal
Tipicidad subjetiva:
En el comportamiento del primer párrafo del artículo 296 se requiere necesariamente el dolo,
pero en el caso de posesión (segundo párrafo CP) se exige, además, un elemento subjetivo
del tipo consistente en la intención de destinar la posesión de droga al tráfico. En el compor
tamiento recogido en el tercery cuarto párrafos del artículo 296 del Código Penal se requiere,
también aparte del dolo, un elemento subjetivo consistente en la intención de destinar el co
mercio a la elaboración de drogas toxicasy formar parte de una conspiración de personas para
promover, favorecer o facilitar el tráfico ilícito de drogas.
19.2. Comercialización y cultivo de amapola y marihuana y su siembra compulsiva
19.2.1. Descripción normativa:
“Art. 296-A CP. El que promueve, favorece, financia, facilita o ejecuta actos de siembra o cultivo de plan
tas de amapola o adormidera de la especie papaver somníferum o marihuana de la especie cannabís
sativa será reprimido con pena privativa de libertad no m enor de ocho años ni mayor de quince años
y con ciento ochenta a trescientos sesenta y cinco días-multa e inhabilitación conforme al artículo 36,
in cisos!), 2) y 4).
El que comercializa o transfiere semillas de las especies a que alude el párrafo anterior será reprimido con\
pena privativa de libertad no menor de cinco ni mayor de diez años y con ciento veinte a ciento ochenta
días-multa, e inhabilitación conforme al artículo 36, incisos !) y 2),
La pena será privativa de libertad no menor de dos ni mayor de seis años y de noventa a ciento veinte días-mul
ta cuando:
1. La cantidad de plantas sembradas o cultivadas no exceda de cien.
2, La cantidad de semillas no exceda de la requerida para sembrar el número de plantas que señala el inciso
precedente.
Será reprimido con pena privativa de libertad no menor de veinticinco ni mayor de treinta y cinco años, e
inhabilitación conforme al artículo 36, incisos 1) y 2), el que, mediante amenaza o violencia, obliga a otro a la
siembra o cultivo o al procesamiento ilícito de plantas de coca, amapola o adormidera de la especie papaver
somníferum, o marihuana de la especie cannabis sativa. Se excluye de los alcances de lo establecido en el :
presente artículo, la siembra o cultivo cuando se haya otorgado licencia para la investigación del cannabis y
sus derivados, o para la comercialización o producción farmacológica o artesanal de los derivados del can
nabis con fines medicinales y terapéuticos. De incumplirse con la finalidad de la licencia señalada, se deja sin \
efecto la presente exclusión. Será reprimido con la pena máxima más el cincuenta por ciento de la misma al
funcionario público que otorga irregularmente la licencia o autorización referida".
Lo que prohíbe el legislador no es el autoconsumo o incluso el autocultivo (sea para fines me
dicinales o recreativos), sino el tráfico y todas las actividades relacionadas con él, incluidos el
cultivo, la siembra, el transporte y toda actividad que lo favorezca.
Desde una interpretación basada tanto en la ubicación del presente artículo en la norma como
en la doctrina penal, este tipo penal tiene como bien jurídico protegido la salud pública. Para
Azabache, estas sanciones se entienden como "derivadas de la prohibición de comercializar
determinados elementos que la ley denomina genéticamente como ‘drogas1o ‘estupefacien
tes1(...) en condiciones que comprometan la salud y la seguridad pública” (2021, p. 2). Al ser este
el bien jurídico, lo que se busca es protegerá la persona de cualquier ataque contra su integri
dad tanto física como psicológica, así como el estado normal de funcionamiento del cuerpo.
Como es bien conocido, toda actividad que vaya en contra del bien jurídico protegido será la
actividad punible. En ese sentido, para Ugaz, cualquier actividad relacionada con el proceso
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1062 of 1506 --

UBILEX
del Cannabis, siempre y cuando esta sea para fines medicinales, no es punible pues no hay
una vulneración al bien jurídico protegido (2021). Asimismo, para Prado Saldarriaga, la propia
naturaleza del delito de tráfico ilícito de drogas demanda que la acción del agente tenga fines
lucrativos (2017, pp. 165-166). Sería un completo sinsentido penar con un delito a la salud pú
blica a un sujeto que ejerce una actividad que busca, justamente, promover la salud pública200.
FORMAS AGRAVADAS (Art. 297 inciso 1 al 7 CP):
La penalidades no menor de 15 años ni mayor de veinticinco años.
No menor de ciento ochenta ni mayor de trescientos sesentay cinco días multa e inhabi
litaciones según los incisos 1 ,2 ,4 ,5 y 8 del artículo 36odel Código penal.
1. El agente comete el hecho abusando del ejercicio de la función pública.
2. El agente tiene la profesión de educador o se desempeña como tal en cualquiera de
los niveles de enseñanza.
“(...) la agravante sub examine, se funda en la deslealtad con la causa pública y la/mayorfackc
lidad y trascendencia para la difusión de drogas en el entorno del educador, estoesrlermayor
cercanía y autoridad frente a grupos de estudiantes, recalcando que es determmante>ehtítulQ:
y/o la posición funcional como educador en cualquier nivel de enseñanza. De Im q u e ^ d e s ^
prende que para configurar dicha agravante no solo se requiere que el imputado tenga~la-:€oticlk-
ción de educador, sino que su accionar delictivo se haya verificado en el contexto y aproveeham
do el ejercicio de su condición de tal, con el consiguiente grave riesgo de los alumnos sea que
no hubieran alcanzado una edad que les permita comprender las posibles consecuencias del consumo al que
pudieran ser inducidos por el comportamiento de su maestro ó que pudieran ser influidos negativamente, pese
a su mayoridad al consumo de estupefacientes". Cas. N° 126 -2 0 12 Cajamarca. Fj. 2.4. Doctrina Jurisprudencial.
3. El agente es médico, farmacéutico, químico, odontólogo o ejerce otra profesión sani
taria.
"(...) para configurar dicha agravante no solo se requiere que el imputado tenga la condición de
"profesional sanitario o de salud", sino que su accionar delictivo se haya verificado en el contexto
y aprovechando el ejercicio de su condición de tal, con las posibles consecuencias de riesgo para
la salud que trae el consumo ilegal de estupefaciente". Cas. N° 738-2014, Cajamarca. Fj. 2.2. Doctrina
jurisprudencial vinculante.
4. El hecho es cometido en el interior o en inmediaciones de un establecimiento de
