5 o 6 del artículo 2 9 7 del Código Penal".
Bien Jurídico Protegido El bien jurídico protegido en estos delitos es la salud pública, enten
dido como la suma de la salud de todos los individuos (carácter colectivo), amén de constituir
un derecho fundamental reconocido en el artículo 7 de la Constitución. La salud pública es un
derecho al que pueden acogerse todos los ciudadanos. La protección inmediata con la represión
