UBILEX
del delito de tráfico ilícito de drogas es la salud pública, en tanto que la protección mediata es
la salud individual. Lo que se quiere evitar es la generalización de un hábito insalubre entre
personas indeterminadas. Exp. N° 3 2 6 7 -2 0 2 0 -8 5 Segunda S a la S u p e rio r d e la L ib e rta d . Fj.y.
Tipicidad objetiva:
El delito de micro comercialización de drogas tipificado en el artículo 298.1 del Código Penal,
reprime la conducta consistente en que “la cantidad de droga tóxica elaborada, fabricada, ex
tractada, preparada, comercializada, entregada a terceros o poseída para usos ilegales por el
agente no sobrepase los cincuenta gramos de pasta básica de cocaína y derivados ilícitos (...)”.
La conducta sólo será típica si supone una contribución inmediata a la expansión también in
mediata del consumo ilegal de las sustancias prohibidas. En la medida en que se trata de con
ductas que han de promover, favorecer o facilitar el consumo ilegal, aquellas que no resulten
idóneas para difundir dicho consumo y, con ello, poner en peligro el bien jurídico protegido
han de considerarse atípicas. Debe tenerse presente que el inciso 1 del artículo 298 del Código
Penal, exige como tipo objetivo del delito que la posesión de droga esté destinada con fines
de micro comercialización. Exp. N° 3 2 6 7 -2 0 2 0 -8 5 S e g u n d a Sala S u p e rio r d e la L ib e rta d . Fj. 9.
El comportamiento típico del inciso tercero consiste en comercializar o distribuir pegamentos
sintéticos que expelen gases con propiedades psicoactivas, acondicionados para ser destina
dos al consumo humano por inhalación.
El últim o párrafo del artículo 298, prescribe que la pena se agrava si concurre alguna de las
agravantes del artículo 297 del CP
Con fe c h a n d e diciembre de 2023 a través del Decreto Legislativo N°i592 se modificó el artí
culo en comentario, con anterioridad el encabezado de este artículo era "Microcomercialización
o microproducción”, ahora es reemplazado por''Tormas atenuadas de elaboración, comercializa
ción y posesión". Asimismo, se penará la droga tóxica elaborada, entregada a terceros o poseída para
usos ilegales, antes no se incluían ninguno de estos términos.
Tipicidad Subjetiva. Es el dolo. La conducta se realiza con conocimiento y voluntad en la co
misión de los elementos del tipo objetivo y con la especial intención de utilizar estas sustan
cias para su tráfico ilícito.
Sujeto activo. Puede ser cualquier persona.
Sujeto pasivo. La colectividad.
Irrelevancia de los actos de consum o personal de drogas
Según el artículo 299o, la posesión de drogas tóxicas no es punible, siempre que se encuentre
destinada al propio e inmediato consumo, en cantidad que no exceda de cinco gramos de pas
ta básica de cocaína, dos gramos de clorhidrato de cocaína, ocho gramos de marihuana o dos
gramos de sus derivados, un gramo de látex de opio o doscientos miligramos desús derivados
o doscientos cincuenta miligramos de éxtasis, conteniendo Metilendioxianfetamina - MDA,
Metilendioxim etanfetamina- MDMA, Metanfetamina o sustancias análogas.
Se excluye de los alcances de lo establecido en el párrafo precedente la posesión de dos o más tipos
de drogas tóxicas, sean estupefacientes, sustancias psicotrópicas o nuevas sustancias psicoactivas.
