Tema 6: Temas de la Especialidad Penal
Tampoco será punible la posesión del cannabis y sus derivados con fines medicinales y tera
péuticos, siempre que la cantidad sea la necesaria para el tratamiento del paciente registrado
en el Ministerio de Salud, supervisado porel Instituto Nacional de Saludy la DIGEMID, o de un
