De aquí le sigue delitos informativos:
2 0 . D E L IT O S IN F O R M Á T IC O S
Dannecker concibe el delito informativo como aquella forma de criminalidad que se encuentra
directa o indirectamente en relación con el procesamiento electrónico de datos y se comete
con la presencia de un equipo de procesamiento electrónico de datos.
Por nuestra parte, entendemos a la criminalidad informática como aquellas conductas d iri
gidas a burlar los sistemas de dispositivos de seguridad, esto es invasiones a computadoras,
correos o sistemas de datas mediante una clave de acceso; conductas típicas que únicamente
pueden ser cometidos a través de la tecnología. En un sentido amplio, comprende a todas
aquellas conductas en las que las TIC son el objetivo, el medio o el lugar de ejecución, aunque
afecten a bienes jurídicos diversos y que plantea problemas criminológicos y penales, origina
dos por las características propias del lugar de comisión.
1. Descripción normativa:
“LEY N° 300 9 6 - LEY DE DELITOS INFORMÁTICOS
(...) DELITOS CONTRA DATOS Y SISTEMAS INFORMÁTICOS
Artículo Accszc ¡licite
El que deliberada e ilegítimamente accede a todo o en parte de un sistema informático, o se
excede en lo autorizado, será reprimido con pena privativa de libertad no menor de uno ni mayor
de cuatro años y con treinta a noventa días-multa.
Si el agente accede deliberada e ilegítimamente, en todo o en parte, al sistema informático vulnerando las
medidas de seguridad establecidas para impedirlo, será reprimido con pena privativa de libertad no menor de
tres ni mayor de seis años y con ochenta a ciento veinte días-multa.
Artículo 3. .lis/Jíatto a la integridad de datos imortnéiims
El que deliberada e ilegítimamente daña, introduce, borra, deteriora, altera, suprime o hace inaccesibles datos
informáticos, será reprimido con pena privativa de libertad no menor de tres ni mayor de seis años y con
ochenta a ciento veinte días-multa.
Artículo 4. Atentado a la integridad ds sistemas informáticos
El que deliberada e ilegítimamente inutiliza, total o parcialmente, un sistema informático, impide el acceso a
este, entorpece o imposibilita su funcionamiento o la prestación de sus servicios, será reprimido con pena
privativa de libertad no menor de tres ni mayor de seis años y con ochenta a ciento veinte días-multa.”
DELITOS INFORMÁTICOS CONTRA LA IN D E M N ID A D Y LIBERTAD SEXUALES
Artículo 5. Proposkioms a niños, niñas y adolescentes con fines saimaies por medhs tecnológicos
El que a través de internet u otro medio análogo contacta con un menor de catorce años para solicitar u ob
tener de él material pornográfico, o para proponerle llevar a cabo cualquier acto de connotación sexual con
él o con tercero, será reprimido con una pena privativa de libertad no menor de seis ni mayor de nueve años.
Cuando la víctima tiene entre catorce y menos de dieciocho años de edad y medie engaño, la pena será no
menor de tres ni mayor de seis años.
En todos los casos se impone, además, la pena de inhabilitación conforme a los numerales 1,2,3, 4, 5, 6,8, 9,
10 y 11 del artículo 36 del Código Penal.
