DELITOS INFORMÁTICOS CONTRA EL PATRIM ONIO
A rtíc u lo 8 . Fraude info rm ático
El que deliberada é ilegítimamente procura para sí o para otro un provecho ilícito en perjuicio de tercero me
diante el diseño, introducción, alteración, borrado, supresión, clonación de datos informáticos, sup lantación d e
in te rface s o p á g in a s w eb o cualquier interferencia o manipulación en el funcionamiento de un sistema inform áti
co, será reprimido con una pena privativa de libertad no menor de cuatro ni mayor de ocho años y con sesenta
a ciento veinte días-multa. •
La pena será privativa de libertad no menor de cinco ni mayor de diez años y de ochenta a ciento cuarenta
días multa cuando se afecte el patrimonio del Estado destinado a fines asistenciales o a programas de apoyo
social.
La misma pena se aplica al que ¡ntencíonalmente colabora con la comisión de alguno de los supuestos de los
párrafos precedentes, facilitándo la transferencia de activos.
DELITOS INFO RM ÁTICOS CONTRA LA FE PÚBLICA
A rtíc ulo 9. Suplantación d e identid ad
El que, mediante las tecnologías digitales suplanta la identidad de una persona natural o jurídica, siempre que
de dicha conducta resulte algún perjuicio, material, moral o de cualquier otra índole, será reprimido con pena -
privativa de libertad no menor de tres ni mayor de cinco años.
La pena privativa de libertad es no menor de seis ni mayor de nueve años cuando se suplante la identidad de
una persona menor de 18 años de edad y resulte algún perjuicio, material, moral o de cualquier otra índole.
DIS P O S IC IO N E S CO M UNES
A rtíc u lo 10. Abuso de mecanismos y dispositivo s in fo rm á tic o s
El que deliberada e ¡legítimamente fabrica, diseña, desarrolla, vende, facilita, distribuye, importa u obtiene para
su utilización, uno o más mecanismos, programas informáticos, dispositivos, contraseñas, códigos de acceso
o cualquier otro dato informático, específicamente diseñados para la comisión de los delitos previstos en la
presente Ley, o el que ofrece o presta servicio que contribuya a ese propósito, será reprimido con pena privativa
de libertad no menor de uno ni mayor de cuatro años y con treinta a noventa días-multa.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1067 of 1506 --

Tema 6: Temas de la Especialidad Penal
Artículo I I . Agravantes
El juez aumenta la pena privativa de libertad hasta en un tercio por encima del máximo legal fijado para cual
quiera de los delitos previstos en la presente Ley cuando:
1. El agente comete el delito en calidad de integrante de una organización criminal.
2. El agente comete el delito mediante el abuso de una posición especial de acceso a la data o información:
reservada o al conocimiento de esta información en razón del ejercicio de un cargo o función.
3. El agente comete el delito con el fin de obtener un beneficio económico, salvo en los delitos que prevén dicha
circunstancia.
4. El delito compromete fines asistenciales, la defensa, la seguridad y la soberanía nacionales.
Artículo 12, Exención de responsabilidad penal
Está exento de responsabilidad penal el que realiza las conductas descritas en los artículos 2,3, 4 y 10 con
el propósito de llevara cabo pruebas autorizadas u otros procedimientos autorizados destinados a proteger
sistemas inform áticos,”
B ien ju ríd ic o tu te la d o : El bien jurídico tutelado en los delitos informáticos se concibe en dos
planos de manera conjunta y concatenada; en el primero, se encuentra la “información” de
manera general (información almacenada, tratada y transm itida mediante los sistemas de
tratamiento automatizado de datos); y en el segundo, los demás bienes afectados a través de
este tipo de delitos como son la indemnidad sexual, intimidad, etc.
Respecto de la información, debe ser entendida como el contenido de las bases y/o banco de
datas o el producto de los procesos informáticos automatizados; por lo tanto, se constituye en
un bien autónomo de valor económico y es la importancia del “valor económico" de la infor
mación lo que ha hecho que se incorpore como bien jurídico tutelado.
Sin embargo, creemos que la información se debe considerar de diferentes formas, y no solo
como un valor económico, sino como un valor intrínseco de la persona por la fluidez y el trá fi
co jurídico, y por los sistemas que lo procesan o automatizan los mismos que equiparan a los
bienes protegidos tradicionales tales como el patrimonio (fraude informático), la reserva, la
¡ntim idady confidencialidad de los datos (agresiones informáticas a la esfera de la Intimidad),
seguridad o fiabilidad del tráfico jurídico probatorio (falsificación de datos o documentos pro
batorios), etc.
Por tanto, en este tipo de delitos no se puede establecer a la información como el único bien
jurídico afectado, por ser el principal y el más importante; sino a un conjunto de bienes que
son afectados, debido a la característica de la conducta típica en esta modalidad delictiva que
colisiona con diversos intereses colectivos. Es en ese sentido, es un delito pluriofensivo, sin per
juicio que uno de tales bienes esté independientemente tutelado por otro tipo penal.
Tip o s p en ales:
a) D e lito s co ntra los d ato s y siste m a s in fo rm á tico s (artícu lo s 2 o, 3oy 4 o):
i) A cceso ilícito : Esta figura sanciona la violación de la confidencialidad, que se realiza
a través del acceso no autorizado al sistema, vulnerando las medidas de seguridad
establecida para evitarque ajenos ingresen a un sistema informático; el verbo rector
“acceder" se entiende el hecho de entrar en un lugar o pasara él, que en esta figura se
entiende el acto de entrar sin autorización del titu la ra un sistema, y el térm ino “vul
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1068 of 1506 --

nerar” se entiende como "transgredir, quebrantar, violar una ley o precepto” que se
entiende al hecho de trasgredir las barreras de protección diseñados por el sistema.
Por la característica que presenta este tipo penal se le puede calificar como un delito
de mera actividad, porque esta figura exige el acto de acceder (entrar en un lugar o
pasar a él) sin autorización a un sistema informático, vulnerar (transgredir, quebran
tar, violar una ley o precepto) las medidas de seguridad, de esta manera se configura
el ilícito; por tanto el delito queda consumado en el momento que se vulnera las
medidas de seguridad establecida para impedir el acceso ilícito, y para ellos es ne
cesario que se realice esta conducta con dolo. Por ejemplo, el acceso a la cuenta de
correo electrónico ajeno protegido mediante una contraseña de seguridad, el acceso
no autorizado al sistema informático de una entidad aprovechando las debilidades
inadvertidas por la programación.
La fuente legal de este artículo es el Convenio de Budapest, porque cumple con des
cribir la acción delictiva en los mismos términos estandarizados de la norma interna
cional, por mencionar los términos "deliberación”, “falta de legitimación” de la acción
contenida en el texto del Convenio de Budapest guarda cierta identidad con el dolo
(conocimiento y voluntad).
Con fecha 21 de diciembre de 2023 el artículo 2) fue objeto de dos modificaciones a
través del Decreto Legislativo N °i6i4,en la primera reforma, se agrega un enunciado
en el primer párrafo, el mismo que citamos a continuación: o excede en lo autori
zado". En virtud de la modificación introducida al artículo en comentario no sólo es
punible el acceso ilícito a un sistema informático sin autorización, ahora también se
castiga si alguien autorizado m an ip u la d sistema informático para si o a favor de un
tercero, por tanto, ir más allá de lo autorizado sí acarrearía una responsabilidad pe
nal. En la segunda reforma, se agrega un segundo párrafo al artículo 2, el cual prevé
una forma agravada al tipo básico. Para que se cumpla dicho supuesto, al momento
de tener el acceso ilícito se debe, “...vulnera [r] las medidas de segundad establecidas para
impedirlo”.
Atentado a la integridad de los datos informáticos: Esta figura penal sanciona la
conducta de dañar (causar detrimento, perjuicio, menoscabo), introducir (entrar en
un lugar), borrar (desvanecer, quitar, hacerque desaparezca algo) deteriorar (empeo
rar, degenerar), alterar (estropear, dañar, descomponer), suprimir (hacer cesar, hacer
desaparecer) y hacer inaccesible los datos informáticos a través de la utilización de
las TIC; por la característica que presenta este tipo penal es clasificado como un de
lito de mera actividad, porque esta figura exige el solo cumplim iento del tipo penal,
la sola realización de la conducta de introducir, borrar, deteriorar, alterar, suprim iry
hacer inaccesible los datos informáticos para que se pueda configurar el ilícito, sin
im portar el resultado posterior, por tanto el delito queda consumado al realizarse
cualquiera de estos actos.
Este artículo es compatible parcialmente con el Art. 40 del Convenio de Budapest que
sanciona el atentado contra la integridady la disponibilidad del dato informático.
Atentado a la integridad del sistema informático: Esta figura penal sanciona las
conductas que están dirigidas a inutilizar (hacer inútil, vano o nulo algo) total o par
