to o la prestación de sus servicios utilizando las TIC; por la característica que presenta
este tipo penal se clasifica como un delito de resultado, porque para la configuración
de este injusto penal no basta con cumplir el tipo que es (inutilizar o perturbar), sino
además es necesario que la acción vaya seguida de un resultado (impedir el acceso,
im posibilitar su funcionamiento, o la prestación de sus servicios), por tanto el delito
se consuma cuando se impide el acceso, imposibilita su funcionamiento, etc., del sis
tema informático, caso contrario el hecho solo dará lugar a la tentativa.
Este artículo guarda cierta relación de compatibilidad con el Art. 50 del Convenio de
Budapest en tanto se puede entender la “obstacul¡zación grave” de un sistema infor
mático con el de la “inutilización total o parcial" del sistema.
Son ejemplos de esta figura penal los siguientes delitos:
Delito de daño: comportamiento consistente en dañar, destruir o inutilizar un bien,
en este caso es el sistema informático. El delito de daños existirá si usuarios, carentes
de autorización, alteran o destruyen archivos o bancos de datos a propósito; la des
trucción total de programas y de datos ponen en peligro la estabilidad económica
de una empresa. El modus operandi se viene perfeccionando con el tiempo: virus,
cáncer rotudtine. Estos actos deben causar un perjuicio patrimonial.
El sabotaje informático: consiste, básicamente, en borrar, suprimir o modificar (al
terar) sin autorización funciones o datos de las computadoras con intención de obs
taculizar el funcionamiento normal del sistema, que se conoce comúnmente como
"virus informático”. En efecto, sabotaje informático es la conducta que consiste en la
destrucción o en la producción generalizada de daños.
Las t é c n ic a s q u e p e r m it e n c o m e t e r s a b o t a je in f o r m á t ic o so n la s s ig u ie n t e s :
• Bomba lógica: introducción de un programa de un conjunto de instrucciones in
debidas que van a actuar en determinada fecha, destruyendo datos del ordena
dor, distorsionando el funcionamiento del sistema o paralizando el mismo.
• Rutinas cáncer: son distorsiones al funcionamiento del programa, la caracterís
tica es la auto reproducción.
• Gusanos: se infiltran en los programas ya sea para modificar o destruir los datos,
pero a diferencia de los virus estos no pueden regenerarse.
• Virus informático y malware: elementos informáticos que destruyen el uso de
ciertos antivirus. Por ejemplo, borrar los antecedentes policiales, judiciales y pe
nales de una persona; alterar la deuda real de un cliente; cambiar la clave secreta
o elim inar la cuenta electrónica (correo, twitter, Facebook) para impedí ral titu la r
el acceso a su cuenta.
b) Delitos informáticos contra la indemnidady libertad sexual (artículos 5° 5-A).
(Art. 5) El tipo penal sanciona el contacto (establecer contacto o comunicación con al
guien) realizado con un menor de edad con fines a obtener materiales pornográficos o
para proponerle llevar a cabo actividades sexuales que involucren el quebrantamiento de
la indemnidad o libertad sexual del menor (violación sexual o actos contra el pudor); en
este artículo hay dos supuestos:
