Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1070 of 1506 --

UBILEX
i) El primer supuesto es el contacto con un menor de catorce años para solicitar, obte
ner material pornográfico o para realizar actos sexuales, cuya pena es de 6 a 9 años
de pena privativa de libertad e inhabilitación.
¡i) El segundo supuesto es el contacto con un menor que tiene entre 14 y 18 años para
solicitar, obtener material pornográfico o para proponerle realizar actos sexuales,
cuya pena es de 3 a 6 años de pena privativa de libertad e inhabilitación.
Este tipo sanciona el acto de contactar que significa “establecer contacto o comunicación
con alguien",y el término “para” es un elemento subjetivo que determina la Intención del
sujeto activo y es este elemento que convierte a la figura penal en un tipo de tendencia
interna trascendente (delitos de intención), porque este ilícito “parte Interna” requiere de
una intención especial, que no corresponde a la parte externa objetiva que en este caso
es obtener material pornográfico y/o tener actividades sexuales con el menor; por consi
guiente, el tipo legal queda consumado cuando se produce el resultado típico, no siendo
necesario que el agente consiga realizar su especifica tendencia trascendente, por estas
características se clasifica a esta figura como un delito de resultado cortado, porque en
este ilícito el agente persigue un resultado que está más allá del tip o y que ha de produ
cirse por sí solo, sin su intervención y con posterioridad.
En esta figura penal el legislador adelanta las barreras de punibilidad al sancionar el solo
hecho de contactar con el menor de edad, sin importar si logra su objetivo el cual es obtener
material pornográfico o llegar a tener actividad sexual, sin embargo este artículo tiene mu
chas falencias que podría violar el principio de legalidad, al no tener una redacción clara,y a
consecuencia de este errarse podría sancionar a personas que solo contactan con un menor
de edad sin tener la finalidad de obtener material pornográfico y otro similar porque el tér
mino contactar no está delimitado, por consiguiente se estaría sancionando el solo hecho
de establecer un “contacto” o comunicación con un menor de edad.
(Art. 5-A). El artículo 5-A fue incorporado a la Ley de Delitos Informáticos a través del D. Leg.
1625 del 08 agosto de 2024, este decreto agrega el delito de chantaje sexual mediante el uso
de tecnologías digitales. Este delito sanciona a quienes, a través de amenazas o intimidacio
nes, intenten obtener una conducta o acto de connotación sexual de la víctima, utilizando
la difusión de imágenes o audios íntimos como mecanismo de presión. Las penas para este
tipo de chantaje varían entre 02 a 04 años de pena privativa de libertad e inhabilitación.
Este tipo penal admite las modalidades agravadas cuando concurran las siguientes circuns
tancias: 1. La amenaza a la víctima se refiere a la difusión de imágenes, materiales audio
visuales o audios con contenido sexual en los que esta aparece o participa. 2. Cuando la
víctima mantenga o haya mantenido una relación de pareja con el agente, son o han sido
convivientes o cónyuges. En estos casos la pena privativa de libertad será no menor de 03 ni
mayor de 05 años e inhabilitación.
c) Delitos informáticos contra la intimidad y el secreto de las comunicaciones (artículo 7°).-
La figura penal sanciona la conducta que deliberada e ilegítimamente intercepta (inte
rrumpe, obstruye una vía de comunicación) datos informáticos y las emisiones electro
magnéticas que transportan estos datos en las transmisiones privadas.
Este artículo contiene tres agravantes:
