Este injusto penal -interceptar datos informáticos-es un delito de peligro abstracto y por
ende, solo basta con demostrarla interceptación de datos informáticos para que el delito
quede consumado. Por ende, se clasifica como un delito de mera actividad porque basta
con el sólo hecho de interceptar datos informáticos para que se consuma el delito. Por
ejemplo, interceptación de archivos que contengan información relacionado con una in
vestigación reservada por ley, interceptación de comunicaciones que contenga informa
ción sensible que puede ser utilizado por algún país en un contexto bélico,
d) Delito informático contra el patrimonio-fraude informático (inciso 8).-
Este injusto penal sanciona diversas conductas, entre ellos: diseñar (proyecto o plan), in
troducir (entrar en un lugar), alterar (estropear, dañar, descomponer), borrar (desvane
cer, quitar, hacer que desaparezca algo), suprimir (hacer cesar, hacer desaparecer), clonar
(producir clones) datos informáticos o cualquier interferencia, o manipular (operar con
las manos o con cualquier instrumento) el funcionamiento de un sistema informático
procurando (conseguir o adquirir algo) un beneficio para sí o para otro en perjuicio de
tercero; y por la forma como está estructurado-a propósito de la mala redacción que ge
nera mucha confusión al momento de interpretar la figura, y las conductas inadecuadas
como “diseñar, introducir, alterar, borrary suprimir" que no encajan en el delito de fraude
informático, estas conductas son propios del delito de daño- se clasifica como un delito
de resultado porque no basta cumplir con el tipo penal para que se consume el delito
de fraude informático, sino que además, es necesario que esa acción vaya seguida de un
resultado separado de la misma conducta el que consiste en causar un perjuicio a terce
ro, de otro modo el delito quedaría en tentativa. Por ejemplo, clonar tarjetas bancarias,
el fraude informático afecta los programas sociales JUNTOS, PENSIÓN 65, destinados a
apoyo social.
Este artículo es compatible con el Art. 8 del Convenio de Budapest, porque ambos artícu
los sancionan el empleo indebido de datos informáticos, la manipulación del funciona
miento del sistema mismo.
Con fecha 21 de diciembre de 2023 el artículo 8) de la Ley de Delitos Informáticos fue ob
jeto de dos modificaciones a través del Decreto Legislativo N ° i6i 4 , en la primera reforma,
se agrega un enunciado en el primer párrafo, el mismo que citamos a continuación:
suplantación de interfaces o páginas web”. En este apartado se sanciona el perjuicio gene
rado a un tercero, donde este tercero debe tener viciada su voluntad y que además de
dicho evento se genere un beneficio para sí o para otros. La segunda reforma agrega un
