e) Delito informático contra la fe publica-suplantación de identidad (artículo 9o).-
Estetipo penal sancionael hecho sesuplantar(ocuparcon malasartesel lugar de alguien,
defraudándole el derecho, empleo o favor que disfrutaba) la identidad de una persona
natural o jurídica causando algún perjuicio.
La suplantación de identidad se puede calificar como un delito de resultado porque no
ba5ta con realizar la conducta típica de "suplantar” la identidad, sino que además es ne
cesario que esa acción vaya seguida de un resultado separado de la misma conducta que
consiste en causar un perjuicio, caso contrario quedaría en tentativa. Por ejemplo, crear
perfiles falsos en las redes sociales (correo electrónico, Facebook, tw itter) atribuidos a
personas naturales y/o jurídicas para engañary perjudicar a terceros.
A través del Decreto Legislativo N°1591 publicado el 13 de diciembre de 2023, se modifica
el artículo en comentario, confirmando los supuestos ya regulados en la normativa an
terior, además de variar el término utilizado en el texto anterior a la reforma el cual era
“tecnologíasde la información”, optándose en la nueva regulación por un térm ino más espe
cífico, esto es, “tecnologíasdigitales”. Asimismo, se incorpora una agravante que incrementa
la pena privativa de libertad de 6 a 8 años para casos donde se suplante la identidad de
una persona menor de 18 años y resulte algún perjuicio, material, moral o de cualquier
otra índole.
f) Disposiciones comunes (artículos 10o, n °y 12o).-
i) Delito de abuso de mecanismos y dispositivos informáticos:
Se sanciona diversas conductas, entre ellas: fabricar (producir objetos en serie, ge
neralmente por medios mecánicos), diseñar (hacer un diseño), desarrollar, vender
(traspasara alguien por el precio convenido la propiedad de lo que uno posee), faci
litar (proporcionar o entregar), distribuir (entregar una mercancía a los vendedores
y consumidores), importa (dicho de una mercancía: valer o llegar a cierta cantidad)
y obtener (alcanzar, conseguiry lograr algo que se merece, solicita o pretende), para
la utilización de mecanismos, programas informáticos, contraseñas, etc., diseñados
específicamente para la comisión de los delitos previstos en esta ley.
Este artículo es una expresión del adelantamiento de las barreras punitivas porque
se sanciona la participación y más aún el sólo hecho de ofrecer un servicio que facili
te la comisión de algún delito previsto en la presente ley.
Este tipo penal se clasifica como un delito de mera actividad, porque la figura exige
cumplir con la conducta mencionado en el tipo penal para la consumación del de
lito sin importar el resultado posterior. Aquí el legislador adelanta las barreras de
punibilidad al sancionar el solo hecho de fabricar, diseñar, vender, etc., mecanismos,
programas orientados a cometer diversos delitos previstos en la ley.
Esta figura penal poseería las características del llamado derecho penal del enemigo
porque se sanciona actos preparatorios alegando la puesta en peligro de la seguri
dad informática. Por ejemplo, tráfico de datos de usuarios y contraseñas obtenidas
