dos en capturar, interceptar información.
Este artículo es compatible con el art. 6 o de la Convención de Budapest, sin embargo
hay una interpretación muy amplia, un vacío de este artículo por cuanto se extiende
a toda gama de delitos previstos en la presente ley y que podría generar problemas
en la interpretación judicial, debido a la extensión de ilícitos como: interferencia te
