ii) Circunstancias agravantes de los delitos informáticos:
Se regulan las agravantes de los delitos previstos en la presente ley,y en base a esta
norma el juez puede aumentar la pena hasta en un tercio por encima del máximo
legal fijado; por ejemplo, participación de integrantes de la organización criminal en
la comisión de delitos informáticos, el acceso ilícito a la cuenta de correo electrónico
a cambio de un pago (los hackers de un centro comercial).
iii) Exención de responsabilidad penal en los delitos contra los datos y sistemas in
formáticos, y el delito de abuso de mecanismosy dispositivos informáticos:
Este artículo incorporado por el Art. 3o de la Ley N° 30171 "Ley que modifica la Ley N°
30096, Ley de Delitos Informáticos”, exime de responsabilidad penal a toda perso
na que realiza alguna de las conductas reguladas en los artículos 2o, 30, 4°y 10o de
la presente Ley. Esta cláusula de exención de responsabilidad se fundamenta en la
conducta legal -au torizad a por la autoridad correspondiente- para realizar pruebas
u otro procedimiento con el objetivo de protege ríos sistemas y datos informáticos.
21. DELITOS CONTRA LA PROPIEDAD INTELECTUAL E INDUSTRIAL
1. Delito contra los derechos de autor y conexos
Bien jurídico protegido: El bien jurídico protegido en las figuras penales ahora analizadas es
el derecho de autory, en algunos casos, los derechos conexos. La protección penal se encamina
a perseguir aquel los comportamientos que supongan una vulneración tanto de las facultades
morales como patrimoniales, con cierta preeminencia de estas últimas. En efecto, si bien se
reprimen conductas que suponen la afectación de derechos morales tales como el derecho
a la paternidad, a la integridad y a la no divulgación de la obra, lo cierto es que buena parte
de los comportamientos delictivos -con más razón desde la entrada en vigor de la Ley 29263
que incorpora nuevas figuras típicas-tienen que ver con actos de comunicación, distribución,
reproducción e importación atentatorios contra las facultades patrimoniales de los derechos
de autory conexos.
Los derechos patrimoniales reconocidos al autor están preordenados a garantizarle el disfrute
de los beneficios económicos obtenidos por la explotación de su obra. Parece claro que algu
nos países-principalmente Estados Unidos-se muestran más sensibles a las infracciones a los
derechos patrimoniales de a uto ry derechos conexos que a ilícitos que inciden en el aspecto
moral. Aquéllos son los que generan mayor preocupación en los países que han alcanzado
un gran desarrollo de sus industrias fonográfica, audiovisual, satelital y del software. Estamos
ante intangibles que generan grandes ganancias.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1074 of 1506 --

UBILEX
■ Debe tenerse en cuenta que entre los derechos de autor (que atiende en sentido estricto a los
creadores) y los derechos conexos (esto es, de los intérpretes o ejecutantes; de los productores
de fonograma, y de los organismos de radiodifusión) se pueden establecer vasos comunican
tes: "Lo que se observa sin mayor esfuerzo es que las obras de los autores son el Insumo o la m ateria prima
de la cual se valen los titulares de los denominados derechos conexos o vecinos,y a su vez los autores en
cuentran en los titulares de derechos conexos sus mejores aliados en la Iaborde dar a conocery de difusión
de sus creaciones, lo cual crea una especie de m atrim onio por conveniencia entre unosy otros."
Cabe mencionar que el derecho de autortiene reconocimiento constitucional. El art. z inc 8 de
nuestra carta fundamental señala que toda persona tiene derecho a “la libertad de creación
intelectual, artística, técnica y científica, así como a la propiedad sobre dichas creaciones y a su
producto. El Estado propiciad acceso a la culturay fomenta su desarrolloy difusión”.23 Cierto
es que, a diferencia de la Constitución de 1979, ya no se hace referencia expresa al derecho
de autor, pero eso no significa que este derecho haya perdido reconocimiento constitucional,
pues el mismo queda comprendido dentro del art. 2 inc. 8 de la Constitución de 1993 que alude
a la libertad de creación intelectual y a la propiedad sobre dicha creación. Y es que una obra no
es otra cosa que una creación intelectual, un producto del ingenio humano. Con lo cual, cuan
do la Constitución reconoce el derecho a la libertad de creación intelectual y a la propiedad
sobre dicha creación, está reconociendo implícitamente el derecho de autor.
2. Tipos penales
a) Delito de copia o reproducción no autorizada
Descripción norm ativa:
“Art. 21S CP Será reprimido con pena privativa de la libertad no menor de dos ni mayor de cuatro años
v x í V d e d ie z a sesenta días-multa, a quien estando autorizado para publicar una obra, lo hiciere en una
W M J de las formas siguientes:
: : a. Sin mencionar en los ejemplares el nombre del autor, traductor, adaptador, compilador o arreglador,
b. Estampe el nombre con adiciones o supresiones que afecte la reputación del autor como tal, o en su caso,
del traductor, adaptador, compilador o arreglador.
c. Publique la obra con abreviaturas, adiciones, supresiones, o cualquier otra modificación, sin el consenti
miento del titular del derecho,
d. Publique separadamente varias obras, cuando la autorización se haya conferido para publicarlas en con
junto; o las publique en conjunto, cuando solamente se le haya autorizado la publicación de ellas en forma
separada."
Tipicidad objetiva: En el artículo en análisis se aglomeran una serie de actos materiales con-
figuradores de ilícito, cuya característica esencial es que el sujeto activo 256 cuenta con auto
rización del autor de la obra protegida y que el comportamiento constituye un exceso de sus
atribuciones, estos actos son:
i) O m itir consignar el nombre del autor, traductor, adaptador, com pilador o arreglador.
El autor o sus derecho habientes sólo pueden ceder a otra persona, que la norma deno-
m in a “editor”, mediante contrato de cesión el derecho de publicar, distribuir y divulgar la
