obra protegida, en este caso el editor se encuentra obligado a indicar en cada ejemplar el
nombre o seudónimo del autor, traductor, compilador, adaptador, o arreglador.
Por otra parte, se deja fuera de la tutela de protección del Derecho Penal al autor que
actúa bajo seudónimo, lo que constituye un vacío legislativo, estimamos de lege ferenda
debe llenarse dicho vacío, toda vez que el seudónimo cumple, para el autor que usa, la
misma función que desempeña el nombre, en función que logra que se vincule a su crea
ción intelectual (derecho de paternidad). Debe distinguirse entre el supuesto aquí ana
lizado con el delito de plagio, previsto en el art. 219 del Código, en tanto que este últim o
exige que el sujeto activo se sustituya en la condición de autor.
ii) Estam pe el nombre con adiciones o supresiones que afecte la reputación del autor
como tal, o en su caso, del traductor, adaptador, com pilador o arreglador.
iii) Publique la obra con abreviaturas, adiciones, supresiones, o cualquier otra m odifica
ción, sin el consentim iento del titu lar del derecho. La conducta que va dirigida contra
la integridad de la obra, de allí que se exija que las modificaciones de la obra resulten
sustanciales, por ello es que las modificaciones de orden no trascendentales, como las
correcciones ortográficas, no resulten punibles.
Publicar, según lo establece la Ley de Derechos de Autor consiste en la: “Producción de ejem
plares puestos al alcance del público con el consentimiento del titu la r del respectivo derecho, siempre
que la disponibilidad de tales ejemplares permita satisfacer las necesidades razonables del público
teniendo en cuenta la naturaleza de la obra”. En este entendido, no serán punibles los estadios
previos, es decir, lasóla modificación de la obra, sin contar con el consentimiento del titu
lar del derecho intelectual. El consentimiento del titu lar excluye el tipo, no se exige en el
consentimiento ningún tipo de formalidad.
iv) Publique separadam ente varias obras, cuando la autorización se haya conferido para
publicarlas en conjunto; o las publique en conjunto, cuando solam ente se le haya au
torizado la publicación de ellas en form a separada. Se hace extensivas las anotaciones
pertinentes del anterior párrafo, en este específico caso no se afecta en mayor medida la
integridad de obra sino principalmente las cuestiones relativas al derecho de explotación.
El sujeto pasivo en este caso será cualquier persona natural titu lar del derecho de autor,
sea como autor, traductor, compilador o arreglador de una obra protegida.
Tipicidad subjetiva: El tipo penal exige que la conducta sea dolosa.
