d. Reproduzca total o parcialmente una película, por cualquier medio o procedimiento, dentro de las salas de
cine o análogos,
e. La reproduzca, distribuya o comunique, en mayor número que el autorizado por escrito.
La pena será no menor de cuatro años ni mayor de ocho y con sesenta a ciento veinte días multa, cuando el
agente la reproduzca total o parcialmente, por cualquier medio o procedimiento y si la distribución se realiza
mediante venta, alquiler o préstamo al público u otra forma de transferencia de la posesión del soporte que
contiene la obra o producción que supere las dos (2) Unidades Impositivas Tributarias, en forma fraccionada,
en un solo acto o en diferentes actos de inferior importe cada uno."
Tipicidad objetiva: El tipo penal establece también un catálogo de conductas delictivas, sin
embargo, a diferencia del precepto antes analizado, detalla los objetos de tutela en sede pe
nal; así son protegidas las obras, las interpretaciones, las ejecuciones artísticas, los fonogra
mas, las emisiones de radiodifusión, las transmisiones de radio.
La modificación consiste en alterar la sustancia de la obra protegida, no es indispensable que
esta haya alterado la totalidad de aquella, se exige sólo la alteración parcial, surge aquí una
interrogante relacionada a los límites mínimos requeridos para hablar de modificación; por
ejemplo, si el editor se lim ita a corregir errores ortográficos contenidos en una obra.
Debe entenderse como reproducción la fijación de la obra o producción intelectual en un so
porte o medio que permita su comunicación, incluyendo su almacenamiento electrónico,y la
obtención de copias de todo o parte de ella. En este supuesto, no se exige perjuicio alguno al
autor ni que las copias hayan sido puestas al alcance. Resultaba innecesario, según se entien
de, detallar las formas en que dicha distribución se puede realizar, el propio concepto de dis
tribución permite comprenderá la venta, alquiler, o préstamo público, si además que produce
una laguna de punibilidad, al no comprenderse, por ejemplo, la distribución a título gratuito
de la obra. Una interpretación restrictiva del tipo, destinada a evitar la intervención del siste
ma penal a casos de bagatela, exige que la distribución haya sido hecha a más de una persona,
de lo contrario la venta, alquiler o préstamo no se considera como pública.
El comportamiento consistente en el acceso de una o más personas, distintas al autor, reuni
das o en diferente lugar, a la obra, sin que ésta haya sido aún distribuida.
Con relación a los medios, estos pueden ser de cualquier naturaleza (análogo o digital, co
nocido o por conocerse), siempre que pueda difundir los signos, palabras, sonidos o imáge
nes (a más de una persona, conforme al carácter “publico” de la "comunicación o “difusión”). La
comunicación pública puede producirse, conforme lo dispuesto por la legislación autoral, de
manera diferenciada según el tipo de obra.
Con fecha 13 de setiembre de 2024 se publicó el Decreto Legislativo 1649, cuya finalidad es
complementar las disposiciones en materia penal relacionadas con la reproducción no auto
rizada de películas dentro de las salas de cine o análogos. Este dispositivo legal modifico el ar
tículo 217 CP para mejorar la normativa penal y sancionar con mayor eficacia la reproducción
no autorizada de películas en salas de cine. En estos casos, la pena será entre 04 a 08 años pena
privativa de libertad, y con 60 a 120 días multa. Esta sanción se aplica cuando la distribución
