c) Delito de plagio
Descripción normativa:
“Art. 279 CR Será reprimido con pena privativa de libertad no menor de cuatro ni mayor de ocho años y
noventa a ciento ochenta días multa, el que con respecto a una obra, la difunda como propia, en todo
o en parte, copiándola o reproduciéndola textualmente, o tratando de disimular la copia mediante
ciertas alteraciones, atribuyéndose o atribuyendo a otro, la autoría o titularidad ajena."
Tipicidad objetiva: En el plagióse vulnera de lleno el derecho moral de paternidad de la obra,
pues se pretende pasar como propia una creación ajena.
Esto implica actos de reproducción o cuasi reproducción de la obra (copia servil) o actos en los
que se busca disimular el plagio incorporando ciertas alteraciones (copia inteligente). Si las
