i. Sólo al titu lar de un derecho de autor o conexo corresponde el derecho de realizar, auto
rizar o prohibir actos de comunicación, reproducción o distribución de una obra, inter
pretación, producción, emisión u otro bien susceptible de protección por la Ley sobre el
