de lucro legalmente constituidas para dedicarse, en nombre propio o ajeno, a la gestión
de derechos de autor o conexos, sobre todo derechos de carácter patrimonial. Para ello
deben contar con la autorización de laO ficinade Derechos deAutordel INDECOPI.
