UBILEX
En este sentido, aquel que conceda autorizaciones para la explotación de las obras, o fije y
recaude la remuneración correspondiente a dicha explotación incurrirá en este delito en
su forma agravada si es que no cuenta con la debida autorización. Si bien es verdad que
la distribución -a los titulares de un derecho de autor o conexo- de las remuneraciones
recaudadas constituye una función de las sociedades de gestión, hacerlo efectivamente,
aun sin contar con la autorización debida, no parecería afectar los intereses de los autores,
compositores o intérpretes, sino todo lo contrario. A pesar de ello, también queda com
prendida como una forma agravada.
Y’es que estas entidades conservan una parte de la remuneración por concepto de gastos
administrativos (30%) y gastos socioculturales (10%), lo que solamente puede admitirse
en favor de entidades que hayan sido reconocidas como sociedades de gestión colectiva
por la autoridad administrativa correspondiente.
iii. Es de entender que estas entidades se constituyen para una mejor gestión de los derechos
de autory conexos. No obstante, puede suceder que los responsables de estas entidades
realicen determinadas conductas que vayan en perjuicio de los derechos administrados.
Estas son justamente las que se mencionan en el literal “c” del presente artículo.
iv. Se trata de conductas defraúdaterias que atenían contra los intereses patrimoniales de
los titulares de los derechos de autor o conexos representados por la entidad. La circuns
tancia agravante prevista en el literal “d”, consistente en la pertenencia a una organización
destinada a perpetrar estos ilícitos, nos parece innecesaria, pues basta aplicar la regla del
concurso de delitos (con el de pertenencia a organización criminal: art. 317o CP) para de
term inar la pena acorde al grado de injusto. Por si fuera poco, es de tener en cuenta que la
gran mayoría de los casos podrán ser reconducidos a la forma agravada, pues es raro que
estos ilícitos sean perpetrados de manera individual o sin un mínimo organizativo.
v. La circunstancia del literal “e” se atiene a la condición de funcionario o servidor público del
agente. En otro lugarya hemos cuestionado esta agravante. Sólo por mencionar algunos de
los cuestionamientos, debe repararse en que ya contamos con eíartículo46°-Adel Código
Penal, que podría eventualmente aplicarse al caso propuesto (más allá de la crítica que que
pa hacer a este artículo). Siendo además, que el literal “d” del artículo 220o fundamenta la
agravante en la sola condición de funcionario o servidor público, sin que se exija algún tipo
de aprovechamiento de su condición o cargo para la perpetración del hecho punible. Esto es
más propio de un derecho penal de autor, lo que resulta francamente inadmisible.
3. Delitos contra la propiedad industrial
Bien jurídico protegido: Este es el tema más debatido en la doctrina penal y no hay coinci
dencia entre los autores. Hay dos formas de clasificar las distintas posiciones existentes. La
primera se sustenta en la naturaleza individual (de carácter patrimonial) o supraindividual (la
Propiedad Industrial como instrumento en la economía de mercado) del bien jurídico.
En cambio, la segunda, no se sujeta a esos parámetros, aunque se podrían interpolar.
Siguiendo a García Cavero, encontramos cuatro teorías:
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1081 of 1506 --

Tema 6: Temas de la Especialidad Penal
i. Formalista o Positiva: Se protege la propiedad industrial, según el tenor del Capítulo que
recoge los ilícitos penales; es de naturaleza individual y la que menos describe la verda
dera esencia del bien jurídico.
ii. Administrativa: Se protege la competencia, el mercado o los consumidores, esto se debe
a la gran vinculación que existe entre la Propiedad Industrial y estos factores, sobre todo
en materia regulatoria; es de naturaleza supraindividual.
íii. Estática: Se protege el derecho individual de propiedad sobre determinados bienes, es
decir el uso exclusivo de los bienes que se encuentran dentro del ámbito de la Propiedad
Industrial, es de naturaleza Individual.
ív. Funcionalista: Se protegen relaciones sociales dinámicas, es decirse busca que se cumpla
la expectativa normativa de conducta de respeto del uso exclusivo de los bienes industria
les dentro de determinados parámetros, es de naturaleza individual y expresa mejor el
carácter de delito socioeconómico de esta clase de ilícitos penales, siendo ésta la opción
con la que concordamos.
3 . 1 . Tipos penales
a) Delito de fabricación o uso no autorizado de patente
Descripción típica:
“Art. 222 CP. Será reprimido con pena privativa de libertad no menor de dos ni mayor de cinco años,
con sesenta a trescientos sesenta y cinco días multa e inhabilitación conforme al Artículo 36 inciso
4) tomando en consideración la gravedad del delito y el valor de los perjuicios ocasionados, quien
en violación de las normas y derechos de propiedad industrial, almacene, fabrique, utilice con fines
comerciales, oferte, distribuya, venda, importe o exporte, en todo o en parte:
a. Un producto amparado por una patente de invención o un producto fabricado mediante la utilización de un
procedimiento amparado por una patente de invención obtenidos en el país;
b. Un producto amparado por un modelo de utilidad obtenido en el país;
c. Un producto amparado por un diseño industrial registrado en el país;
d. Una obtención vegetal registrada en el país, así como su material de reproducción, propagación o multiplicación;
e. Un esquema de trazado (tipografía) registrado en el país, un circuito semiconductor que incorpore dicho
esquema de trazado (topografía) o un artículo que incorpore tal circuito semiconductor;
f. Un producto o servicio que utilice una marca no registrada idéntica o similar a una marca registrada en el país. "
Tipicidad objetiva:
Lo debatible en esta área es incluir en todos los verbos rectores (fabricar, importar, almacenar
distribuir, usar con fines comerciales, ofertar, vender, exportar), tanto a los bienes como a los
servicios en el caso de las marcas regulado en el inciso f) del artículo 222o
Reconocemos que con esta Incorporación de verbos rectores con la Ley N° 27729, se amplían
los supuestos de sanción de ilícitos que penales en materia de propiedad industrial, al buscar
abarcartodo el espectro del circuito económico de bienesy servicios, pero aun así es necesario
un reordenamiento, sólo por una cuestión de didáctica frente a la población y por un afán de
constante mejora legislativa que debemos establecer en nuestro país.
