UBILEX
Cabe mencionar que esta relación de verbos rectores, influye también en cuanto a la consu
mación, y la tentativa; por cuanto, dependiendo de cada caso en particular, un delito puede ser
de mera actividad o de peligro, así como puede haber o no tentativa (aunque con esta relación
de conductas no es fácil caer en tentativa sino más bien recaer en cualquiera de los verbos
rectores). Las distintas situaciones jurídico-registrales pueden influir en las conductas, al es
tablecer causales de justificación o de atipicidad, como sucede con la nulidad o cancelación o
caducidad de la inscripción, o el caso del consentimiento del titular.
De la lectura del artículo 222o del Código Penal, se incluyen a bienes y servicios que deriven de
invenciones o de signos distintivos, aunque no se comprenden a la totalidad de las modalidades
de aquellas. En el caso de las Invenciones, se consideran a: la Patente de Invención, el Modelo de
Utilidad, el Diseño Industrial, la Obtención de Variedad Vegetal y el Esquema de Trazado.
En cambio, dentro de los Signos Distintivos, encontramos a las marcas, sean éstas de servi
cio, de producto, colectiva o de certificación. Pero en todos estos objetos, se requiere que la
invención o el signo distintivo se encuentren registrados en el Perú, en este caso, la Oficina de
Invencionesy Nuevas Tecnologías o en la Oficina de Signos Distintivos del Instituto Nacional
de Defensa de la Competencia y de la Protección de la Propiedad Intelectual (INDECOPI), se
gún sea el caso.
Tipicidadsubjetiva: El tipo penal exige que la conducta del autor sea con dolo.
b) Penalización de la clonación o adulteración de equipos terminales de telecomunicaciones:
‘A rt 2 2 2 -A C P - Será reprimido con pena privativa de libertad no menor de cuatro ni mayor de seis años,
con sesenta (60) a trescientossesentay cinco (365) días multa, el que altere, reemplace, duplique, clone, o de
cualquier modo modifique un número de línea, o identifcador de la tarjeta SIM, o identifcador de la Identi
dad Internacional del Abonado Móvil o del IM El o MAC lógico o físico o de cualquier otro dispositivo similar.
Este tipo penal penaliza la adulteración de terminales de telecomunicaciones, de acuerdo con
la modificación realizada porel Decreto Legislativo 1578 (Pub.15.10.2023), no solo quien altere,
reemplace, duplique sino también clone el número de línea o identificador de la tarjeta SIM o
¡dentificadorde la identidad internacional del abonado móvil o del IMEI o MAC lógico o físico
o de cualquier otro dispositivo similar. Esta modificación pretende atenuar la incidencia de ac
tos tendientes al manejo de líneas móviles clonadas y que luego son usadas para la comisión
de otros delitos contra el patrimonio o extorsivos.
El IMEI (del inglés International Mobile Equipment Identity, identidad internacional de equi
po móvil) es un código USSD pregrabado en los teléfonos móviles CSM. Este código identifica
al aparato de forma exclusiva a nivel mundial y es transm itido porel aparato a la red al conec
tarse a estay MAC significa Media Access Control, y cada código tiene la intención de ser único
para un dispositivo en particular.
c) Posesión ilegítima de SIM cards activados: “A r t 222-B CP.- El que provee, comercialice o facilite
la adquisición de SIM Card activados pudiendo presumir razonablemente que su uso es para la comisión
de delitos, será reprimido con pena privativa de libertad no menor de uno ni mayor de cuatro años y con
inhabilitación conforme al numeral 4 del artículo 36 del Código Penal. Si el agente adquiere, posee, los
SIM Card activados con la finalidad de favorecer o fa cilitarla comisión de delitos será reprimido con pena
privativa de libertad no menor de tres ni mayor de seis años”.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES

