Tema 6: Tem as de la Especialidad Penal
Delito incorporado con el paquete de modificatorias aprobada por el Decreto Legislativo 1578,
en el primer párrafo se penaliza la posesión ilegítima de SIM cards activados, cuya conducta
sancionada está referida a la comercialización o facilitación para la adquisición de estos dis
positivos pudiendo presumir razonablemente que su uso es para la comisión de delitos. Este
nuevo tipo penal va dirigido a combatir la venta indiscriminada de SIM cards que se realiza sin
supervisión en las calles de las grandes ciudades del país. Podemos agregarque la orientación
político- criminal que origina este artículo es la de prevenir futuros actos delictivos como los
delitos de extorsión, usurpación de identidad, entre otros.
En el segundo párrafo del artículo comentado se tipifica la conducta de quien adquiere los
SIM Cards para cometer actos delictivos. A través de este supuesto se sanciona tanto a quien
vende como también a quien compra los SIM Cards, para su configuración, en el primer su
puesto, el sujeto activo hade presumir el uso ilícito que se le dará, mientras que, en el segundo
supuesto, se sanciona el acto mismo de darle una finalidad ilícita.
d) Comercialización de Equipos Terminales Móviles con IMEI lógico o físico alterado, re
emplazado, duplicado: "A rtículo zzz-C CP.- El que tenga bajo su disposición, en exhibición para su
distribución, o para la venta o comercialización, equipos terminales móviles, número de línea, o de serie
electrónico, o de serie mecánico, o de IMEI lógico o físico, alterado, reemplazado, duplicado o de cualquier
modo modificados, será reprimido con pena privativa de libertad no menor de dos ni mayor de cuatro
años, e inhabilitación conforme al numeral 4 del artículo 36 del Código Penal”.
Delito incorporado con el paquete de modificatorias aprobada por el Decreto Legislativo 1578,
este artículo sanciona a los adquirentes de equipos móviles que tengan adulterado, modifica
do, duplicado o remplazado el IMEI ya sea físico o electrónico. Las reformas planteadas obede
cen al elevado índice de robos de celulares y que estos, a su vez, terminan comercializándose
en mercados ilegales.
Este tipo penal sanciona la sola tenencia de dispositivos alterados sin importar si se compró
de buena o mala fe,ya no se permite alegar, por parte de los compradores la buena fe (error de
tipo) aduciendo que los IMEIS no se reportan como robados y adjuntado sus comprobantes
de pago por la adquisición, la ley es más drástica ahora,ya que el tipo penal castiga el mismo
acto de disposición del equipo.
e) Posesión ilegítim a de dispositivos para adulterar, reemplazar, duplicar o m odificar
IMEI: "Art. z z z-D CP.- El que posea dispositivos, aparatos, herramientas, instrumentos o programas
informáticos con la finalidad de ser utilizados en la adulteración, reemplazo, duplicación o modificación
de IMEI lógico o físico de terminales móviles de comunicación, será reprimido con pena privativa de liber
tad no menor de cuatro años ni mayor de seis años e inhabilitación conforme al inciso 4 del artículo 36.
La misma pena se aplica al que, promueva, facilite o financie la obtención de los aparatos, herramientas,
instrumentos o programas informáticos para la finalidad señalada en el prim er párrafo.”
Delito incorporado con el paquete de modificatorias aprobada por el Decreto Legislativo 1596
(Pub. 17.12.2023), este artículo sanciona dispositivos, aparatos, herramientas, instrumentos o
programas informáticos con la finalidad de ser utilizados en la adulteración, reemplazo, du
plicación o modificación de IMEI lógico o físico de terminales móviles de comunicación. Esta
medida busca prevenir actividades delictivas relacionadas con la alteración de identificadores
de dispositivos móvilesy contribuir a la lucha contra la delincuencia asociada a estos equipos.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 1084 of 1506 --

f) Uso o v e n ta n o autorizada de diseño o modelo industrial: “A rt. 223 CP.- Serán reprimidos con
pena privativa de la libertad no menor de dos ni mayor de cinco años, con sesenta a trescientos sesenta
y cinco días-multa e inhabilitación conforme al Artículo 36 inciso 4) tomando en consideración la gra
vedad del delito y el valor de los perjuicios ocasionados, quienes en violación de las normas y derechos de
propiedad industrial: a. Fabriquen, comercialicen, distribuyan o almacenen etiquetas, sellos o envases
que contengan marcas registradas; b. Retiren o utilicen etiquetas, sellos o envases que contengan mar
cas originales para utilizarlos en productos de distinto origen;y c. Envaseny/o comercialicen productos
empleando envases identificados con marcas cuya titu la rid a d corresponde a terceros."
Incautáción preventiva y comiso definitivo: En los delitos cometidos contra la propiedad in
dustrial se procederá a la incautación preventiva de los ejemplares y materiales, de los apara
tos o medios utilizados para la comisión del ilícito y, de ser el caso, de los activos y cualquier
evidencia documental, relacionados al ¡lícito penal. En caso de emitirse sentencia condenato
ria, los ejemplares, materiales ilícitos, aparatosy medios utilizados para la comisión del ilícito
serán comisados y destruidos, salvo casos excepcionales debidamente calificados por la auto
ridad judicial. En ningún caso procederá la devolución de los ejemplares ilícitos al encausado.
Condición y grado de participación del agente: Será reprimido con pena privativa de libertad
no menordedos ni mayorde cinco añosy con noventa a trescientos sesentay cinco días-multa
e inhabilitación conforme al artículo 36, inciso 4: a) Si el agente que comete el delito integra
una organización criminal destinada a perpetrar los ilícitos previstos en el presente capítulo,
b. Si el agente que comete cualquiera de los delitos previstos en el presente capítulo, posee la
calidad de funcionario o servidor público.
22. DELITOS CONTRA CONFIANZA Y LA BUENA FE EN LOS NEGOCIOS
1. Delito de insolvencia fraudulenta
Descripción normativa:
“Art. 209 CP. Será reprimido con pena privativa de libertad no menor de tres ni mayor de seis años e in-
í habilitación de tres a cinco años conforme al Artículo 36 incisos 2) y 4), el deudor, la persona que actúa
\Jw J en su nombre, el administrador o el liquidador, que en un procedimiento de insolvencia, procedimiento
simplificado, concurso preventivo, procedimiento transitorio u otro procedimiento de reprogramación
de obligaciones cualesquiera fuera su denominación, realizara, en perjuicio de los acreedores, alguna de las
siguientes conductas:
1. Ocultamiento de bienes;
2 . Simulación, adquisición o realización de deudas, enajenaciones, gastos o pérdidas; y,
3. Realización de actos de disposición patrimonial o generador de obligaciones, destinados a pagara uno o va
rios acreedores, preferentes o no, posponiendo el pago del resto de acreedores. Si ha existido connivencia con
el acreedor beneficiado, éste o la persona que haya actuado en su nombre, será reprimido con la misma pena.
Si la Junta de Acreedores hubiere aprobado la reprogramación de obligaciones en un procedimiento de insol
vencia, procedimiento simplificado, concurso preventivo, procedimiento transitorio u otro procedimiento de
reprogramación de obligaciones cualesquiera fuera su denominación, según el caso o, el convenio de liqui
dación o convenio concursa!, las conductas tipificadas en el inciso 3) sólo serán sancionadas si contravienen
dicha reprogramación o convenio. Asimismo, si fuera el caos de una liquidación declarada por la Comisión,
conforme a lo señalado en la ley de la materia, las conductas tipificadas en el inciso 3) sólo serán sancionadas
si contravienen el desarrollo de dicha liquidación.
Si el agente realiza alguna de las conductas descritas en los incisos 1), 2) ó 3) cuando se encontrare sus
pendida la exigibilidad de obligaciones del deudor, como consecuencia de un procedimiento de insolvencia,
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y N O M B R AM IEN TO DE JUECES Y FISCALES

-- 1085 of 1506 --

Tema 6: Temas de la Especialidad Penal
procedimiento simplificado, concurso preventivo, procedimiento transitorio u otro procedimiento de repro
gramación de obligaciones cualesquiera fuera su denominación, será reprimido con pena privativa de libertad
no menor de cuatro ni mayor de ocho años e inhabilitación de cuatro a cinco años, conforme al Artículo 36
incisos 2) y 4)."
Bien jurídico protegido: El tipo penal de insolvencia fraudulenta es un delito de afectación
pluriofensivo, debido a que vulnera dos bienes jurídicos de carácter colectivo e individual. En
efecto, aunque nos inclinamos por considerar como bien jurídico primordial al Sistema Credi
ticio, en su aspecto funcional en favor del orden socioeconómico que a final sería el verdadero
favorecido de la tutela penal, no desconocemos el derecho crediticio de los acreedores que se
han perjudicado concretamente con los actos delictivos (tutela patrimonial).
Algunos en la doctrina han incidido en dicho carácter de que nos encontramos ante un de
lito de protección mixta, pues el bien jurídico protegido sigue siendo el derecho de crédito
de acreedor, conducente la satisfacción de su contenido sobre el patrimonio del deudor, pero
además el delito adquiere relevancia colectiva de infracción contra el orden socioeconómico,
en atención a las consecuencias sociales que estas conductas pueden producir.
Tipicidad objetiva: El delito de insolvencia fraudulenta es un delito especial propio, toda vez
que conforme se desprende de lo expuesto por el artículo 209o del Código Penal, solamente
puede ser cometido por el deudor, la persona que actúa en su nombre, el administrador o el
liquidador de una empresa.
La descripción normativa exige para que se configure el delito de insolvencia fraudulenta, que
los actos realizados por el sujeto activo en agravio de los acreedores deben ser cometidos en
un procedimiento de insolvencia, procedimiento simplificado, concurso preventivo, proce
dimiento transitorio, u otro procedimiento de reprogramación de obligaciones cualesquiera
fuera su denominación.
En cuanto a los procedimientos concúrsales, hay que señalar que si bien los nombres de es
tos procedimientos actualmente regulados por la Ley General del Sistema Concursal no están
expresamente indicados en el tipo penal, la referencia típica al procedimiento de insolvencia
debe entenderse hecha a los actuales procesos concúrsales (procedimiento concursal ordina
rio y procedimiento concursal preventivo) tal como lo establece la Tercera Disposición Com-
plementariay Final de la Ley General del Sistema Concursal201.
Por otro lado, el delito de insolvencia fraudulenta no requiere que el deudor haya sido declara
do como quebrado, sino que basta que esté adentro de cualquier de los procedimientos con
cúrsales que señala la ley de la materia. Conforme lo señalado, cualquier acto o transacción
que se habría realizado fuera del procedimiento concursal respectivo, incluso de naturaleza
fraudulenta, para los fines del tipo penal que es objeto de análisis no tendría relevancia penal
por lo menos como delito de insolvencia fraudulenta.
201 Tercera Disposición Complementaria y Final de la Ley General del Sistema Concursal: Las referencias legales
o administrativas al procedimiento de Declaración de Insolvencia se entienden hechas al Procedimiento
Concursal Ordinario y aquellas hechas al Concurso Preventivo se entienden efectuadas al procedimiento
Concursal Preventivo.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1086 of 1506 --

UBILEX
El sujeto pasivo viene a ser la sociedad como titu lar del funcionamiento del sistema crediticio,
aunque también se afectan con estas conductas los acreedores titulares de los bienes o los
derechos. Así pues, el sujeto pasivo del delito es la sociedad; pero el sujeto pasivo de la acción
vendría a ser los acreedores.
En cuanto a los actos típicos:
i) Se admite ejecutar la ocultación, indirectamente, así cuando se oculta el título que re
presenta a los bienes. Esta ocultación puede ser total o parcial. La primera, se da si se
oculta todos los bienes; la segunda, cuando solo se oculta parte de ellos. La últim a forma
resultara idónea para los requerimientos típicos cuando el bien que queda visible a las
exigencias de los acreedores es satisfactorio todavía a las deudas.
También puede ser física o jurídica. Una ocultación física sucede cuando se esconde
los bienes o se traslada físicamente a lugares en los cuales los acreedores desconozcan;
mientras que, una ocultación jurídica implica la transferencia de la titularidad de los bie
nes a terceros. Con los actos materiales de ocultamiento el agente logra evitar que sus
bienes formen parte del procedimiento concursal, generando fraude en perjuicio de sus
acreedores.
ii) Específicamente, el incido 2 del artículo en mención castiga el aumento indebido del pa
sivo del deudor concursado y, por tanto, la disminución de su patrim onio202. Asimismo, el
hecho de que el deudor recurra a una simulación deuda configura por sí mismo un acto
de defraudación suficiente para dar relevancia típica a esta conducta, pues en esta mo
dalidad del fraude concursal doloso resulta necesaria la intervención de un tercero que
aparece como el acreedor de la deuda o beneficiario del gasto203.
En la medida que este tercero conozca la simulación, responderá como cooperador nece
sario del delito (cómplice primario).
iii) Con la modalidad de realización de actos de disposición patrimonial o generadorde obli
gaciones destinadas a pagar a uno o varios acreedores, preferentes o no, posponiendo el
pago del resto de los acreedores, algunos acreedores no se ven perjudicados, a costa de
otros, a diferencia de las otras dos anteriores modalidades, en la cual todos los acreedores
son perjudicados. Uno o varios acreedores obtienen más ventajas, reduciéndose el crédi
to que normalmente debían de obtener los otros acreedores. En otras palabras, se incurre
en un favorecimiento de acreedores gem ine no justificado.
Se distingue, en la ejecución delictiva, dos conductas. La primera conducta consiste en la rea
lización de actos de disposición patrimonial destinados a pagara los acreedores beneficiados,
en donde el deudor va a disponer o tom ar de su patrimonio en beneficia de las deudas que
tiene con los acreedores que el considere a pagar. En la segunda conducta se van a realizar ac
tos generadores de obligaciones que se destinan a pagar a los acreedores beneficiados. Aquí,
el deudor va adquirir o realizar deudas durante el procedimiento concursal para así obtener
más obligaciones para con los acreedores que a los que ha destinado los beneficios, todo esto
en perjuicio de los demás acreedores.
202 GARCIA CAVERO, Percy. Op. Cit. pp. 306y ss.
203 lb¡d., p. 312.
