UBILEX
Conforme se aprecia del tipo, el núcleo de la acción gira en torno a dos formas de conducta
básicas: el obligary el hacer prometer el pago de intereses usureros. Es así que el agente ins-
trum entaliza como medio de acción, la utilización direccionada y dolosa de la coacción, que
válidamente puede asumi ría forma de violencia física e incluso de intimidación. El tipo no cu
bre la conducta engañosa, la que da cara al tipo en comentario, resultara atípica (pudiéndose
encuadraren la forma de estafa o defraudación).
Por''bbligar” hay que entender el acto de compeler a alguien a realizar algo que no desea reali
zar, mientras que la expresión “hacer prometer” significa la conducta de quien asegura el cum
plimiento de algo (todo ello gira con relación a conductas persuasivas ilícitas y abusivas, que
pretenden la exigencia del pago de intereses por encima de los señalados por la ley).
Como se puede apreciar, la conducta típica se manifiesta en la concesión de un crédito o en su
otorgamiento, renovación, descuento o prórroga del plazo de pago. Concertar un crédito involu
cra la realización de un contrato de crédito, que determina, desde la perspectiva civilista, la facul
tad de utilizar un capital de otro, con la obligación de devolver el mismo capital o el equivalente
respectivo, agregando los intereses pertinentes. La acción se materializa tanto en el momento de
su perfeccionamiento (otorgamiento), en su renovación (realizar un nuevo contrato que reem
plaza al que ya se venció), descuento (es el interés de un préstamo efectuado con una garantía en
el tráfico comercial), o en su prorroga (ampliación del plazo de cumplimiento).
Tipicidad subjetiva: La conducta usurera se observa una evidente direccionalidad del compor
tamiento del agente a lograr un estado de imposición coactiva (una forma extorsiva), en virtud
del cual logra su objetivo. En la usura se constata conciencia y voluntad por parte del agente,
de imponer intereses abusivos, por lo que la acción se representa como eminentemente dolosa.
Asimismo, el tipo integra la exigencia subjetiva de que el agente haya actuado "con el fin de obtener
una ventaja patrimonial, para sí o para otro", lo que involucra la necesidad de que la conducta del
agente haya sido motivaday direccionada por un especial animuslucrandi que no necesariamen
te debe materializarse (ello por la característica de tipo de peligro del injusto), sino que debe
estar presente desde el inicio de la acción y debe comandar la conducta. Adquiere así el tipo una
característica suigeneris que lo representa como uno de tendencia interna trascendente (que son
aquellos que contienen una finalidad o propósito que trasciende la mera realización del tipo).
3. Delito de libramiento y cobro indebido
Descripción normativa:
“Art. 215 CP. Será reprimido con pena privativa de la libertad no menor de uno ni mayor de cinco años, el que
gire, transfiera o cobre un Cheque, en los siguientes casos:
1) Cuando gire sin tener provisión de fondos suficientes o autorización para sobregirar la cuenta corriente;
2) Cuando frustre maliciosamente por cualquier medio su pago;
3) Cuando gire a sabiendas que al tiempo de su presentación no podrá ser pagado legalmente;
4) Cuando revoque el cheque durante su plazo legal de presentación a cobro, por causa falsa;
5) Cuando utilice cualquier medio para suplantar al beneficiario o al endosatario, sea en su identidad o firmas;
o modifique sus cláusulas, líneas de cruzamiento, o cualquier otro requisito formal del Cheque;
6) Cuando lo endose a sabiendas que no tiene provisión de fondos.
En los casos de los incisos 1) y 6) se requiere del protesto o de la constancia expresa puesta por el banco
girado en el mismo documento, señalando el motivo de la falta de pago.
88 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1089 of 1506 --

Tema 6: Temas de la Especialidad Penal
Con excepción del incisos 4) y 5), no procederá la acción penal, si el agente abona el monto total del Cheque
dentro deí tercer día hábil de la fecha de requerimiento escrito y fehaciente, sea en forma directa, notarial,
judicial o por cualquier otro medio con entrega fehaciente que se curse al girador,"
Bien jurídico protegido: El delito de libramiento indebido es un delito pluriofensivo, en el que
resultan afectándose tantos bienes jurídicos colectivos, como la seguridad del comercio, ha
biéndose entendido como afectada incluso la fe pública; así como bienes jurídicos individua
les, como el patrimonio del tenedor del cheque.
Tipicidad objetiva: En primer lugar, debemos indicar que el art. 215°C.P emplea tres verbos
rectores: girar, transferir y cobrar un cheque realizando alguna de las conductas previstas en
los referidos incisos.
• El g ira re s la forma de expedir un cheque, esto es, firmando en el mismo, a través de lo cual
se puede poner en circulación dicho título valor. Este verbo se emplea expresamente en
los incisos primero y tercero.
• Por transferirse entiende el poner en circulación el cheque mediante la simple entrega
-tra d itio -. Esto es entendióle tanto en los cheques al portador como en los cheques nom i
nativos, los cuales se pueden transferir si el título valor esta endosado. En ninguno de los
incisos del art. 215°C.P se hace referencia explícita a dicho verbo.
• El cobrarse configura cuando la persona recibe el dinero consignado en el cheque. Tam
poco se hace referencia a dicho verba en el art. 215°C.P, si bien, en la nomenclatura del
capítulo se emplea el term ino cobra indebido, esto es, el cobro de una cantidad de dinero a
la cual no se tiene derecho.
Para configurar el delito de libramiento indebido, el legislador ha previsto una serie de su
puestos alternos. La sola acción de girar el cheque no configura el delito, sino que el agente
debe hacerlo incurso en alguno de los supuestos previstos en la norma penal:
a) No tener provisión de fondos o autorización para sobregirarse.
b) Frustrar maliciosamente el pago.
c) Girar a sabiendas que al tiempo de su presentación no podrá ser pagado legalmente.
d) Cuando revoque el cheque durante su plazo legal de presentación a cobro, por causa fal
sa.
e) Cuando utilice cualquier medio para suplantar al beneficiario o al endosatario, sea en su
identidad o firmas; o modifique sus cláusulas, líneas de cruzamiento, o cualquier otro
requisito formal del cheque.
f) Cuando se endosa el cheque a otra persona a sabiendas que no tiene fondos.
La norma penal señala también que el agente debe ser informado de la falta de pago median
te protesto u otra forma documentada de requerimiento, en los casos de girar un cheque sin
tener provisión de fondos o autorización para sobregirarse, frustrar maliciosamente el pago o
girar el cheque a sabiendas que al tiempo de su presentación no podrá ser pagado legal mente.
El protesto es el acto solemne por el cual se acredita en forma verosímil que un título valor no
se ha pagado. El protesto puede efectuarse dentro del plazo de 30 días si el cheque es em itido
