23. DELITOS CONTRA LA FE PÚBLICA
Los delitos contra la fe pública son aquellos que contravienen a la confianza colectiva en de
terminados actos, documentos, signos o símbolos indispensables para el normal desenvol
vimiento de la vida civil. El bien jurídico tutelado en estos delitos es la fe pública, entendida
ésta como la confianza o creencia que cualquier miembro del grupo social tiene en lo que se
entrega o muestra, por la certeza que de ello da el Estado.
Bien jurídico protegido: El bien jurídico protegido en los delitos contra la fe pública se con
creta en la confianza que prestan los ciudadanos a determinadas formas u objetos que juegan
un papel especial dentro de las relaciones sociales que se desenvuelven en el tráfico jurídico.
1. El delito de falsificación de documentos en general
a) Falsificación de documentos: En el delito de falsificación de documentos el bien jurídico
está determinado por la funcionalidad del documento en el tráfico jurídico.
El delito de falsificación de documentos se encuentra regulado en el Art, 427 del Código Penal
y se configura cuando el agente hace, en todo o en parte, un documento falso o adultera uno
verdadero que pueda dar origen a derecho u obligación o servir para probar un hecho, con el
propósito de utilizar el documento. Asimismo, realiza este delito el que hace uso de un docu
mento falso o falsificado, como si fuese legítimo, siempre que de su uso pueda resultar algún
perjuicio.
El bien jurídico protegido es la fe pública, y el hecho delictivo se caracteriza como un delito
común, pues cualquier persona puede realizarlo.
— Tipo objetivo.- La acción típica del primer párrafo describe dos modalidades: i) hacer en
todo o en parte un documento falso (falsedad propia), y, ii) adulterar uno verdadero (falsedad
impropia), ambas modalidades obedecen a la voluntad del autor por usar el documento que
ha sido objeto de falsificación, como si fuera verdadero, entendiendo el término “usar» en el
sentido de emplear o utilizar dicho documento.
En el caso del segundo párrafo, se requiere que el agente activo haga uso de un documento falso
o falsificado como si fuera legítimo o verdadero, siempre que de su uso haya algún perjuicio.
Se cumple el requisito típico de uso de documento público falso cuando es introducido en el
tráfico jurídico, desde que se coloca o incorpora el documento falso o falsificado al tráfico o
al cúmulo de relaciones sociales, políticas, económicas o jurídicas; para determinar si en rea-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1091 of 1506 --

Tema 6: Temas de la Especialidad Penal
I¡dad el documento falso se utiliza o emplea, lo decisivo es la penetración o incorporación en
el tráfico jurídico.
La institución resulta aplicable a persona distinta del autor de la falsedad, cuando obra de
manera autónoma o, puede tratarse incluso del mismo autorde la falsedad, que inicialmente
haya procedido sin los requisitos subjetivos requeridos por la figura; en este caso basta que
los requisitos subjetivos se hallen presentes en el segundo de los momentos. En este últim o
el uso de documento es una acción unida, lógica y jurídicamente a la conducta típica de la
falsificación.
Está claro que Documento Público es aquel expedido por los funcionarios públicos que están
autorizados a ello, en lo que se refiere a ejercicio de sus funciones. Por ello se dice que debe
cumplir tres características: «que el documento sea emitido por un funcionario público o au
toridad, que el mismo sea legalmente competente para expedir tal clase de documento, en
tendiéndose por competencia no sola la genuina potestad de em itir un documento de aquella
clase, sino la competencia por razón de materiay territorio para em itir el concreto documento
y en tal emisión observe la forma prescrita por la ley para cada caso».
Sujeto Activo.- Puede ser cualquier persona, el tipo penal no exige condición o cualidad espe
cial del agente, basta que sea imputable penalmente para responder penal y civilmente por
el delito.
Sujeto pasivo.- PEÑA CABRERA FREYRE señala que desde un plano macrosocial, tomando
en cuenta la naturaleza supraindividual del bien del bien jurídico protegido, sería la sociedad
como sujeto pasivo mediato, pero, del mismo tenor de la redacción normativa, se identifica
un sujeto pasivo inmediato, el tercero, que puede verse perjudicado con el uso del documento
falsario en el tráfico jurídico.
— Tipo subjetivo.-El dolo típico requiere el conocimiento cierto de la falsedad del documen
to y la voluntad de utilizarlo tal según su finalidad probatoria.
— Circunstancias agravantes y penas: La circunstancia agravante está determinada por la
falsificación de un documento público, un registro público, un título auténtico o cualquier otro
transmisible por endoso o al portador.
La pena privativa de libertad será no menor de dos ni mayor de diez años y con treinta a no
venta días multa.
La comisión del delito de falsificación de documentos por parte del notarioy la pena: Cuando
el delito de falsificación de documentos sea cometido por un notario, funcionario o servidor
público, siempre y cuando medie el abuso de sus funciones, se le impondrá además la pena
de inhabilitación de uno a tres años privándole de su función e incapacitándolo para obtener
mandato, cargo, empleo o comisión de carácter público (artículo 432° Código Penal).
— Consumación del delito.- Se produce con el sólo hecho de falsificar un documento, puesto
que efectuada la falsificación del objeto material del delito, éste se convierte en un elemento
potencial para causar peligro a terceros, en ese entendido el uso o no de dicho instrumento será
irrelevante para la consumación del delito. Así lo confirma la Sala Penal Permanente de la Corte
Suprema al establecer como doctrina jurisprudencial vinculante en la Cas. N° 1121-2016, Puno
(15 de agosto de 2017) que: “DÉCIMO: Como se señaló el tipo penal de falsificación no presenta
