Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1092 of 1506 --

UBILEX
ambigüedad en su redacción referente al perjuicio; pues señala claramente que para la confi
guración del delito basta la potencialidad e idoneidad del mismo; así, en uno de sus últimos
pronunciamiento esta Corte Suprema mediante el Recurso de Nulidad N° 2279-2014/ Callao, en
su fundamento jurídico N° 4 -4 , ha señalado que: “la condición objetiva de punibilidad en esta ciase de
ilícitos es ¡a posibilidad de causar perjuicio al agraviado y no perjuicio efectivo para considerarse típico, por
cuanto el bien jurídico que se tutela es el correcto funcionamiento de la administración pública referidos al
tráfico jurídico correcto Así, para la configuración típica en un caso concreto se deberá conside
rar como típico la sola potencialidad de perjuicio -no se requiere su concretización-".
b) Falsedad ideológica: El tipo de falsedad ideológica, se encuentra regulada en el Art. 428 CP
se configura este delito cuando el agente inserta o hace insertar, en instrumento público, de
claraciones falsas concernientes a hechos que deban probarse con el documento, con el obje
to de emplearlo como si la declaración fuera conforme a la verdad. Resulta necesario también
recalcar que la sanción de este delito se equipara hacia aquel que hace uso del documento
como si el contenido fuera exacto, siempre que de su uso pueda resultar algún perjuicio.
Los bienes jurídicos protegidos son la seguridad en el tráfico jurídico y la fe pública.
— Tipo objetivo.- Según García Cantizano, la falsedad puede sercometida en dos momentos
concretos: en el mismo instante de la redacción del documento o en un momento posterior,
una vez que ya está conformado perfectamente el documento. En base a esta apreciación, se
considera que la falsedad ideológica es la única susceptible de ser cometida en el momento
preciso de la confección del documento. Este autor también menciona que: las formas positi
vas de ejecutar la alteración del documento son la adición, donde la intercalación no es más
que una forma específica de ésta, y la modificación o alteración, strictu sensu, del contenido
que debiera expresarse documental mente, con el requisito común a todas de la concurrencia
de la sustitución de un contenido por otro.
Sujetos.- En la acción de «insertar», el sujeto activo o agente puede sersolo el funcionario que
tiene la misión de autenticar el documento en el que están insertas las declaraciones falsas.
En cambio, en la acción de «hacer insertar», son autores o sujetos activos los otorgantes o soli
citantes del acto que, con conocimiento y voluntad, hacen insertar declaraciones falsas, con el
consentimiento del funcionario o sin él.
— Tipo subjetivo.- El presente es un delito doloso, compatible solo con el dolo directo.
— Consumación.- Para la doctrina dominante, se consuma la acción cuando el objeto en
el que se han hecho las inserciones falsas adquiere la calidad de documento público. La
consumación se da con el perfeccionamiento del instrumento (escritura pública) o al adquirir
este valor como tal.
El delito en estudio se consuma cuando el documento público queda perfeccionado como tal,
con todos los signos de autenticidad requeridos por ley, aunque no se hayan realizado todavía
los actos necesarios para oponer ante terceros la prueba por él constituida, pues ya en ese
momento ha nacido la posibilidad de perjuicio.
