I
1. CRIMINOLOGÍA Y DERECHO PENAL
1.1. La criminología
La palabra Criminología, definido por el Diccionario de la Real Academia de la lengua Españo
la en su más reciente 22° edición, la define en dos partes, del latín cnm inis-c rim e n y del griego
logia-tratado, bajo esta premisa, criminología sería tratado del crimen.
Esta palabra, acuñada por el antropólogo francés TOPPINARD ha sido hasta el momento
adoptada para titu lar las obras que se ocupan del estudio del delincuente y de las medidas
represivas del delito, fue RAFAEL CAROFALO quien la adopta por primera vez para este fin.
Siguiendo con el concepto gramatical, para este diccionario la criminología se ocupa de los es
tudios sobre las causas y circunstancias de los distintos delitos, se encarga de la personalidad
de los delincuentes y del tratamiento adecuado para su represión. Como lo constataremos
más adelante este concepto es similar a los muchos que existen en la literatura criminológica,
razón por la cual empiezo con esté, es para estructurar la versión más aceptada para su com
prensión y estudio.
Concepto: Por los conocimientos que aporta la criminología cobra el rango de ciencia, esto es,
aporta conocimientos verificados, sistemáticos, por razón del método y técnicas de investiga
ción, la criminología es una disciplina empírica e interdisciplinaria: una ciencia del serfáctica,
inductiva, que predomina la observación de la realidad sobre la perspectiva norm ativistay el
método abstracto, formal y deductivo propios de otras ciencias. Finalmente, en cuanto a su ob
jeto la criminología se ocupa del crimen, del infractor desde el punto de vista bio-psico-social,
esto es, del delincuente, de la víctima, del d elitoy del control social del comportamiento des
viado. Como ciencia empírica del hombre en su entorno social, la criminología se encuentra
relacionada con otras ciencias como la psiquiatría y la sociología, y dentro de la totalidad de
las ciencias penales se encuentra íntimamente relacionada con el derecho penal, sin embargo,
no debe ser identificada como ciencia auxiliar del derecho penal.
1.2. Lincamientos elementales del Derecho Penal
El derecho penal materializado en el Código Penal en su más estricta expresión se interpreta
como el principal sinónimo de represión, en este caso social, no tendría su razón de ser si no
lo fuera, pues hasta el momento no se conoce un código penal con fines distintos, con la fina
lidad irrestricta de una doble vertiente; en la protección de bienes jurídicos y en la prevención
de conductas delictivas futuras, bien de carácter especial y general, fundamentales para lograr
la sana convivencia social. El Código penal representa la últim a razón del Estado (Ú ltim a ratio)
para conseguir el restablecimiento social que se vio vulnerado, es decir que, para utilizar el
Código Penal, la sociedad representada, tendría que haber agotado todas las instancias civiles
y de carácter administrativo hasta llegar a esta últim a razón que tiene el Estado de utilizar su
fortaleza represiva mediante la implementación de medidas penales que pueden ser desde
una multa hasta la privación de la libertad.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1095 of 1506 --

Tema 6; Temas de la Especialidad Penal
1.3. La Interacción entre el Derecho penal y la crim inología
El derecho penal es el conjunto de normas jurídico positivas reguladoras del poder punitivo
del Estado como delitos determinados presupuestos a los que asignan ciertas consecuencias
jurídicas, entendidas éstas como penas o medidas de seguridad.
El derecho penal se erige como ciencia normativa, del “deber ser", la criminología por lo tanto
como ciencia del “ser”. La delimitación se identifica por el método utilizado por cada una de
ellas, mientras la primera utiliza el deductivo la segunda el inductivo.
El derecho penal regula la conducta humana externa en el ámbito social, para proteger bienes
jurídicos que equilibran la convivencia social, en el sentido de mantener los límites del ius
puniendi para evitar la justicia social unilateral, logrando garantizar la protección de los parti
culares en intervenciones ilícitas por parte del estado.
Mientras que la criminología puedeydebe desempeñar un papel importante al momento de
determinarque hechos han de ser descriminalizados, de tal maneraque la criminología aun
que recibe el concepto normativo legal de delito, debe de reducir o extender su propio objeto
de regulación y que medios debe emplear para preveniry reprimir eficazmente los ataques a
la sociedad.
Por todo esto queda claro que entre el derecho penal y la criminología existe una interacción
que debe de establecerse entre los dos saberes, por eso afirmamos que la criminología sin el
derecho penal esta ciega, el derecho penal sin la criminología es estéril.
2. CRIMINOLOGIA CLÁSICA Y LA CRIMINOLOGIA MODERNA
2.1. La criminología clásica
La criminología posee un método de estudio empírico e interdisciplinar. En la escuela clásica
se utilizaba el método deductivo. Es Lombroso el padre de la Criminología (escuela positiva),
a partir de aquí empieza a utilizar el método empírico (observar la realidad) empieza a consi
derarse ciencia.
El método empírico toma la experiencia como única base del conocimiento humano. No bus
ca exactitud al realizar sus estudios sino probabilidad. El Criminólogo analiza datos y saca
conclusiones.
Toma el carácter de ciencia autónom ay se convierte en sociología criminal, utilizando el resto
de ciencias que le dan información, (antropología, sociología, psicología, biología, estadística
criminal). El principio interdisciplinar recoge información de estas ciencias y las integra, las
coordina y da soluciones. Esto permite que la Criminología de un diagnóstico científico del
crimen.
2.2. La criminología moderna
A partir de mediados del sig lo xx; se presenta un cambio de paradigma en la ciencia crim i
nológica fijando su atención en los procesos de criminalización, en el ambiente social, pero
estudia también a la víctima. Según la definición de Antonio García-Pablos de Molina:
