“Es una ciencia empírica e interdisciplinaria, que se ocupa del estudio del crimen, de la perso-
nadel infractor, lavíctim ayel control social del comportamiento delictivo, y trata de suminis
trar una información válida, contrastada, sobre la génesis, dinám icay variables principales del
crimen — contemplado éste como problema individual y como problema social— así como
sobre los programas de prevención eficaz del mismo, las técnicas de intervención positiva en
el hombre delincuentey los diversos modelos o sistemas de respuesta al delito”.
3 . D E F IN IC IÓ N ¥ T IP O S D E C R IM E N
El crimen es un hecho innato al ser humano. Por más que se retroceda en el tiempo ambas
variables se hallan presentes a lo largo de la historia. Desde el asesinato de Caín y Abel hasta
nuestros días se han producido m ultitu d de manifestaciones delictivas. El delito debe consi
derarse un hecho cíclico que aumenta o disminuye según los medios de control social adopta
dos por los diversos entes nacionales e internacionales. Durkheim lo definió como un fenóme
no normal dentro de una sociedad, incluso aunque la misma estuviera compuesta por santos
el crimen existiría.
Desde el punto de vista del derecho, el crimen es una conducta, una acción o una omisión
tipificada por la ley que resulta antijurídica y punible. Un crimen, por lo tanto, viola el derecho
penal. El concepto está vinculado al de delito, aunque esta palabra (del latín delinquen) tiene
un origen etimológico que remite a “abandonar” el camino establecido por la ley.
Delito, por lo tanto, suele usarse en un sentido genéricoy crimen se reserva para hacer referen
cia a un delito de gravedad o a un delito ofensivo contra las personas.
Crimen y delincuencia organizada: Se conoce como crimen organizado o delincuencia orga
nizada la actividad que realiza un grupo estructurado sólidamente cuya finalidad es cometer
delitos graves a fin de obtener a cambio un beneficio económico o material. En cada país exis
ten diversos grupos que desarrollan este tipo de acciones que atenta con la seguridad.
Cabe mencionar que las acciones realizadas por estas personas van en contra de la legislación
vigente. Pese a ello, consiguen desempeñar su labor de una forma tan “cuidadosa" que la justi
cia no puede condenarlos. Cabe mencionartambién que, en muchos casos, se hace muy difícil
acabar con ellos ya que dichos grupos se encuentran protegidos por instituciones, personas o
entidades con un cierto peso social.
Estos grupos, además de cometer crímenes de todo tipo, suelen traficar con drogas, personas
y cometer delitos de todo tipo, como secuestros y asesinatos.
Desde hace años la Organización de las Naciones Unidas intenta desarrollar proyectos para
luchar contra este tipo de organizaciones delictivas y term inar con la delincuencia organizada,
estableciendo medidas para el combate e intentando que las personas de cada país colaboren
con el esclarecimiento de los crímenes cometidos por estos organismos.
4 . U P O D E C O N D U C T A
