evitar que se trasgreda su estado de derecho.
Existen diferentes tipos de conductas que son estudiadas por la Criminología de manera
reiterada, esto con el fin de identificar el posible nacimiento de una conducta delictiva que
trasgreda el bien común de las personas, esto en base a las actitudes de las desplegadas por
