y discernir esos pensamientos negativos en el sujeto que desencadenen una acción criminal.
Encontrando entonces que las conductas existentes son la social, asocial, parasocial y antiso
cial en donde la más estudiada por las personas del gremio encargadas de estudiar el porqué
de la conducta criminal es laantisocial pero no poreso dejando atrás las otras tres, ya que con
