La conducta social, es aquella que se adecúa a las normas de convivencia socialmente
establecidas, en donde nadie trasgrede o viola alguna de estas, este tipo de conductas
lo que busca es evitar agredir a la colectividad, vivir en sana armonía como tejido social
vinculado al sano desarrolloy cumplir el bien común, esta conducta es la que la mayoría
de los miembros de las sociedades realizan.
La conducta asocial, en este caso se resume en comportamientos de soledady aislamien
to en donde las personas carecen de un contenido social donde pierden toda relación
con las normas de convivencia y con el bien común, por lo que su estado de soledad les
impide trasgredir las normas.
Conducta parasocial, esta es diferente a la conducta social la cual sigue la mayoría de las
personas de la sociedad, en este caso el parasocial no acepta los valores aceptados por
la colectividad, aunque tampoco los ataca ni busca destruirlos, no busca el bien común
pero aun así nunca lo agrede, a diferencia también de la conducta asocial es que el para
social no es aislado al contrario es una conducta que tiene la capacidad de relacionarse
con otros.
Y por últim o tenemos la conducta antisocial, este es uno de los casos más sonados por
