5 . D E L IN C U E N T E
La Criminología se ocupa, como es lógico, del delincuente: de la persona del infractor. La per
sona del delincuente alcanzó su máximo protagonismo como objeto de las investigaciones
criminológicas durante la etapa positivista. El principio de la diversidad que inspiró la Crimi
nología tradicional convirtió a éste en el centro casi exclusivo de la atención científica.
En la moderna Criminología, sin embargo, el estudio del hombre delincuente ha pasado a un
segundo plano, como consecuencia del giro sociológico experimentado por aquella y de la
necesaria superación de enfoques individualistas en atención a objetivos político criminales.
El centro de interés de las investigaciones se desplaza prioritariamente hacia la conducta de
lictiva misma, la víctim ay el control social. Pero más significativo es la imagen que se profesa
del hombre delincuente: con el prototipo de criminal se opera en la Criminología, porque son
muchas y controvertidas las concepciones que se sustentan sobre el d elitoy el delincuente.
Cuatro respuestas son paradigmáticas: la Clásica, la Positivista, la Correccionalista y la Mar-
xista:
El Mundo Clásico partió de una imagen sublime, ideal, del ser humano como centro del
universo, como dueño y señor absoluto de sí mismo, de sus actos. El Dogma de la Liber
tad hace iguales a todos los hombres (sin diferencias entre el hombre delincuente y no
delincuente) y fundamenta la responsabilidad: el absurdo comportamiento delictivo
solo puede comprenderse como consecuencia del mal uso de la libertad en una concreta
situación, no a pulsiones internas ni a influencias externas. El crimen, pues, hunde sus
raíces en un profundo misterio o enigma. Para los Clásicos, el delincuente es un pecador
que optó por el mal, pudiendoy debiendo haber respetado la ley.
El Positivismo Criminológico por el contrario, destronaría al hombre, privándole de su centro
y de su reinado, al negarel libérrimo control del mismo sobresus actosy su protagonismo
en el mundo natural, en el universo y en la historia. El hombre, según Ferri no es el rey de
la Creación, como la tierra no es el centro del universo, sino una combinación transitoria,
una combinación química que puede lanzar rayos de locura y de criminalidad. El Positi
vismo Criminológico inserta el comportamiento del individuo en la dinámica de causas
y efectos que rige el mundo natural o el mundo social: en una cadena de estímulos y res
puestas, determinantes internos (biológicos) o externos (sociales), explican su conducta.
Para el Positivismo Criminológico, el infractores un prisionero de su propia patología (de-
terminismo biológico) o de procesos causales ajenos al mismo (determinismo social): un
esclavo de su herencia, encerrado en sí, incomunicado de los demás, que mira al pasadoy
sabe, fatalmente escrito, su futuro: un animal salvajey peligroso.
