6. VICTIMOLOGÍA
Antecedentes históricos: En los 70 del siglo XX, los estudios individuales de las víctimas de
delitos específicos, populares en las primeras etapas de la victimología, fueron eclipsados por
las encuestas de victimización a gran escala que transformaron el micro enfoque en un macro
enfoque.
El objetivo principal de estas encuestas era determinar el volumen de la victimización, para
identificar a la población víctima, y para establecer las características socio-demográficas de
las víctimas de delitos. Si bien este enfoque macro demostró ser muy útil para el estudio de las
tendencias y patrones de victimización, y para el análisis de la distribución espacial y social de
algunos tipos de delitos, el mismo reveló muy poco sobre las situaciones socialesy personales
en las que tuvieron lugar estos delitos. Era de un valor limitado para la comprensión de la psico
y sociodinámica del comportamiento criminal, el proceso de selección de las víctimas, las in
teracciones entre víctim asy delincuentes, el papel dinámico de la víctima en diversos delitos,
y así sucesivamente.
De la victimología teórica a la victimología aplicada: En los últimos veinticinco años, la vic
timología ha sufrido una gran transformación. La victimología temprana era fundam ental
mente teórica, preocupada casi exclusivamente por las explicaciones causales del delito y el
papel de la víctima en esas explicaciones. Se centró principalmente en las características de las
víctimas, sus relaciones e interacciones con sus victimarios, y el análisis de la conducta de la
víctima como una variable situacional, como un factor desencadenante, actualizante o preci
pitante. Este marco teórico, propuesto por Von Hentig, guio la investigación pionera realizada
por Ellenberger, Wolfgang, Amir, Normandeau, Curtís, Silverman y Fattah entre otros. La pre
ocupación por la difícil situación de las víctimas de delitos se podía encontrar principalmente
en los modestos programas de indemnización estatal a las víctimas de delitos que se estable
cieron en algunos países como Nueva Zelanda, Inglaterra, Canadá y los EE.UU. El redescubri
miento de las víctimas de delitos, encabezado por el movimiento feminista, un movimiento
que defendió la causa de las víctimas de violación, asalto sexual y violencia doméstica, generó
una gran cantidad de empatia y simpatía hacia un grupo largo tiempo privado de sus dere
chos.
La victimología teórica se convirtió en objeto de ataques injustificados y críticas ideológicas
sin fundamento. Fue interpretada por algunos (Clarky Lewis, 1977) como “el arte de culpar a
la víctima". Fue tomando forma un nuevo enfoque para la victimología: ayudar y asistir a las
víctimas de delitos, aliviar su penosa situación y afirmar sus derechos. Nació un movimiento
político y la victimología fue cada vez más definida y reconocida a través de su componente
