aplicado. Los encuentros de Victimología reflejaban la transformación de la victimología des
de una disciplina académica en un movimiento humanista, el paso de la investigación aca
démica al activismo político. Estas reuniones a menudo se convirtieron en plataformas para
la defensa en favor de las víctimas. Esta transformación de la victimología tuvo serias im pli
caciones. Una de las consecuencias fue la de reorientar el concepto de la crim inalidad sobre
los delitos convencionales que tenían una víctima directa, inmediata, tangible. Los delitos de
cuello blanco, acciones corporativas que causan graves daños sociales, legalmente definidas o
no como delitos, fueron una vez más relegadas a un segundo plano. La metamorfosis también
tuvo un impacto negativo en la política criminal. Ayudó a reforzar primitivas reacciones venga
tivas frente a la delincuenciay dio mucho fuelle a los políticos conservadores, permitiéndoles
en consecuencia poner en práctica su agenda punitiva.
Victimología en la actualidad: La victimología hoy es muy diferente de la victimología en
los años 50 o 60 del s. XX. Las disciplinas científicas experimentan una constante evolución,
aunque el ritmo de cambio puede variar de una disciplina a otra. La Victimología ha expe
rimentado una evolución no sólo rápida sino también más fundamental en las dos últimas
décadas. Las décadas de los años 80 y 90 podrían fácilmente describirse como un período
de consolidación, recopilación de datos y teorización, con nueva legislación, compensación a
las víctimas, reparación y mediación, ayuda, asistencia y apoyo para posibilitar a las víctimas
recuperarse de los efectos negativos de la victimización.
Modelos teóricos: La riqueza de los datos recogidos principalmente a través de las encuestas
de victimización ha dado lugar a diversas formulaciones teóricas. Los modelos han sido de
sarrollados para ofrecer explicaciones plausibles de las variaciones en los riesgos de victim i
zación y de la agrupación de la victimización en determinadas zonas y determinados grupos.
También han ayudado a desentrañar el fenómeno intrigante de repetición de la victimización.
Uno de los primeros y más importantes modelos que explican los riesgos diferenciales de
victimización es el estilo de vida desarrollado por Hindelang, Cottfredson y Carofalo (1978). Este
modelo postula que la probabilidad deque un individuo sufra una victimización personal de
pende en gran medida del estilo de vida. Usar el estilo de vida para explicar las variaciones
en el riesgo no es ni un enfoque nuevo ni único. Se ha sabido durante mucho tiempo que la
probabilidad de muerte o lesión accidental está en muchos aspectos relacionada con el estilo
de vida de la población y el tipo de actividades en las que están involucrados. Los médicos han
insistido en la estrecha relación entre el estilo de vida y las actividades de rutina y el riesgo
de padecer ciertas enfermedades como el cáncer de pulmón y de piel, alta presión arterial y
enfermedades cardiovasculares, cirrosis hepática, SIDA, etc. Como una cuestión de hecho, el
concepto de estilo de vida impregna las explicaciones dadas para la mayor o menor suscep
tibilidad a una amplia variedad de enfermedades. La creencia de que el estilo de vida puede
influir en la probabilidad de victimización aumentando o disminuyendo las probabilidades
de convertirse en víctimas de ciertos delitos de la gente puede ser vista como una extensión
lógica de este concepto a la esfera social.
Otro modelo explicativo es el Enfoque de la Actividad Rutinaria desarrollado por Cohén y Felson
(1979)- El énfasis en el enfoque de Cohén y Felson está en “violaciones predatorias de contacto
directo”, que son aquellas “que implican contacto físico directo entre al menos un delincuente
