factores facilitadores.
Los modelos de estilo de vida y actividades rutinarias no son de ningún modo los únicos. Tam
bién está el modelo de oportunidad (Cohén et al., 1981) y el Modelo holandés (Van D ijky Steinmetz,
sin fecha). El modelo de oportunidad incorpora elementos de los dos anteriores y postula que
el riesgo de victimización delictiva depende en gran medida del estilo de vida de las personasy
actividades rutinarias que les ponen aellosy/osus bienes en contacto directo con los posibles in
fractores en ausencia de vigilancia adecuada. El Modelo holandés fue desarrollado porVan Dijky
Steinmetzy sugiere tres factores principales: la proximidad, el atractivo y la exposición como los
determinantes más importantes de los riesgos diferenciales de victimización.
1 . D E F IN IC IO N
Considerada como una disciplina técnico científico, jurídico y metodológico que integra las di
ferentes áreas del saber científico aplicables a la investigación a fin de establecer por el estudio
y/o análisis de los indicios o evidencias, el móvil, las pruebas, las circunstancias y los medios
empleados para su ejecución, del delito, así como la identificación del autor o autores.
La criminalística es la ciencia forense que estudia el delito como conducta humana y social,
investiga las causas de la delincuencia, de la prevención del delito y del tratamiento del de
lincuente. Realizando tales actividades a nivel de la administración de la justicia, el campo
penitenciarioy la prevención del delito.
2 . P R IN C IP IO S D E L A C R IM IN A L ÍS T IC A
La criminalística aplica siete principios fundamentales los cuales son el de uso, de producción,
de intercambio, de correspondencia de características, reconstrucción de hechos y fenóme
nos, de probabilidad y de certeza, estos realizados de una manera óptim a nos ayudaran a co
nocerá él o los responsables de dicho actoy derivara en una dinámica que nos acerque más a
conocer como en realidad sucedió el hecho que se está investigando,
a) Intercambio o transferencia recíproca: Este principio cuya paternidad se le atribuye al
Criminalista francés Dr. Edmundo Locard (1877-1966), plantea que cuando dos cuerpos “A”
y "B" interactúan, se produce un contacto inevitable entre dos elementos distintos, lo cual
necesariamente genera una transferencia de elementos materiales, en muchos casos una
transferencia mutua o intercambio, de evidencias físicas tangibles o intangibles.
Cuando se comete un delito ocurre un choque inevitable de elementos contrarios, se pro
duce un intercambio de indicios materiales y evidencias físicas. Estos elementos contra
